  @override
  String get nicotinePouchesReferenceDay1 =>
      'پہلا دن: نکوٹین کی دستبرداری شروع ہوتی ہے\n\nماخذ: McLaughlin, Dani & De Biasi — Nicotine Withdrawal\n\nنکوٹین والے مصنوعات کے طویل استعمال کے بعد دستبرداری کے جائزے کے مطابق، دستبرداری کی علامات چھوڑنے کے 4–24 گھنٹے بعد شروع ہو سکتی ہیں۔ اسی لیے پاؤچ کے بغیر پہلا دن ایک حقیقی جسمانی سنگِ میل ہے۔\n\nاس کے بعد کیا ہوتا ہے\nعلامات عموماً تیسرے دن کے قریب عروج پر پہنچتی ہیں اور پھر اگلے 3–4 ہفتوں میں کم ہوتی ہیں۔ شدت اس بات کے مطابق مختلف ہو سکتی ہے کہ نکوٹین کس طرح استعمال کی جاتی تھی، اس لیے ہر شخص کا تجربہ مختلف ہو سکتا ہے۔';

  @override
  String get nicotinePouchesReferenceDay3 =>
      'تیسرا دن: نکوٹین کی دستبرداری کا عروج\n\nماخذ: McLaughlin, Dani & De Biasi — Nicotine Withdrawal\n\nیہ جائزہ طویل نکوٹین استعمال بند کرنے کے بعد معمول کی دستبرداری کے عروج کو تقریباً تیسرے دن رکھتا ہے۔\n\nیہاں سے آگے\nعروج کے بعد علامات عموماً اگلے 3–4 ہفتوں میں کم ہوتی ہیں۔ جائزہ یہ بھی بتاتا ہے کہ شدت نکوٹین کے استعمال کے طریقے کے مطابق بدلتی ہے، اس لیے درست شدت ہر فرد میں مختلف ہو سکتی ہے۔\n\nتیسرا دن محنت سے حاصل کیا ہوا سنگِ میل ہے: آپ ابتدائی دستبرداری کے معمول کے منحنی کی چوٹی تک پہنچ گئے ہیں۔';

