  @override
  String get nicotinePouchesReferenceDay7 =>
      'ایک ہفتہ: ترک کی علامات کم ہو رہی ہیں\n\nماخذ: McLaughlin, Dani & De Biasi — Nicotine Withdrawal\n\nجائزے کے مطابق نکوٹین والی مصنوعات کے طویل استعمال کو روکنے کے 4–24 گھنٹے بعد ترک کی علامات شروع ہو سکتی ہیں، تقریباً تیسرے دن عروج پر پہنچتی ہیں، اور پھر اگلے 3–4 ہفتوں میں کم ہوتی رہتی ہیں۔\n\nایک ہفتے کی حقیقی کامیابی\nایک ہفتے پر آپ عام چوٹی سے کئی دن آگے اور علامات کے کم ہونے والے مرحلے میں ہوتے ہیں۔ جائزہ یہ بھی بتاتا ہے کہ ترک کی شدت اس بات سے مختلف ہو سکتی ہے کہ نکوٹین کس طریقے سے لی جاتی تھی، اس لیے ہر شخص میں شدت ایک جیسی نہیں ہوتی۔\n\nنکوٹین پاؤچ کے بغیر ایک ہفتہ اس بات کی علامت ہے کہ ابتدائی ترک کے عام منحنی کا سب سے تیز حصہ پیچھے رہ چکا ہے۔';

  @override
  String get nicotinePouchesReferenceDay14 =>
      'دو ہفتے: علامات مسلسل کم ہو رہی ہیں\n\nماخذ: McLaughlin, Dani & De Biasi — Nicotine Withdrawal\n\nجائزہ نکوٹین ترک کرنے کی عام چوٹی تقریباً تیسرے دن بتاتا ہے اور کہتا ہے کہ علامات اگلے 3–4 ہفتوں میں کم ہوتی رہتی ہیں۔\n\nکمی والے مرحلے میں کافی آگے\nدو ہفتوں پر آپ چوٹی کے بعد علامات کم ہونے والے مرحلے میں کافی آگے آ چکے ہوتے ہیں۔ یہ جائزہ نکوٹین والی مصنوعات کے طویل استعمال کا احاطہ کرتا ہے اور بتاتا ہے کہ ترک کی شدت نکوٹین لینے کے طریقے کے لحاظ سے مختلف ہوتی ہے۔\n\nنکوٹین پاؤچ کے بغیر دو ہفتے نیچے جاتے منحنی پر ایک واضح سنگ میل ہیں: عام ترک کی علامات مسلسل کم ہو رہی ہیں۔';

