  @override
  String get adderallReferenceDay1 =>
      'اِس شمارے میں سے . . .\n\nماخذ: MedlinePlus (U.S. National Library of Medicine)\n\nاِس شمارے میں سے . .\nایم ڈی ایچ ڈی اور نارکولپسی (جیسے ایڈرل اینڈ ویوانس) کے علاج کے لیے استعمال ہونے والی دوا دونوں ناجائز مواد (جیسے سڑک کی رفتار) اور ادویات شامل ہوتی ہیں ۔ اِن میں سے زیادہ‌تر لوگ دُم‌دار ہیں اور اِن کی وجہ سے اِن میں سے بہت زیادہ توانائی ، توانائی اور توانائی پیدا کر سکتے ہیں ۔ باقاعدہ بھاری استعمال کے ساتھ دماغ بار بار چلنے والی رکاوٹوں سے مطابقت رکھتا ہے لہٰذا روک لینے سے ذہنی سکون ، توانائی اور تحریک عارضی طور پر کم ہو سکتی ہے ۔\n\nعام طور پر سُرخ خلیے\nمیڈلین پلس ان فہرستوں میں ایسے ہی ہیں جیسے کہ جب امپیرین روک رہے ہوں:\n• منشیات کی شدید خواہش\n• ڈپریشن سے نپٹنے کیلئے پریشانی کا باعث بنتے ہیں\n• دن بھر تھکے تھک جاتے ہیں۔\n• وہ توجہ نہیں دے سکتے\n• حلیہ (جو وہاں نہیں ہیں)۔\n• جسمانی ردِعمل جیسے کہ سر درد، چیچک اور درد، بھوک میں اضافہ اور اچھی نیند نہیں سوتے۔\n\nکیا اِس سے کوئی فرق پڑتا ہے ؟\nمیڈلین پلس اپنے آپ میں طبی طور پر خطرناک نہیں بلکہ یہ بیان کرتا ہے کہ شدید علامات زندہ علاج کے پروگرام کے لئے درخواست دے سکتی ہیں اور ڈپریشن سمیت ذہنی اور جذباتی مسائل بھی سنگین ہو سکتے ہیں اور مدد کی ضرورت پڑ سکتی ہے۔\n\nمدد حاصل کرنا\nاگر آپ یا آپ یا آپ جانتے ہیں کہ آپ کا کوئی شخص آپ سے رابطہ کرنا چاہتا ہے تو آپ کو اِسے ختم کرنے میں مدد کی ضرورت ہے ۔ اگر آپ خود غرضی کے خیالات رکھتے ہیں، تو یہ پڑھنے والوں کو ہدایت کرتا ہے کہ وہ 988 یا 911 جیسے بحرانی وسائل کی جانچ پڑتال کریں۔';

  @override
  String get adderallReferenceDay3 =>
      'اِس شمارے میں سے . . .\n\nماخذ: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings,\" World Health Organization (2009), on the NCBI Bookshelf\n\nجہاں ۳ دن کی جگہ\nاِس سلسلے میں ایک کتاب بیان کرتی ہے کہ علامات ” آخری زمانے میں ۲۴ گھنٹے کے اندر اندر اور ۳ تا ۵ دن تک قائم رہتی ہیں ۔ “\n\nاِس شمارے میں\nایم ایم بی سی کی قسم کے رہنماؤں کی فہرست کے لئے:\n• س . ع .\n• ڈپریشن\n• نیند اور تھکاوٹ میں اضافہ\n• مٹی کا رس\nبھاری صارفین پیرانیا جیسے نفسیاتی علامات بھی پیدا کر سکتے ہیں ، جنکی وجہ سے وہ ذہنی طور پر متاثر ہو سکتے ہیں یا پھر وہ خود کو نقصان پہنچا سکتے ہیں ۔\n\nزیادہ‌تر لوگوں کا مسئلہ\nاِس کے برعکس ، شراب‌نوشی یا کسی حد تک خطرناک ہوتی ہے ۔ غالب مشکل نفسیاتی ہوتی ہے یعنی کم مزاج، عیش و عشرت کی کمی اور شوق کی وجہ سے ایک دوپیمین (Dopine-depeleted) دماغ کی طرف سے چلائی جاتی ہے۔\n\nانتظام\nاُن کی رہنمائی کرنے کے لئے ضروری ہے کہ وہ اُن کی مدد کریں :\n• روزانہ کم از کم 2–3 لیٹر پانی پیتے ہیں۔\n• بی گروپ وٹامن اور وٹامن سی کے ساتھ مل‌جُل‌جُلُوِیّین کے مرکبات\n• چیچک اور پریشانی کے لیے symptomatic دوا ہے۔\n• شدید اذیت کے لئے ، چال‌چلن سب سے پہلے ، دیسیپم کے ساتھ ضرورت پڑنے کے لئے\n\nع . کے دہے سے باہر\nاِس سلسلے میں ایک مثال پر غور کریں ۔';

  @override
  String get adderallReferenceDay7 =>
      'ایک ہفتہ بے اِدار : دُنیا کا خاتمہ نزدیک ہے\n\nماخذ: Li & Shoptaw, \"Clinical Management of Psychostimulant Withdrawal: Review of the Evidence,\" Addiction (2023), on PubMed Central\n\nاِس سے ظاہر ہوتا ہے کہ اِس بیماری کی وجہ سے اُن کی صحت پر اچھا اثر پڑتا ہے ۔\nاِس سلسلے میں ایک مثال پر غور کریں ۔ مشکل مرحلے میں علامات \'پیک کے بعد پہلے 2–3 دن‘ اور \'مریخ پر تکلیف عام طور پر 4–7 دن کے اندر حل ہوتی ہے‘۔ پہلی ہفتے کے اختتام تک حادثے کا مشکل ترین حصہ زیادہ تر لوگوں کے پیچھے ہوتا ہے یعنی توانائی اور توانائی مستقل ہونا شروع ہو جاتی ہے اور نیند کا انتظام کرنا شروع ہو جاتا ہے۔\n\nاسکے بعد کیا واقع ہوتا ہے\nاس جائزے میں بتایا گیا ہے کہ زیادہ‌تر علامات اگلے دو سے تین ہفتوں پر محیط رہتی ہیں ۔ سات دن پہلے ہی بحالی کا کام جاری ہے ۔\n\nاب بھی 7 دن پر موجود ہے۔\nجسم کے حادثے کو کم کرنے والی علامات :\n• کم حوصلہ افزائی اور عیش و آرام کی کمی ہے۔\n• مایوسی\n• مودود جو اب بھی حسب معمول ہے۔\nیہ ایک دوامین سسٹم کی عکاسی کرتے ہیں جو بحال کر رہا ہے — ایک معمول اور عارضی بحالی کا حصہ ہے ۔\n\nدوبارہ سے نشانات کو صاف کریں\nکوئی بھی ایف ڈی این اے سے لگنے والی دوا خاص طور پر اسمعیلنٹ کو روکنے کا علاج کرتی ہے، لہذا معاون دیکھ بھال، ترکیب، نیند، خوراک اور نفسیاتی امداد اس مرحلے کے ذریعے بنیادی طور پر معاون ثابت ہوتی ہے۔';

  @override
  String get adderallReferenceDay14 =>
      'دو ہفتے کے بعد اُس نے اُس کے ساتھ کام کرنا چھوڑ دیا ۔\n\nماخذ: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings,\" World Health Organization (2009), on the NCBI Bookshelf\n\nاِس سے ظاہر ہوتا ہے کہ اُس کا ایمان مضبوط تھا ۔\nاِس کے بعد اُس نے ایک دن تک نرم‌مزاجی سے کام لینا شروع کر دیا ۔ دو ہفتوں میں، تباہی آپ کے پیچھے ہے.\n\nاُس نے کہا : ” مَیں نے اِس بات کو تسلیم کِیا کہ مَیں یہوواہ خدا سے دُعا کرتا ہوں ۔\nاسکی وجہ یہ ہے کہ اِن میں سے زیادہ‌تر لوگ نیند سوتے ہیں اور اِن میں سانس لیتے ہیں ۔ جو چیز عام طور پر حلیم ہوتی ہے: کم یا تبدیل شدہ مزاج، تحریک میں کمی اور دماغ کے اجرا کے نظام کے طور پر رکاوٹوں کے طور پر۔\n\nنیند اور تجسّس\nاِس کی وجہ یہ ہے کہ زیادہ‌تر لوگ نیند سوتے ہیں اور اِن میں سے زیادہ دیر تک سوتے رہتے ہیں ۔ جب نیند پوری ہو جاتی ہے تو اُس کا مزاج ، مزاج اور توانائی اِس کی پیروی کرنے لگتے ہیں ۔\n\nدہشت‌گردی اور ڈی‌ہ‌ہ‌ڈی\nیہ ابھی تک ایک اعلٰی ترین مدت ہے، خاص طور پر اگر زیر علاج ADHD کی علامات میں سے کسی کو دوا کے بغیر واپس کر دیا جائے۔ ڈرون رہنماؤں نے نفسیاتی حمایت اور دوبارہ پیدا ہونے والی صلاحیتوں پر زور دیا؛ جو لوگ Aderall for ADHD کے لیے کام کرتے ہیں، ان لوگوں کے لیے یہ اچھا وقت ہے کہ وہ کسی ڈاکٹر کے ساتھ غیر جذباتی یا متبادلات پر گفتگو کریں۔';

  @override
  String get adderallReferenceDay30 =>
      'اِس سلسلے میں ایک مہینے کا وقفہ : زیادہ‌تر لوگ آپ کے پیچھے پیچھے چلتے ہیں ۔\n\nماخذ: Li & Shoptaw, \"Clinical Management of Psychostimulant Withdrawal: Review of the Evidence,\" Addiction (2023), on PubMed Central\n\nجہاں ایک ماہ کی چھٹی ہوتی ہے\nاس جائزے سے پتہ چلتا ہے کہ پہلے دو سے تین ہفتوں کے دوران علامات ختم ہو جاتی ہیں ۔ 30 دن تک ، ان میں سے زیادہ‌تر لوگوں نے آسانی اور جذبے اور تحریک کو پہلے ہفتے کی نسبت زیادہ بہتر خیال کِیا ہے ۔\n\nبعدازاں دوبارہ دوبارہ تعمیر کئے جانے والے نقش\nایک سے چھ ماہ تک یادو، منصوبہ بندی، توجہ اور فیصلہ سازی کا سلسلہ جاری رہتا ہے۔ ایک مہینے میں ، تباہی ختم ہو گئی ہے اور جو منافع پہلے ہی سے جاری ہے ۔\n\nمُلک اور تحریک\nحادثے سے لطف اندوز ہونے کا گہرا نقصان اب تک بڑی حد تک اٹھایا جا چکا ہے۔ پہلے ہفتے میں خوشی حاصل کرنے والی کامیابیوں نے پھر سے کامیابی حاصل کرنا شروع کر دی ۔\n\nاُن لوگوں کے لئے جو اِس بیماری میں مبتلا ہیں\nاگر ADHD کے لئے ایڈرل کا حکم دیا گیا تھا تو اس وقت زیرِزمین علامات زیادہ خطرناک ہو سکتی ہیں ۔ اس مرحلے کے دوران صحت کی دیکھ بھال فراہم کرنے والے کے ساتھ کام کرنا بہت ضروری ہے۔';

  @override
  String get adderallReferenceDay60 =>
      'دو ماہ کی تاخیر ایدارل : دو ماہ کی تاخیر کی وجہ سے پُراسرار ہوا ہوا ہو جاتی ہے۔\n\nماخذ: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings,\" World Health Organization (2009), on the NCBI Bookshelf\n\nجہاں دو ماہ کی چھٹیاں ہوتی ہیں۔\nجی‌ہاں ، ابتدائی تباہی کے دو ماہ بعد ایک نرم‌مزاج شخص کی بحالی کا دَور بیان کرتا ہے ۔ آپ ۶۰ دن کے بعد اس کھڑکی کے اختتام پر ہیں اور اس کی علامات بڑی حد تک حل ہو رہی ہیں ۔\n\nاِن سوالوں پر غور کریں\nزیادہ‌تر لوگوں کیلئے مایوسی ، مایوسی اور نیند کی وجہ سے پریشان‌کُن بات‌چیت کرنے والے اصولوں کی فہرست میں اضافہ ہو رہا ہے :\n• ابتدائی بحالی کی کم‌ازکم علامات کے ساتھ ہمارا ذہنی رُجحان متبادل ہوتا ہے\n• نیند اور مزاج میں نارمل پن پایا جاتا ہے۔\n• انعام کا نظام روزمرّہ زندگی کی عیش‌وعشرت — خوراک ، ورزش ، رابطہ — کو زیادہ خوشی سے قبول کرتا ہے\n\nدوبارہ سے نشانات کو صاف کریں\nاِس کے علاوہ اِس بات پر بھی غور کریں کہ اُن کی سوچ کیا ہے ۔\n\nجسمانی صحت\nروزمرّہ زندگی سے نشہ‌آور ادویات کو صاف کرنے سے دل کی دھڑکن ، بھوک اور وزن پر اثر پڑتا ہے ۔';

  @override
  String get adderallReferenceDay90 =>
      'تین ماہ بعد اِس مسئلے کو حل کرنے کے لئے تیار رہیں : جنگ میں کامیابی\n\nماخذ: Li & Shoptaw, \"Clinical Management of Psychostimulant Withdrawal: Review of the Evidence,\" Addiction (2023), on PubMed Central\n\nجہاں 90 دن کی چھٹیاں ہوتی ہیں۔\nتین ماہ میں ابتدائی علامات طویل عرصے سے ختم ہو جاتی ہیں جب کہ یادداشت، منصوبہ بندی، توجہ، فیصلہ سازی اور اجرت کا نظام بہتری کا باعث بنتا رہتا ہے۔\n\nسوچنے اور یاد کرنے میں پہل کریں\nاس جائزے سے پتہ چلتا ہے کہ یادداشت ، منصوبہ بندی ، توجہ اور خطرے کے فیصلے مہینوں تک بہتری لا سکتے ہیں ۔ 90 دن تک جاری رہنے کے ساتھ ساتھ مرکزیت اور یادو اب بھی درست سمت میں منتقل ہو رہے ہیں۔\n\nیہ ونڈوز اب تک کیوں معاملات ہیں\nکوئی بھی ایف ڈی این اے سے لگنے والی دوا خاص طور پر سٹیملنگ کو نشانہ بناتی ہے، لہذا اس مرحلے کے ذریعے بحالی، معالجہ، ورزش، نیند اور معاونت وہ آلات ہوتے ہیں جو اس مرحلے کے ذریعے انجام دیتے ہیں۔ اِن عادات کو فروغ دینے کے لئے ہمیں کیا کرنا چاہئے ؟\n\nبِھیڑ کی تصویر\nتین ماہ کی ایک حقیقی کامیابی ہے — سب سے مشکل جسمانی اور جذباتی پس‌منظر آپ کے پیچھے ہے اور یہاں سے مستقل طور پر آذربائیجان کیساتھ رہنے والی چیونٹی مسلسل بہتری کا باعث بنتی ہے ۔';

  @override
  String get adderallReferenceDay180 =>
      'چھ ماہ بعد ابی‌سلوم : مشکل کا سامنا کریں\n\nماخذ: \"Withdrawal Syndromes,\" StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nس . ع .\nاِس میں اِس بات کا ذکر کِیا گیا ہے کہ اِس حادثے کی وجہ سے اِس میں بہتری آ رہی ہے ۔ عام مسائل میں ڈپریشن، نیند بہت زیادہ، بھوک، کم مزاج اور بے چینی حرکت اور سوچ شامل ہیں۔ ڈپریشن کئی ہفتوں تک برقرار رہ سکتا ہے جس میں نرم‌مزاجی سے بہتری آتی رہتی ہے ۔\n\nجہاں چھ ماہ کی چھٹی نشستیں ہیں۔\nچھ مہینوں میں آپ دونوں کو بہت عرصہ گزر چکا ہے اور کئی ہفتوں کے دوران اسٹیج پر آنے والے مرحلے کو بیان کرتے ہیں۔ اِس کی وجہ یہ ہے کہ اِس میں آہستہ آہستہ تبدیلی آنے کا وقت آ گیا ہے ۔\n\nدوبارہ سے نشانات کو صاف کریں\nابتدائی ہفتوں سے آگے آہستہ آہستہ آہستہ آہستہ آہستہ آہستہ ایک بار پھر سے گزرنے لگتا ہے ۔ چھ ماہ تک، تباہ کن شکست اور کئی ہفتے کے طویل مرحلے آپ کے پیچھے بہت پیچھے ہیں، مستحکم مزاج، نیند، بھوک اور تحریک اب غالب نمونہ ہے.\n\nایک دوسرے سے دوستی کریں\nاے ڈی ایچ ڈی کے لیے ایڈرل لے جانے والے لوگوں کے لیے چھ ماہ کی طویل علالت سے حالیہ علامات کے ڈاکٹر کے ساتھ واضح جائزہ لینا ایک اچھا نقطہ نظر ہے اور اگر غیر stimulant نزدیک آئے تو ورزش، نیند، ترکیب، علاج یا متبادل دوا آپ کی ضروریات پوری کر رہی ہیں۔';

  @override
  String get adderallReferenceDay365 =>
      'ایک سال خارجی ادارل: زیر انتظام بحالی، غیر منظم فریدہ ہے۔\n\nماخذ: Berman et al., \"Potential Adverse Effects of Amphetamine Treatment on Brain and Behavior: A Review,\" Molecular Psychiatry (2008), on PubMed Central\n\nاس شمارے کے بارے میں\nیہ تجزیاتی دائرۃ المعارف (high-dose) یا طویل مدتی امیگریشن شعاعیں دماغ اور دستاویزات کی بحالی کے دوران میں انجام دے سکتی ہیں۔\n\nصفائی کے بارے میں کیا کہا جاتا ہے\nدماغ میں خون کی گردش میں ہونے والی تحقیقی دستاویزوں کی بحالی اور پروٹین میں جو لمبے عرصے کے بعد دوپمین کو جذب کرتے ہیں۔ کچھ دماغ کے کچھ علاقے دوسروں کی نسبت تیزی سے بڑھتے چلے جاتے ہیں لیکن مجموعی سمت واضح ہے: استعمال کرنے کے بعد دماغ شفا پاتا ہے۔\n\nلمبے عرصے تک سرمائیہ دار\nجائزہ لینے والی دستاویزات دماغ کے خون کے بہاؤ اور دور دراز کے بعد ڈبلین ری سائیکل کی بحالی۔ ایک سال میں ان دماغی نظاموں کو دوبارہ تعمیر کرنے کا پورا سال حاصل ہو گیا ہے۔\n\nایک سال میں اس کا کیا مطلب ہے ؟\nبہتیرے لوگوں کیلئے — بالخصوص تفویض‌شُدہ کام کرنے والے — ایک سال کے لئے انعام ، توجہ اور تحریک کے نظام کا مفہوم پیش کرنے والے لوگ دن‌رات کام کر رہے ہیں ۔ ہیویر یا زیادہ سے زیادہ استعمال کرنے سے زیادہ وقت لگ سکتا ہے لیکن بحالی جاری رہتی ہے۔ ابتدائی بحالی کے مقابلے میں دوبارہ پیدا ہونے والا خطرہ بہت کم ہوتا ہے ۔';

  @override
  String get alcoholReferenceDay1 =>
      'جب آپ شراب پینا بند کرتے ہیں تو نیند کیلئے کیا واقع ہوتا ہے ؟\n\nماخذ: \"Alcohol and the Sleeping Brain\" (Colrain, Nicholas & Baker), Handbook of Clinical Neurology — peer-reviewed, NIH-hosted\n\nشراب اور نیند کے آثار\nشراب نوشی کا شکار ہو جاتی ہے اس لیے یہ وقت کم ہو جاتا ہے کہ سو جائے اور رات کے ابتدائی نصف حصے میں گہرے سستے سو جائے۔ لیکن یہ ایک حد تک واقع ہوتا ہے : الکحل کی کمیت ( آنکھوں کی حرکت ) نیند — ذیابیطس اور جذباتی رُجحانات سے جڑ جاتی ہے — اور رات کے دوسرے نصف حصے میں نیند سو جاتی ہے ۔\n\nشراب کی پہلی رات\nاِس کی وجہ یہ ہے کہ شراب‌نوشی کرنے والے لوگ نیند سوتے ہیں ۔ یہ بحالی کا عام، عارضی حصہ ہے.\n\nدوبارہ سے کوشش\nدماغ اگلے دنوں اور ہفتوں کے دوران تازہ‌دم ہو جاتا ہے ۔ نیند کے امراض سے متعلقہ علامات میں سے ایک ہے، لیکن یہ عام طور پر زچگی کے ساتھ جڑے رہنے والی علامات کی طرف راغب ہوتا ہے۔\n\nحد سے زیادہ شراب پینے پر غور کریں\nبھاری یا طویل عرصے تک روزانہ پینے کے لیے پہلا 24 گھنٹے بعد آنے والی علامات (انگریزی: Exsety, پسینہ، زلزلے، جھٹکے وغیرہ) بھی لا سکتے ہیں۔ اگر آپ ہر روز حد سے زیادہ شراب پیتے ہیں تو ڈاکٹر سے بات کریں ۔';

  @override
  String get alcoholReferenceDay3 =>
      'تیسرا دن: ودڈرال کے عروج کا مرحلہ\n\nماخذ: \"Alcohol Withdrawal\"، StatPearls — ہم مرتبہ جائزہ شدہ، NIH National Library of Medicine\n\nتقریباً 72 گھنٹے\nالکحل ودڈرال کی علامات چند گھنٹوں میں شروع ہو سکتی ہیں اور اکثر تقریباً 72 گھنٹوں میں عروج پر پہنچتی ہیں۔ StatPearls کپکپی، بے خوابی، بے چینی، پسینہ، بلند فشارِ خون، تیز دھڑکن اور دوروں کو اس شدید اعصابی تحریک کی علامات میں شمار کرتا ہے۔\n\nتین مضبوط دن\n72 گھنٹوں تک پہنچنا ایک بڑی منزل ہے کیونکہ یہ بہت سی شدید علامات کے دستاویزی عروج کے عین درمیان آتا ہے۔\n\nشدید ودڈرال بعد میں بھی آ سکتا ہے\nالکحل ودڈرال دلیریئم (delirium tremens) شراب چھوڑنے کے 3–8 دن بعد ہو سکتا ہے اور جان لیوا بھی ہو سکتا ہے۔ شدید ودڈرال طبی ہنگامی حالت ہے۔ جو لوگ روزانہ بہت زیادہ پیتے ہیں، یا جنہیں پہلے ودڈرال کے دورے یا دلیریئم ہو چکے ہیں، انہیں بغیر مدد اچانک چھوڑنے کے بجائے طبی مشورہ لینا چاہیے۔';

  @override
  String get alcoholReferenceDay7 =>
      'نظامِ‌شمسی کیسے بحال کرتا ہے\n\nماخذ: \"Alcohol and the Immune System\" (Sarkar, Jung & Wang), Alcohol Research: Current Reviews — peer-reviewed, NIH-hosted\n\nشراب میں کیا خرابی ہے ؟\nشراب کئی طریقوں سے مدافعتی نظام کو کمزور کرتی ہے ۔ ایک بھاری مشروب بھی 24 گھنٹے تک انفیکشن کی صلاحیت کو کم کر سکتا ہے۔ لمبے عرصے کے استعمال سے خون کے سفید خلیوں کو کم کیا جاتا ہے، مدافعتی اشاروں کو نقصان پہنچتا ہے اور پھیپھڑوں اور پھیپھڑوں کے دفاعی نظام کو نقصان پہنچتا ہے جس سے انفیکشن کا خطرہ بڑھ جاتا ہے اور سستے زخموں کی جراحی کا خطرہ بڑھ جاتا ہے۔\n\nاِس کی کیا وجہ ہے ؟\nاِن میں سے بہت سے اثرات شراب چھوڑنے کے بعد بہتر ہوتے ہیں ۔ سفید خون کے خلیات اور مدافعتی سگنلز کی مرمت شروع ہو جاتی ہے جبکہ گوتم اور ہوائی دفاعی نظام کی مرمت شروع ہو جاتی ہے۔ پہلے ہفتے کے اندر اندر آپکا مدافعتی نظام روزانہ دب نہیں جا رہا ہے اور عام انفیکشن کے خلاف مزاحمت شروع ہو رہی ہے ۔\n\nایک بڑی تبدیلی\nاِس کے علاوہ اِس بات پر بھی غور کریں کہ شراب پینے میں کتنا وقت لگتا ہے ۔';

  @override
  String get alcoholReferenceDay14 =>
      'اِس کے نتیجے میں دماغ کا دماغ اِس بیماری میں مبتلا ہو جاتا ہے ۔\n\nماخذ: Bartsch AJ et al., \"Manifestations of early brain recovery associated with abstinence from alcoholism,\" Brain (2007) — peer-reviewed\n\nدوبارہ تعمیر کرنا\nاس تحقیق نے حال ہی میں شراب کے پہلے ہفتوں کے دوران شراب پر انحصار کرنے والے لوگوں کو صحت‌مند کنٹرول سے تشبِیہ دیتے ہوئے استعمال کِیا ۔ اس نے ایک مرتبہ پھر سے دوبارہ پینے کے بعد دماغ پر قبضہ کر لیا ۔\n\nدماغ کی جِلد میں تبدیلی\nاِس کی وجہ یہ ہے کہ اِس بیماری میں مبتلا لوگوں کی صحت خراب ہو جاتی ہے اور اِس وجہ سے اُن کی صحت خراب ہو جاتی ہے ۔ ابجد کے ساتھ محققین نے تقریباً 2% کی اوسط عالمی دماغ-volume حاصل کرنے کا اندازہ لگایا، اس کے ارد گرد کی فضاء، وسط عرض البلد اور پیش کش علاقوں کا احاطہ کیا گیا۔ اِن میں سے زیادہ‌تر لوگ اِس بات پر یقین رکھتے ہیں کہ خدا اُن کی مدد کرے گا ۔\n\nتوجہ اور توجہ\nریکی خاص طور پر حرکت اور توجہ کے لیے استعمال ہونے والے دماغی شعبوں میں واضح تھی۔ دماغ کے خلیات کی صحت کا ایک نشان توجہ کے ساتھ ساتھ بہتر بہتری کے ساتھ سامنے آیا، اس لیے جسمانی معالجے میں حقیقی کامیابی حاصل ہوئی۔\n\nایک فاؤنڈیشن ، بینظیر بھٹو کی بجائے\nاِس سے ظاہر ہوتا ہے کہ اِس بیماری کی وجہ سے دماغ جلدازجلد تندرست ہو جاتا ہے ۔';

  @override
  String get alcoholReferenceDay30 =>
      'جب آپ شراب پینا چھوڑ دیتے ہیں تو خون پر دباؤ بڑھتا ہے\n\nماخذ: Roerecke et al., \"The effect of a reduction in alcohol consumption on blood pressure: a systematic review and meta-analysis,\" Lancet Public Health (2017) — peer-reviewed\n\nثبوت\nاس میٹا analysis نے 36 حادثاتی امتحانات (تقریباً 2,865 شرکاء) میں یہ جانچنا کہ جب لوگ کم شراب پیتے ہیں تو بلڈ پریشر کے ساتھ کیا واقع ہوتا ہے۔ اس میں واضح پایا گیا، دوسے-اڑنے والا اثر: جتنے بھی شخص نے پیٹھ کاٹ دیا، اتنا ہی زیادہ ان کا بلڈ پریشر گر گیا۔\n\nاسکا اثر کتنا بڑا ہے ؟\nجو لوگ دن میں دو یا اس سے بھی کم شراب پیتے تھے، انہوں نے نہ صرف خون کی ایک خاص تبدیلی دیکھی تھی، بلکہ اس کے نتیجے میں اس میں کوئی تبدیلی نہیں آئی۔ اس سے اوپر، اثر دوا-ڈیپنر تھا: یہ لوگوں میں سب سے مضبوط یا زیادہ مشروبات میں تھا جس نے تقریباً آدھی رات کے وقت ان کا استعمال منقطع کر دیا تھا، جہاں تقریباً 5.5 mmHg اور دیسوٹالک کا دباؤ تقریباً 4.0 mmHg سے گر گیا تھا۔ اس سائز کی کمی کا مطلب ہے — کچھ بلڈ پریشر دواؤں کے مشابہ اور لمبے عرصے تک لگنے والے دورے اور دل کے خطرے کو کم کرنے کے لئے کافی ہے ۔\n\nایک مہینے کا مسئلہ\nاِس طرح اُس کے جسم میں خون کی مقدار بڑھ جاتی ہے ۔ اس جائزے سے حاصل ہونے والی آزمائشوں سے ظاہر ہوتا ہے کہ کئی ہفتوں تک مسلسل کمی واقع ہوتی رہتی ہے — لہٰذا ایک مہینے کے اندر اندر شراب پینے والے کے سخت دباؤ نے صحت‌بخش سطح پر رہنے کا وقت لیا ہے ۔\n\nایک خطرناک اثر\nاس جائزے نے واضح طور پر دیکھا : لوگوں میں دن میں دو سے زیادہ مشروب پینے سے فائدہ اُٹھایا جاتا تھا اور آہستہ آہستہ پہلے کی سب سے بڑی مقدار میں تیزی سے اضافہ ہو جاتا تھا ۔ اگر آپ ہلکی پینے والے تھے تو اس مخصوص بلڈ پریشر کے فوائد کی توقع نہ کریں — لیکن زیادہ شراب پینے والے شخص کو ایک حقیقی اور قابلِ قبول حد تک رکاوٹ بننے سے روک سکتے ہیں۔';

  @override
  String get alcoholReferenceDay60 =>
      'شراب پینا بند کرنے کے بعد زندہ رہنا\n\nماخذ: National Institute on Alcohol Abuse and Alcoholism (NIAAA), \"Alcohol\'s Effects on the Body\"\n\nشراب پینے والے کو کس حد تک نقصان پہنچاتا ہے ؟\nجگر زیادہ‌تر شراب پینے کا عمل کرتا ہے اور یہ نقصاندہ ہو جاتا ہے ۔ AIAA شراب سے متعلقہ جگر کو زخمی کرنے کی ایک بیماری بیان کرتا ہے : یہ چربیی جگر (steatosis — جگر کے خلیوں میں چربی پیدا کرنے والی چربی ) سے شروع ہوتی ہے ، الکحل ہیپاٹائٹس ( انفلمنٹ ) کی طرف پیش قدمی کر سکتی ہے اور لمبے بھاری استعمال کیساتھ فیبرسیس اور جِلد (scaring) تک پہنچ سکتی ہے۔\n\nاس سے پہلے کے دَور میں بڑے بڑےبڑے پتھر پائے جاتے ہیں\nسب سے اہم بات یہ ہے کہ جگر انتہائی خطرناک ہوتا ہے اور اس نقصان کے ابتدائی مرحلے شراب پینے کے بعد بہتر ہو سکتے ہیں۔ خاص طور پر چربی کا جگر باقاعدگی سے اُس بیماری میں حل کرتا ہے جس کی وجہ سے اُس کی صحت خراب ہو جاتی ہے ۔ دو ماہ کے اندر اندر اندر ہی جگر کو چربی کے بخارات ، آرام‌دہ غذاؤں اور دوبارہ صاف کرنے کیلئے حقیقی وقت مل گیا ہے — جو جگر کی سطح ( ایل‌ٹی اینڈ اے‌ٹی ) کو گرنے سے ظاہر ہوتا ہے ۔\n\nلُور سے بھی زیادہ\nاِس کے علاوہ اُس نے شراب پینے سے دل ، پھیپھڑوں اور مدافعتی نظام کو آلودہ کر دیا ہے ۔ اِس کے علاوہ بہت سے لوگ اِس مرحلے کی وجہ سے اِس بیماری میں مبتلا ہو جاتے ہیں ۔';

  @override
  String get alcoholReferenceDay90 =>
      'تین ماہ کے بعد سوچ‌بچار اور یادداشت\n\nماخذ: Systematic review of neuropsychological recovery following abstinence from alcohol (PubMed Central, 2024) — peer-reviewed\n\nاس بات کا کیا ثبوت ہے ؟\nاس جائزے نے مل کر مطالعے کیے جس سے لوگوں کو پینے سے باز آنے کے بعد کس طرح سوچ اور یادداشت بحال ہو جاتی ہے۔ زیادہ‌تر مہارتاں چھ سے بارہ مہینے کے اندر اندر اندر منتقل ہو جاتی ہیں اور بعض پہلے بہتر ہو جاتے ہیں ۔\n\nپہلی بات کیا ہے ؟\nباقی کی نسبت دو مخصوص صلاحیتیں سامنے آتی ہیں: بنیادی کارکردگی کی رفتار (اس جائزے نے تقریباً ایک ماہ تک دوبارہ حاصل کی ہے، اگرچہ زیادہ پیچیدہ کاموں کے پیچھے درست ہے) اور کام میموریل کی کارکردگی کو عمل میں لایا جاتا ہے۔ تین ماہ کے نشان کے آس پاس سے ، بہت سے لوگ پہلے ہی یہ دیکھ لیتے ہیں ۔\n\nاِس کا کیا نتیجہ نکلا ؟\nتوجہ، منصوبہ بندی، فیصلہ سازی، بے قابوی، بصیرت اور یاد داشت چھ ماہ کی بحالی کی کھڑکیوں میں بہتری لاتی رہتی ہے۔\n\nکن اثرات پر قابو پایا جاتا ہے\nاِس سلسلے میں ایک مثال پر غور کریں ۔ اِس مضمون میں ہم کن باتوں پر غور کریں گے ؟ ریکی (انگریزی: Recovery) ایک متوقع trajitory ہے.\n\nیہ کیوں ضروری ہے\nکلیئرر سوچ عملی بحالی ہے: بہتر توجہ اور فیصلہ سازی علاج میں لوگوں کی مدد کرتی ہے اور واپس آنے سے گریز کرتی ہے۔';

  @override
  String get alcoholReferenceDay180 =>
      'سوبریٹی کے چھ مہینے میں دماغ دوبارہ سانس لیتا ہے۔\n\nماخذ: Peer-reviewed review of structural and functional brain recovery during abstinence from substance use (PubMed Central)\n\nدوبارہ کوشش جاری رہتی ہے\nپہلے ہفتوں کے ابتدائی دماغ کی شروعات ہی شروع ہوتی ہے۔ اِس تحقیق سے پتہ چلتا ہے کہ دماغ کے اندر اِس بات کا خیال رکھا گیا ہے کہ وہ اِس بات کا خیال رکھتا ہے کہ اُس کا دماغ اُس کی صحت پر اچھا اثر ڈالے گا اور اِسے دوبارہ بحال کرے گا ۔\n\nدماغ کا اگلا حصہ\nریکی خاص طور پر دماغ کے سامنے اہم ہوتی ہے جو فیصلہ، منصوبہ بندی اور خود قابو میں رکھتی ہے۔ جب یہ شفا بخشتی ہے تو فیصلہ سازی اور منصوبہ بندی کنٹرول کو تقویت ملتی ہے۔\n\nدماغ میں دوبارہ پیدا ہونا اور اِس میں کمی\nجسمانی مرمت کے ساتھ ساتھ دماغ کی کارکردگی اور تعلقات بھی بحال ہو جاتے ہیں ۔ دماغ دوبارہ پیدا کر سکتا ہے جس کی وجہ سے علاج اور نئی عادات کے لئے ایک طاقتور وقت ضائع ہو جاتا ہے ۔\n\nدوبارہ سے نشانات کو صاف کریں\nچھ ماہ تک ، دماغ کی ساخت اور کارگزاری صاف طور پر ایک صحتمندانہ معمول کی طرف بڑھ رہی ہے ۔ اِس سے ظاہر ہوتا ہے کہ اِس بیماری کی وجہ سے اُن کی صحت خراب ہو جاتی ہے ۔';

  @override
  String get alcoholReferenceDay365 =>
      'شراب ، کینسر کی روک‌تھام اور تھکاوٹ\n\nماخذ: National Cancer Institute (NCI), \"Alcohol and Cancer Risk\"\n\nالکحل کینسر کا باعث بنتی ہے\nاین‌سی‌آئی بیان کرتی ہے کہ شراب پینے سے کینسر کا باعث بن سکتا ہے ۔ شراب کو مُنہ کے کینسر (یا اُس کے معدے ) ، فرناس (throat) ، لِری‌ناک بکس ، اوسوپاگوس ، جگر ، سینے اور کالونی اور ری‌توم ) سے منسلک کِیا جاتا ہے ۔ ایک شخص جتنا زیادہ پیتا ہے اُتنا ہی زیادہ شراب پینے کا خطرہ زیادہ ہوتا ہے ۔\n\nشراب کیسے کینسر کا باعث بنتی ہے\nبعض ماہرین کا کہنا ہے کہ اِس شراب میں ڈی‌این‌اے کو نقصان پہنچ سکتا ہے ؛ اِس بیماری کی وجہ سے ڈی‌این‌اے کو نقصان پہنچ سکتا ہے اور اِس کی وجہ سے اِس بیماری کی وجہ سے اُس کی صحت خراب ہو جاتی ہے ۔\n\nخطرات کو روک لینے کے بعد\nبنیادی طور پر ، این‌سی‌آئی بیان کرتی ہے کہ شراب پینے میں وقتاًفوقتاً کم خطرے سے دوچار ہوتا ہے — تحقیق سے ظاہر ہوتا ہے کہ مُنہ کے کینسر اور اوسوپاگوس کو روکنے کے بعد اُس شخص کو کئی سال تک خطرہ لاحق ہو سکتا ہے جو کبھی شراب نہیں پیتا ۔ ایک سال شراب سے آزاد اس راستے پر ایک بامقصد قدم ہے۔\n\nفائدہ‌مند\nاِس کے علاوہ اِس بیماری کی وجہ سے جگر کی بیماری میں مبتلا ہونے کا خطرہ کم ہو جاتا ہے اور جگر کی بیماری میں مبتلا ہو جاتا ہے ۔';

  @override
  String get benzodiazepineReferenceDay7 =>
      'بینزودیازپین واپسی: پہلا ہفتہ\n\nماخذ: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings\"، عالمی ادارۂ صحت (2009)، NCBI Bookshelf\n\nحفاظت پہلے\nبینزودیازپین کی واپسی سے دورے پڑ سکتے ہیں۔ WHO کے مطابق محفوظ ترین طریقہ یہ ہے کہ بینزودیازپین کی مقدار بتدریج کم کی جائے؛ اس سے واپسی کی علامات میں کمی آتی ہے اور دوروں سے بچاؤ میں مدد ملتی ہے۔ طویل استعمال کے بعد اچانک بند نہ کریں — طبی ماہر کے ساتھ مل کر خوراک بتدریج کم کریں۔\n\nواپسی کب شروع ہوتی ہے\nWHO کے مطابق وقت دوا کے اثر کی مدت پر منحصر ہے:\n• کم دورانیے والی (oxazepam, alprazolam, temazepam): عموماً آخری خوراک کے 1–2 دن بعد شروع ہوتی ہے اور 2–4 ہفتے یا زیادہ جاری رہ سکتی ہے\n• طویل دورانیے والی (diazepam, nitrazepam): عموماً آخری خوراک کے 2–7 دن بعد شروع ہوتی ہے اور 2–8 ہفتے یا زیادہ جاری رہ سکتی ہے\nپہلا ہفتہ طویل دورانیے والی بینزودیازپین سمیت علامات کے عام آغاز کی پوری مدت کو محیط ہے۔\n\nممکنہ علامات\nWHO اضطراب، بے خوابی، بے چینی، اشتعال یا چڑچڑاپن، توجہ یا یادداشت میں دشواری، اور پٹھوں میں تناؤ یا درد کو درج کرتا ہے۔\n\nنگرانی\nواپسی کی شدت میں نمایاں اتار چڑھاؤ ہو سکتا ہے۔ WHO علامات اور پیچیدگیوں کی باقاعدہ نگرانی کی سفارش کرتا ہے؛ بند ماحول کے پروٹوکول میں طبی عملہ ہر 3–4 گھنٹے بعد مریض سے بات کرتا ہے اور ضرورت کے مطابق تسلی اور وضاحت فراہم کرتا ہے۔';

  @override
  String get benzodiazepineReferenceDay14 =>
      'بینزودیازپین کی واپسی: دو ہفتے\n\nماخذ: Poyares وغیرہ، \"Chronic benzodiazepine usage and withdrawal in insomnia patients\"، Journal of Psychiatric Research (2004)، PubMed\n\nتقریباً دو ہفتوں میں حقیقی بحالی کی علامت\nمحققین نے مسلسل بے خوابی والے ایسے افراد کا مطالعہ کیا جو برسوں سے ہر رات بینزودیازپین لیتے تھے، اور بتدریج ادویات چھوڑنے کے 15 دن بعد ان کی نیند دوبارہ ناپی۔ مسلسل بینزودیازپین استعمال کے دوران کی پیمائشوں کے مقابلے میں سست موج والی نیند، نیند کے EEG میں ڈیلٹا سرگرمی اور خود رپورٹ کردہ نیند کا معیار بہتر ہوا۔\n\nگہری نیند واپس آ رہی ہے\nسست موج والی نیند non-REM نیند کا سب سے گہرا مرحلہ ہے۔ 15ویں دن سست موج والی نیند اور ڈیلٹا سرگرمی زیادہ تھی، جبکہ مرحلہ 2 non-REM نیند صحت مند کنٹرول گروپ میں دیکھے گئے نمونے کی سمت کم ہوئی۔\n\nابتدائی بحالی، باقاعدہ پیمائش کے ساتھ\nجن شرکاء نے دوا چھوڑنے کا مرحلہ مکمل کیا، ان کی نیند فوراً بعد خراب ہوئی، لیکن 15 دن کی پیروی تک گہری نیند کے معروضی پیمانے اور رپورٹ کردہ نیند کا معیار بہتر ہو گیا۔ یوں دو ہفتے بحالی کا ایک حقیقی اور ناپا گیا سنگِ میل بنتا ہے۔';

  @override
  String get benzodiazepineReferenceDay60 =>
      'بینزوڈائزیپینز: آٹھ ہفتوں پر دن کے وقت کی کارکردگی\n\nماخذ: Tsunoda وغیرہ، \"Effects of discontinuing benzodiazepine-derivative hypnotics on postural sway and cognitive functions in the elderly\"، International Journal of Geriatric Psychiatry (2010)، PubMed\n\nآٹھ ہفتوں میں قابلِ پیمائش بحالی\nمحققین نے 60 سال یا اس سے زیادہ عمر کے ایسے افراد کا مطالعہ کیا جو نگہداشت کے ادارے میں رہتے تھے اور بینزوڈائزیپین نیند کی دوائیں استعمال کرتے تھے۔ تین ہفتوں میں خوراک بتدریج کم کرکے دوا بند کی گئی، اور آٹھویں ہفتے کے اختتام پر ادراک اور توازن کے ٹیسٹ دوبارہ کیے گئے۔\n\nتوجہ اور یادداشت بہتر ہوئیں\nتحقیق مکمل کرنے والے 26 افراد میں فوری یادداشت، توجہ اور زبان کے انڈیکس اسکور نمایاں طور پر بہتر ہوئے۔ یہ بینزوڈائزیپین بند کرنے کے بعد دن کے وقت کی کارکردگی میں براہِ راست ناپی گئی بہتری ہے۔\n\nقدم زیادہ مستحکم\nآنکھیں بند کرکے جسم کے ڈولنے کے پیمانے بھی نمایاں طور پر بہتر ہوئے۔ مصنفین نے نتیجہ اخذ کیا کہ اس عمر رسیدہ گروپ میں بینزوڈائزیپین نیند کی دوائیں بند کرنا بہتر جسمانی استحکام اور دن کے وقت ادراکی کارکردگی کی بحالی سے وابستہ تھا۔\n\nنیند مستحکم رہی\nتحقیق مکمل کرنے والوں نے استعمال کیے گئے نیند کے سوالنامے میں نیند کے بگڑنے کی ذاتی شکایت نہیں کی۔ آٹھویں ہفتے کے اختتام پر قابلِ پیمائش دن کی بہتری ریکارڈ ہوئی، جبکہ نیند کے معیار میں کسی رپورٹ شدہ کمی کا پتہ نہیں چلا۔';

  @override
  String get benzodiazepineReferenceDay90 =>
      'بینزوڈائزیپین چھوڑنے کے تین ماہ بعد: سوچ تیز، غنودگی کم\n\nماخذ: Rickels et al., \"Psychomotor performance of long-term benzodiazepine users before, during, and after benzodiazepine discontinuation,\" Journal of Clinical Psychopharmacology (1999), on PubMed\n\n12 ہفتوں پر قابلِ پیمائش بحالی\nمحققین نے طویل عرصے سے بینزوڈائزیپین استعمال کرنے والوں کو خوراک کم کرنے سے پہلے اور پھر 5 اور 12 ہفتے بعد جانچا۔ 77 افراد کے 12 ہفتے کے اعداد و شمار موجود تھے، اور کامیابی سے دوا چھوڑنے والوں میں بینزوڈائزیپین سے پاک حالت کی تصدیق ہفتہ وار خون کے ٹیسٹ سے کی گئی۔\n\nذہنی کارکردگی تیز\nکامیابی سے بینزوڈائزیپین چھوڑنے والوں نے علامت نقل کرنے اور ہندسہ-علامت بدلنے کے کام ان شرکاء سے زیادہ تیزی سے کیے جو اب بھی بینزوڈائزیپین لے رہے تھے۔ عمر، تعلیم اور ابتدائی اسکور کو مدنظر رکھنے کے بعد بھی فرق معنی خیز رہا۔\n\nذہنی و جسمانی غنودگی کم\nکامیابی سے دوا چھوڑنے والوں نے دوا جاری رکھنے والوں کے مقابلے میں ذہنی اور جسمانی غنودگی بھی کم بتائی۔\n\nتین ماہ کیسے نظر آ سکتے ہیں\nاس تحقیق میں کامیابی سے دوا چھوڑنے والوں میں خوراک کم کرنے کے 12 ہفتے بعد معلومات پر عمل کی رفتار میں قابلِ پیمائش بہتری اور ذہنی و جسمانی غنودگی میں کمی دیکھی گئی۔ سوچ تیز ہوئی اور غنودگی کا احساس کم ہوا۔';

  @override
  String get benzodiazepineReferenceDay180 =>
      'چھ ماہ میں سوچ‌بچار اور یادداشت : قابلِ‌غور گیس\n\nماخذ: Tata et al., \"Lack of cognitive recovery following withdrawal from long-term benzodiazepine use,\" Psychological Medicine (1994), on PubMed\n\nمطالعے کا مقصد\nاس تحقیق نے 21 طویل عرصے سے بینزائڈیازپین کے مریضوں کا جائزہ لینے سے پہلے، تھوڑی دیر کے بعد، اور پھر چھ ماہ کے عرصے میں ان کا مقابلہ کرنے کے ساتھ ساتھ ان کا موازنہ کروی کنٹرول سے کیا۔ یہ بینزو بحالی لٹریچر میں سب سے زیادہ قابل ذکر ڈیٹا پوائنٹ میں سے ایک ہے۔\n\nاِس کی کیا وجہ ہے ؟\nروک لینے سے پہلے مریضوں کو زبانی سیکھنے ، یادداشت ، حرکت کی رفتار ، نظریاتی نقل‌مکانی اور نظریاتی استدلال کے مسائل درپیش تھے ۔ ٹھیک رکنے کے بعد اس میں بہت کم تبدیلی واقع ہوئی۔ چھ ماہ تک ، ان میں سے کئی علاقوں نے مریخ کو کافی بہتر کر دیا ۔\n\nاِس کا کیا مطلب ہے ؟\nچھ ماہ تک ، لفظی سیکھنے ، یادداشت ، حرکت کی رفتار اور نظریاتی رُجحانات کو نہایت تیز کر دیا جاتا تھا ۔ بہتری پہلے ہی واضح تھی اور اس کے جاری رہنے کا کمرہ تھا ۔\n\nبِھیڑ کی تصویر\nاگر آپ کو چھ ماہ کے لگ بھگ محسوس ہو تو یہ تحقیق کہتی ہے: یہ توقع کی جاتی ہے اور ابہام جاری رہتا ہے۔ وقتاً فوقتاً تحقیق سے پتہ چلتا ہے کہ اس نقطے سے بھی آگے بڑھتی رہتی ہے یعنی دماغ شفا بخشتا رہتا ہے۔';

  @override
  String get benzodiazepineReferenceDay365 =>
      'بین‌الاقوامی مدد کے ایک سال بعد : سوچ‌بچار اور یاد رکھنا\n\nماخذ: Barker et al., \"Persistence of cognitive effects after withdrawal from long-term benzodiazepine use: a meta-analysis,\" Archives of Clinical Neuropsychology (2004), on PubMed\n\nہمارے پاس مضبوط ثبوت ہے\nمحققین نے ایسے مطالعات کو یکجا کیا جو کم از کم چھ ماہ کے بعد دوبارہ طویل بینزئیپین صارفین کو ٹیسٹ کرنے کے بعد دوبارہ کوشش کرتے ہیں۔ مجموعی نتیجہ سوچ اور یادداشت میں واضح طور پر تبدیلی کو ظاہر کرتا ہے ۔\n\nخوشخبری\nمجموعی مطالعے نے کئی سوچ اور یادداشت کو ترک کرنے کے بعد حقیقی ، قابلِ‌تعریف ترقی حاصل کی۔ ایک سال کے اندر اندر بحالی کا موازنہ فعال استعمال سے کِیا جاتا ہے ۔\n\nبحالی جاری رہتی ہے\nمشترکہ مطالعے کو سوچ اور یاد میں وسیع پیمانے پر بحالی ملی۔ ایک سال تک ، آپ ایک بحالی کے رُجحان سے اچھی طرح واقف ہیں جو چھ ماہ پہلے ہی بہتر ہو گیا تھا ۔\n\nایک سال میں اس کا کیا مطلب ہے ؟\nاُمید ہے کہ ایک سال تک سوچ‌بچار کرنے ، یاد رکھنے اور واضح طور پر سمجھ‌داری سے کام لینے کی بجائے بیشتر لوگ استعمال کے دوران زیادہ تیز محسوس کرتے ہیں ۔ لیکن اگر کچھ علاقے اب بھی جاری ہیں تو یہ ثبوت کے مطابق ہے، اس کی کوئی نشانی آپ کے پاس نہیں ہے۔ اُس نے کہا : ” اَے [ یہوواہ ] !';

  @override
  String get benzodiazepineReferenceDay540 =>
      '18 ماہ بعد بین‌الاقوامی کمیٹیوں کے رُکن : پیدائشی طور پر مگر حقیقی بحالی\n\nماخذ: Ashton, \"Protracted withdrawal syndromes from benzodiazepines,\" Journal of Substance Abuse Treatment (1991), on PubMed\n\nبین‌الاقوامی صفائی‌ستھرائی اتنی طویل کیوں ہے\nبینزودیز (Benzodiazepines) گیبا پر عمل، دماغ کا بنیادی آرام دہ نظام ہے۔ لمبے عرصے میں تبدیلی کا استعمال اس نظام کا کتنا سخت جواب دیتا ہے اور ان تبدیلیوں کو رد کرنے میں کئی ماہ لگ سکتے ہیں۔ اسی لیے بینزو بحالی کا اندازہ ہفتوں کی بجائے مہینوں میں لگایا جاتا ہے۔\n\nجہاں ۱۸ مہینے کی جگہیں ہیں\nآسٹن طویل عرصے تک جاری رہنے والی علامات کو بیان کرتا ہے جو آسانی کے لیے ماہ لے سکتی ہیں۔ ۱۸ ماہ تک ، سب سے زیادہ بُری بات لوگوں کی پریشانی ، حساس تبدیلیوں اور دماغی فوگ کی وجہ سے بہت زیادہ پریشان‌کُن ہو جاتی ہے ۔\n\nآہستہ آہستہ مایوسی\nجذباتی طور پر ، Ashton اس بنیادی تبدیلی کو ظاہر کرتا ہے جیسا کہ ’ مرکزی اعصابی نظام میں دوبارہ پیدا ہونے والی تبدیلیوں ‘ کے طور پر استعمال کِیا جاتا ہے ۔\n\nدوبارہ سے نشانات کو صاف کریں\nAshton اس ضمنی تبدیلیوں کو آہستہ آہستہ تبدیل کرنے کے طور پر بیان کرتا ہے۔ 18 ماہ تک دماغ کے آرام دہ گیبا سسٹم کے پاس طویل عرصے سے سکونت اختیار کر چکا ہے اور غالب سمت کو معمول کی طرف رجوع کیا جاتا ہے۔';

  @override
  String get benzodiazepineReferenceDay730 =>
      'بین‌الاقوامی ترقی کے دو سال بعد : میجر ، دائمی ترقی\n\nماخذ: Barker et al., \"Persistence of cognitive effects after withdrawal from long-term benzodiazepine use: a meta-analysis,\" Archives of Clinical Neuropsychology (2004), on PubMed\n\nمعافی مانگنے کا فن\nدو سال ایک اہم سنگ میل ہے خاص طور پر لمبے عرصے کے بعد ۔ ابتدائی اور مستقل‌مزاجی کے مواقع بہت قدیم ہیں اور پہلے سال سے حاصل ہونے والے فوائد سے تقویت پانے کے لئے ایک اَور سال ہیں ۔\n\nکیا چیز ثبوت فراہم کرتی ہے ؟\nمشترکہ مطالعے بہتیرے علاقوں میں بحالی کے بعد ظاہر کرتے ہیں ۔ دو سال تک، زیادہ تر لوگ اپنی قبل از کمبینزو کی سطح پر پریشانی کی رپورٹ دیتے ہیں، قابل اعتماد نیند، دوا کے بغیر، متبادل جذبات اور واضح طور پر استعمال کے دوران میں زیادہ تر سوچ رکھتے ہیں۔\n\nدوبارہ سے نشانات کو صاف کریں\nمشترکہ مطالعے نے سوچ اور یادداشت کے بہت سے شعبوں میں بحالی کا کام قائم کیا۔ دو سال کے دوران، مستقل بحالی ثبوت پشتون امیدوار ہے۔\n\nپُراعتماد رہنے کی اہمیت\nدو سال کے بعد نیند ، مزاج ، یادداشت اور واضح طور پر بحالی والی کھڑکیاں قائم ہو جاتی ہیں ۔ اِس سلسلے میں اِن چاروں باتوں پر غور کریں ۔';

  @override
  String get benzodiazepineReferenceDay1095 =>
      'تین سال بعد بینزودیاز (Benzodiazepines): لمبے عرصے کے بعد لمبے عرصے تک صحت مند رہے۔\n\nماخذ: Barker et al., \"Persistence of cognitive effects after withdrawal from long-term benzodiazepine use: a meta-analysis,\" Archives of Clinical Neuropsychology (2004), on PubMed\n\nطویل نظریہ\nتین سال بینزو بحالی وقت کے بعید اختتام پر بیٹھے ہیں۔ لوگوں کی بڑی اکثریت کے لیے شدید عرصے تک جاری رہنے کے بعد بھی ان کے پیچھے بے چینی کی علامات اچھی لگتی ہیں اور زندگی کی کیفیت کو فعال استعمال سے تشبیہ دی جاتی ہے۔\n\nکیا Meta-Analysis ملا\nلمبے عرصے کے صارفین کے مطالعے سے بہت سے شعبوں میں رد عمل کے بعد بحالی کا مظاہرہ ہوتا ہے۔ کئی سالوں سے غالب کہانی سوچ، یادو اور روزمرہ کی سرگرمیوں میں وسیع پیمانے پر بحالی ہے۔\n\nدوبارہ سے نشانات کو صاف کریں\nطویل عرصے کی تحقیق سے بہت سی سوچ اور یادو کے دور میں بحالی کو ظاہر ہوتا ہے۔ تین سال تک ، ابتدائی اور مستقل‌مزاجی آپ کے پیچھے بہت زیادہ ہے اور جو حاصلات آپ کو تقویت بخشنے کیلئے کئی سال گزر چکے ہیں ۔\n\nاُمید کا پیغام\nبینزو بحالی کا سفر طب میں سب سے زیادہ مانگنے والا سفر ہے اور تین سال آرام دہ شفاخانہ ایک گہری تحصیل ہے۔ اس بات کا واضح ثبوت یہ ہے : دماغ کو غیرمعمولی طور پر شفا ملتی ہے ، زیادہ‌تر لوگ اپنی واضح ، نیند اور جذباتی فضا بحال کرتے ہیں اور وقت کے ساتھ ساتھ بہتری آتی رہتی ہے ۔';

  @override
  String get cocaineReferenceDay1 =>
      'کوکینال : پہلی 24 گھنٹے\n\nماخذ: \"Withdrawal Syndromes,\" StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nکوکاین اور دماغ\nCocaine دماغ کے اجرا کے سرکٹز میں دوپمین (اور دیگر مونومینز) کی رد عمل کو بلاک کرتا ہے جس کے نتیجے میں دوپیازہ کی توانائی اور توانائی جمع ہو جاتی ہے۔ باقاعدہ استعمال کے ساتھ دماغ اس نظام سے مطابقت رکھتا ہے تاکہ منشیات کے بغیر عام سرگرمیاں پلیٹ فارم محسوس ہو جائیں۔\n\nکراس\nستلج اسمتھ کو شروع میں \"کرش\" کے ساتھ شروع کرتے ہوئے بیان کرتی ہے کہ ایک بار \"کرش\" استعمال ہوتا ہے، صورت حال جس میں ممتاز ڈپریشن، کم نیند، بھوک، کم مزاج اور شدت پسند حرکت اور سوچ میں کمی واقع ہوتی ہے۔ پہلے 24 گھنٹوں میں اس مہم میں شامل ہیں:\n• بے حد تھکن اور نیند کی ضرورت بڑھتی ہے۔\n• جذباتی اور بے چینی تحریک اور سوچ و فکر کا شکار ہے۔\n• بڑھتی ہوئی بھوک (cocaine conservancy)۔\n\nعام طور پر اس کھڑکی کے دوران بہت زیادہ معلومات دی جاتی ہیں، اگرچہ سٹیج پرلز خاص طور پر حادثے کا حصہ نہیں بناتے ہیں۔\n\nبعض دیگر منشیات کے برعکس\nاِس کے برعکس ، شراب یا بین‌الاقوامی رُجحانات کے برعکس ، یہ غیرمعمولی طور پر ضبطِ‌نفس کا باعث نہیں بنتا ۔ سب سے اہم خطرہ نفسیاتی ہے — ڈپریشن اور بھاری صارفین میں ، حادثاتی طور پر حادثاتی طور پر نقصاندہ ہو سکتے ہیں ، لہٰذا حمایت اور نگرانی کی ضرورت ہوتی ہے ۔\n\nصحت‌بخش علاج\nاس وقت کوکین رد عمل کا علاج کرنے کے لیے کوئی دوائیں منظور نہیں ہیں؛ انتظامیہ معاونت ہے اور غیر منظم رسائی جیسے کہ بنیادی استعمالات کے لیے ثبوت پر مبنی علاج ہیں۔';

  @override
  String get cocaineReferenceDay3 =>
      'تین دن بغیر کوکین: نوویانگ پیک چیلنج۔\n\nماخذ: \"Cocaine Toxicity,\" StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nجسم پر کوکین کا اثر کیسے ہوتا ہے\nکوکین کی مدد سے کوکین ، اورپینین‌فرین اور سرتونین کے دوبارہ ملاپ کو روک دیا جاتا ہے جس سے ہمدردانہ اسکیشن میں اضافہ ہوتا ہے ۔ اِس کی وجہ یہ ہے کہ اُس کا جسم اِس بات سے متاثر ہوتا ہے کہ اُس کا ہر عضو اِس نظام کو متاثر کرتا ہے ۔\n\nدنوں 2–4: Peak Presculational -\nتین دن تک دہشت‌گردی کا سب سے بڑا مسئلہ خودبخود پیدا ہو گیا ہے :\n• ان کی سب سے زیادہ شدت سے مایوسی اور افسردگی کا شکار ہے۔\n• عیش‌وعشرت کا خاتمہ\n• مضبوط، کیک-کری-رنگل\n• پریشانی اور مایوسی\n• بعض لوگوں میں زیادہ‌تر نیند سو جاتی ہے اور دوسروں میں اِس کا اثر ہوتا ہے ۔\n\nاِس بیماری کی وجہ سے اِس بیماری کا شکار ہو جاتے ہیں ۔\nسٹی‌پیرس کی شناخت کوکین کے سب سے زیادہ تباہ‌کُن اثر کے طور پر ہوتی ہے : دل کی دھڑکن اور خون کے دباؤ میں اضافہ ہوا ، کوروناری واسپسم اور پلیٹ‌لیٹ‌لیٹس — نوجوان صارفین میں بھی اری‌تھی‌میا کے خطرے میں اضافہ ہوا ۔ کوکین کی خود کی نصف حیات مختصر ہے، تقریباً ایک گھنٹے تک اور تین دن تک آپ کے نظام کو مکمل طور پر صاف کر دیا گیا ہے — اگرچہ سٹی‌پرلز نوٹ کرتا ہے کہ استعمال کے بعد بھی کئی گھنٹوں تک خون کی لت پیدا ہو سکتی ہے اور ایک میٹبلائٹ بھی کئی ہفتوں تک رہ سکتی ہے، اس لئے بعض اینٹی‌باڈیز ادویات خودبخود ختم ہو سکتی ہیں ۔\n\nجلد آنے والی سڑک\nاِس کا مطلب ہے کہ اِس کا زیادہ‌تر فائدہ یہ ہے کہ اِس میں ڈپریشن ، مایوسی ، مایوسی اور خوشی کی علامات شامل ہیں ۔';

  @override
  String get cocaineReferenceDay7 =>
      'ایک ویک بے کوکین : جسمانی طور پر صاف‌دلی سے کام لیں\n\nماخذ: \"Withdrawal Syndromes,\" StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nاِس سے ظاہر ہوتا ہے کہ اِس کا انجام موت ہے ۔\nکوکین ردِعمل کی بابت بیان کرتا ہے کہ ابتدائی حادثے سے کافی زیادہ بحالی کے مرحلے میں منتقل ہوتا ہے ۔ پہلے ہفتے کے آخر تک یہ علامات عام طور پر ختم ہو جاتی ہیں جبکہ دوامین کا نظام دوبارہ تعمیر کرتا رہتا ہے۔\n\nجسمانی طور پر کُل‌وقتی خدمت\nکوکین کا ہمدردانہ اسکیپ ولاسٹی رک جانے کے بعد ، اس کی وجہ سے اس کی کمیت ، تھکن ، نیند اور ہوائی اثرات مندرجہ ذیل دنوں اور ہفتوں کے دوران دوبارہ شروع ہو جاتے ہیں:\n• دل کی رفتار اور خون کا دباؤ معمول کی طرف واپس منتقل ہو جاتا ہے۔\n• ایپیٹ آہستہ واپس آتی ہے (کوکین اس کی سختی کرتا ہے)۔\n• نیند کی عادات کا آغاز\n• اگر کوکین کو شفا دینا شروع کی گئی تو\n\nپرو فا ئل جاری رہتا ہے۔\nاساطیری ماہرین کا کہنا ہے کہ ڈپریشن اور عیش‌وعشرت کے زوال کی خصوصیت اُس وقت ہے جب اُس کی جسمانی علامات ختم ہو جاتی ہیں :\n• مُردار اگرچہ اُونچائی سے بھی کم سخت رہتا ہے\n• کُو-تَوْرَگَدَیْنَا تَوَوَّلَتَكُمْ فَوْتَرَكَ مَا تَدْرَكُونَ سانچہ:قرآن-سورہ 26 آیت 56۔\n• ترقی اور تحریک اب بھی ناقابل برداشت ہے۔\n\nپوسٹ ایکسچینج\nاِس کے بعد اُن کی سوچ بدل جاتی ہے اور اُن کی سوچ بدل جاتی ہے ۔ یہ جانتے ہوئے کہ بحالی کا کام آسان ہو جاتا ہے ۔';

  @override
  String get cocaineReferenceDay14 =>
      'دو آئس بے کوکین (Cocaine): ڈھونڈنا Stability –\n\nماخذ: \"Withdrawal Syndromes,\" StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nدو رنگ\nدو ہفتوں تک ، شدید حادثے کی علامات — گہرا ڈپریشن ، نیند کی کمی اور حرکتوں اور سوچ میں کمی — نے عام طور پر آسانی حاصل کر لی ہے ۔ اس وقت ریکی دماغ اور جذباتی صحت کو دوبارہ بحال کرنے پر مرکوز ہے۔\n\nتشدد اور جذباتی حالت\nدو ہفتوں کے دوران بھی مزاج معمول سے نیچے ہو سکتا ہے جبکہ دوپیمین سسٹم ٹھیک ہو جاتا ہے۔ پہلے ہفتے کے مقابلے میں عیش‌وعشرت کا گہرا نقصان ہوتا ہے اور خیریت کے حقیقی لمحات واپس آ رہے ہیں ۔\n\nکُل‌وقتی خدمت\nاس مرحلے پر کیو-ٹرینگ ڈرائنگ ایک اہم چیلنج ہے۔ دماغ نے کوکین استعمال اور مخصوص ماحول ، لوگوں ، جذبات اور سرگرمیوں کے مابین مضبوط رفاقت پیدا کی ہے ۔ جب عام رُجحان بہتر ہو جاتا ہے تو اِن میں سے کسی سے ملاقات کرنے سے بھی شدید مایوسی پیدا ہو سکتی ہے ۔ اعلیٰ ماحولیات سے بچنے اور نئی شراکت داریوں کی تعمیر میں اہم کردار ہے۔\n\nنیند پوری کرنا\nنیند عموماً دو ہفتوں تک زیادہ مستحکم اور بحال رہتی ہے ۔ نیند پوری کرنے سے ہمارا ذہنی رُجحان ، واضح سوچ اور ضبطِ‌نفس پر گہرا اثر پڑتا ہے ۔\n\nفاؤنڈیشن تعمیر کریں\nکیوں کہ اسمؤل استعمال کرنے والے امراض کے لیے ثبوتوں پر مبنی علاج سیرت کارانہ ہے — Conscy انتظامیہ، علاج اور ہمہ وقت معاونت — دو ہفتے کے نشان کے ساتھ تعاون کرنے کا ایک اہم وقت ہے جو طویل عرصے تک بحالی کے عمل میں آئے گا۔';

  @override
  String get cocaineReferenceDay60 =>
      'دو ماہ بغیر کوکین: مُود اور انعام بیگن کو دوبارہ حاصل کرنے کے لئے\n\nماخذ: \"Recovering from Cocaine: Insights from Clinical and Preclinical Investigations,\" Neuroscience & Biobehavioral Reviews (2013), on PubMed Central\n\nدماغ کیا کر رہا ہے\nیہ تجزیہ انسانی اور حیوانی مطالعات کو روکتا ہے کہ دماغ کے ساتھ کیا واقع ہوتا ہے جب کوکین استعمال کرتا ہے۔ اِن نظاموں کو بحال کرنے کے لئے اِن نظاموں کو استعمال کِیا جاتا ہے ۔\n\nترقیاتی نظام\nجانوروں کی تحقیق میں کوکین سے متعلقہ تبدیلیاں دوپیمین کے مرکبات اور ری سائیکل پروٹین نے صحت مند مقداروں کی طرف رجوع کیا جن میں مستقل طور پر مستقل طور پر صحت مند نسل کشی کی گئی تھی۔ جب اِس نظام کو بحال کِیا جاتا ہے تو خوشی حاصل کرنے اور روزمرّہ کے اجر — خوراک ، رفاقت ، کامیابی — سے بھرپور فائدہ اُٹھاتے ہیں ۔\n\nدوبارہ سے نشانات کو صاف کریں\nدو ماہ تک، مزاج میں بہتری آ رہی ہے اور نیند کا متبادل ہوتا ہے جبکہ دوپیمین اور سامنے والے کرکٹ سسٹم کی تعمیر جاری رہتی ہے۔ پریمئر کے تحقیق سے پتہ چلتا ہے کہ کوکین سے متعلق D1-receptor اور ٹرانسپورٹر کنٹرول سطحوں کی طرف واپس منتقل ہو جاتی ہے۔';

  @override
  String get cocaineReferenceDay90 =>
      'تین مہینے بے کوکین : دوپمین مارکرز رینے\n\nماخذ: \"Recovering from Cocaine: Insights from Clinical and Preclinical Investigations,\" Neuroscience & Biobehavioral Reviews (2013), on PubMed Central\n\n90 دن کا موسم کیوں ہے\nیہ جائزہ حیاتیاتی طور پر تین ماہ کے نقطہ نظر کو نمایاں کرتا ہے۔ غیر انسانی ذمہ‌داریوں میں ، کوکین نے 90 دن کے طویل عرصے کے بعد ” دوبارہ کنٹرول کرنے کے لئے لوٹنے والی واپسی “ کا مظاہرہ کِیا تھا — براہِ‌راست ثبوت پیش کِیا کہ یہ انعام منشیات ختم ہو جانے کے بعد ختم ہو سکتا ہے ۔\n\nدماغ کا اگلا حصہ\nمصنفہ دماغ کے سامنے بحالی کو وسیع اصناف کے اہم آثار میں سے ایک قرار دیتے ہیں۔ یہ علاقہ کنٹرول، فیصلہ سازی اور خود مختاری کو سنبھالتا ہے اور جب وہ بحال ہو جاتا ہے تو ان صلاحیتوں کو مضبوط کرتا ہے۔\n\nکونسا 90 دن ظاہر کرتا ہے\n90 دن کے دوران پرائمری مطالعات میں D1, D2, اور Dopamine-transporter Densities دریافت ہوئے جو اب غیر انسانی کنٹرولز سے مختلف نہیں ہیں۔ طویل تفاعل کے بعد بھی اس نقطہ سے پہلے ہی دوپمین سسٹم کی بحالی نظر آتی ہے اور ابجد کے ساتھ جاری رہتی ہے۔';

  @override
  String get cocaineReferenceDay180 =>
      'چھ ماہ بغیر کوکین: کلیئر سوچ رکھنے والا\n\nماخذ: \"Structural and Functional Brain Recovery in Individuals with Substance Use Disorders During Abstinence: A Review of Longitudinal Neuroimaging Studies,\" on PubMed Central\n\nتصویر کو دوبارہ ترتیب دیں\nاس جائزے میں پولش لمبے عرصے کے دوران دماغ کے اندر پیدا ہونے والے مطالعے کیے گئے ہیں جو ان ہی لوگوں کو بار بار اپنی بے ترتیبی کی وجہ سے ڈھالتے ہیں۔ کوکین کے لئے یہ بیان کِیا جاتا ہے کہ کامیِ‌عمل ناقابلِ‌برداشت طور پر غیرمعمولی طور پر بحال ہو جاتا ہے ۔\n\nدماغ کے تصور کے ثبوت\nدو کارنامہ-MRI نے وقت کے ساتھ ساتھ کوکین صارفین پر تحقیق کی اور دونوں نے لمبے عرصے تک آذربائیجان اور تلمس میں بہتر طور پر دریافت کیا۔ ایک میں دماغ کے تقریباً چھ ماہ کے بعد غیر صحت مند کنٹرولز کے مشابہ تھا۔ ایک قابل ذکر مواد، تجزیے سے پتہ چلتا ہے کہ ایٹمی عملے میں پیدا ہونے والے نتائج ایک دوامینارجیک کی بحالی کی طرف اشارہ کرتے ہیں۔\n\nچھ ماہ کے بعد اس کا کیا مطلب ہے\nیہ عملی طور پر اس مرحلے کی طرف سے حقیقی دنیا کی بہتری کے ساتھ لوگوں کی رپورٹ کے ساتھ حاصل کرتے ہیں:\n• بہتر توجہ دیں اور کام کی یاد تازہ کریں\n• شارپ فیصل آباد اور فیصل آباد کنٹرول کرتا ہے۔\n• ذہنی رُجحان اور جذباتی میلان\n\nدوبارہ سے نشانات کو صاف کریں\nتقریباً چھ ماہ میں ، ایک لمبی عمر والے دماغ FMRI Kohort نے غیر صحت مند کنٹرولز کے مساوی انداز ظاہر کِیا ، جب کہ بین‌الاقوامی اور گہرا‌شُدہ اینٹی‌بائیوٹکس کے طور پر بہتر ہو گئی ۔ یہ براہِ‌راست دماغی بحالی کی عکاسی کی گئی ہے ۔';

  @override
  String get cocaineReferenceDay365 =>
      'ایک سال بغیر کوکین کے : کارڈی کے عملے کی نقل کی جاتی ہے\n\nماخذ: \"Cocaine Toxicity,\" StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nدل کیوں مرکزی ہے\nسٹی‌پرلز کی شناخت کوکین کے سب سے زیادہ تباہ‌کُن اثر کے طور پر ہوتی ہے ۔ ہر استعمال سے دل کا دورہ پڑنے ، بلڈ پریشر اور میریک‌ڈیکل آکسیجن کی مانگ بڑھتی ہے جبکہ کوروناری واس‌پسم اور خون کے بننے کا سبب بنتی ہے ۔\n\nاَے [ یہوواہ ] !\nکوکین کے بغیر دن‌بھر اِن تلخ‌کلامی سے آزاد ہوتا ہے ۔ ایک سال کے عرصے میں بار بار خون کے دباؤ اور دل کا دورہ پڑنے سے انتقال ہو جاتا ہے، کوکین سے پیدا ہونے والی کوکینری اسپم اور انفنٹری انفنٹری کا خطرہ دور ہو جاتا ہے اور دل کو پھر آکسیجن غلط استعمال میں نہیں لایا جا رہا ہے۔\n\nدوبارہ سے نشانات کو صاف کریں\nکوکین کو روکنے سے دل کی چوٹ لگ جاتی ہے ۔ فلوس یا Myocarditis ایک طبّی مسئلہ ہے لیکن بار بار کوکین-ٹریگرڈ عصمت دری ختم ہو جاتی ہے۔\n\nدماغ کو جلد از جلد ڈھانپنا\nایک سال تک ، انعام اور ضبطِ‌نفس کے نظام میں بہتری لانے ، بہتر کارکردگی کو بہتر طور پر کنٹرول کرنے ، متبادل مزاج کی حمایت کرنے اور روزمرّہ اجرتوں کے لئے مضبوط جوابی‌عمل پیدا کرنے کا وقت ہو گیا ہے ۔';

  @override
  String get cocaineReferenceDay730 =>
      'دو سال بغیر کوکین (Cocaine) : دوبارہ تعمیر شدہ بحالی\n\nماخذ: \"Recovering from Cocaine: Insights from Clinical and Preclinical Investigations,\" Neuroscience & Biobehavioral Reviews (2013), on PubMed Central\n\nطویل نظریہ\nاس جائزے سے انسان اور جانوروں کے مطالعے سے کوکین ایبٹ آباد کے بارے میں کیا ظاہر ہوتا ہے۔ اس کا مرکزی نتیجہ یہ ہے کہ پیشہ ورانہ کام کی حفاظت اور بحالی طویل مدتی رد عمل کا سب سے اہم نشان ہے — طویل مدتی پابندی کرنے والوں (10+) نے مختصر مدتی طور پر پیش قدمی کرنے والوں کی نسبت اعلیٰ پیشہ ورانہ کارکردگی کا مظاہرہ کیا۔\n\nہیل کا عمل جاری رہتا ہے۔\n• کوکین سے تبدیل‌شُدہ دوپیئن مارکز مستقل طور پر مستقل طور پر مستقل‌مزاجی سے کام لیتے رہتے ہیں\n• فعال اور ابتدائی دور میں دیکھے جانے والے سفید اور سفید فام وفاداری صارفین زیادہ عرصے سے اُڑ سکتے ہیں، ممکنہ طور پر میریلین میزائل جاری کرنے کے ذریعے\n• فرنٹل کنٹرول سرکٹ — کنٹرول، فیصلہ، جذباتی دباؤ — مضبوط بناتا ہے۔\n\nدوبارہ سے نشانات کو صاف کریں\nمصنف ایک حقیقی سائنسی احتیاط پیدا کرتے ہیں: طویل عرصے سے احتیاط کرنے والوں میں کچھ فرق ایک \"نور اثر\" کی عکاسی کر سکتا ہے — جن لوگوں نے زیادہ ذہنی توازن کے ساتھ شروع کیا تھا وہ تنہائی کو بحال کرنے کی بجائے تنہائی میں رہنا آسان ہو سکتا ہے۔ واضح رہے کہ دو سال کیک آزاد دماغ کی مدد کرتا ہے ایک غیر عملے کے قریب کام کرتا ہے اور ایک ایسی زندگی جو محض بے بنیاد نہیں بلکہ دوبارہ تعمیر کی جاتی ہے۔';

  @override
  String get ghbReferenceDay1 =>
      'جی‌ایچ‌بی‌بی : پہلی گھڑی\n\nماخذ: \"Characterization of the GHB Withdrawal Syndrome,\" on PubMed Central\n\n<unk> یہ ایک طبی مرکب ہے۔\nاِس لئے اُنہوں نے شراب پینا چھوڑ دیا اور اِسے ترک کر دیا ۔ اِس سے ظاہر ہوتا ہے کہ اِس بیماری کی وجہ سے بہت سے لوگ دل کی بیماریوں میں مبتلا ہو جاتے ہیں ۔ ہر ایک کا انحصار GHB، GBL پر ہے یا 1.4-butanideliol صرف روک تھام کرنے کی بجائے انفنٹری میں داخل ہونے کی کوشش کرنی چاہیے۔\n\nیہ اتنی تیزی سے کیوں شروع ہوتا ہے\nجی ایچ بی کی نصف حیات محض 30–60 منٹ ہے اور انحصار کرنے والے صارفین کو ہر 2–3 گھنٹے صرف سگریٹ چھوڑنے سے گریز کرنے کے لیے سرخ کرنے کی ضرورت ہوتی ہے یعنی شراب یا بینزودائیز سے زیادہ تیز رفتار۔ کہ تیزی سے فقہاکوینتی (harmacocinetics) اس وجہ سے علامات دوسرے سادات (sedative-hyponotic reaction) کے ساتھ ساتھ بہت جلد ظاہر ہو سکتی ہیں۔\n\nابتدائی ابتدا\nپریشانی ، زلزلے ، پس‌منظر ، تیزی سے دل کی دھڑکن اور بلند فشارِخون کا شکار ہو جاتے ہیں ۔';

  @override
  String get ghbReferenceDay3 =>
      'پیدائش : سب سے مشکل دَور\n\nماخذ: \"Characterization of the GHB Withdrawal Syndrome,\" on PubMed Central\n\nسب سے بڑا مسئلہ\nاس مطالعے میں کئی بنیادی علامات — مس‌کیس ، مس‌شُدہ ٹی‌وی ، ایک طنزیہ اور دباؤ ، تیزی سے دل کا دورہ پڑنے اور تین دن کے اندر اندر اندر ۷۰ فیصد سے زیادہ علامات پیدا ہوئیں جن میں چار دن تک علامات میں کمی واقع ہوئی ۔ یہ ابتدائی کھڑکی عام طور پر سب سے اعلیٰ درجے کی مدت ہوتی ہے، جب غیر فعال طور پر غیر جانبدار طور پر دیلریئم، قبضے یا دل کی رفتار اور بلڈ پریشر میں خطرناک انفیکشن کا شکار ہونے کا امکان زیادہ ہوتا ہے۔\n\nسخت یادیں\n• شدید پریشانی اور پریشانی\n• Audiory and Visual Haluciations, Paranoia\n• Tremor، پسٹننگ، دوڑنا دل اور بلند فشارِخون کا شکار ہے۔\n• اذیت کے خطرات\n\nانتظام\nتحقیق میں بیان کِیا گیا ہے کہ بین‌الاقوامی ترقی‌پذیر ٹیپ اور کیمیائی جی ایچ‌بی ٹیپ‌رنگ دونوں عام استعمال کئے جانے والے طریقوں کے طور پر استعمال ہونے والے ہیں ۔ خواہ آپ کسی بھی طریقے سے قریبی نگرانی کا تقاضا کرتے ہیں — یہ گھر میں انتظام کرنے سے محفوظ نہیں ہے ۔';

  @override
  String get ghbReferenceDay7 =>
      'ایک ہفتے کے آخر میں\n\nماخذ: \"Characterization of the GHB Withdrawal Syndrome,\" on PubMed Central\n\nزیادہ‌تر جنگلی جانور ہیں\nکئی بنیادی علامات پہلے چار دن کے اندر اندر شدید یا غیرمتوقع بیماریوں میں ۷۰ فیصد سے زیادہ کمی واقع ہوئی ہیں ۔ نگرانی والی ٹیپنگ کے تحت ، ٹیپنگ مرحلے نے خود کو اوسطاً ۱۱ دن تک برقرار رکھا اور اس کے بعد تقریباً چھ دن بعد دوبارہ شروع ہو گیا — لہٰذا ایک ہفتے تک بہتیرے لوگ اس بہتری میں اچھی طرح مبتلا رہتے ہیں اگرچہ اس عمل کو مکمل طور پر ختم نہ کِیا جا سکے ۔\n\nآپ کیا کر سکتے ہیں ؟\n• خشک‌سالی ، خوف‌زدہ اور ہاتھ\n• بہت زیادہ نیند سونا یا بات‌چیت اور آرام کرنا\n• کرس‌ٹینا\n\nتحقیق سے پتہ چلا کہ ان مخصوص علامات میں کوئی تبدیلی واقع نہیں ہوئی تو اس ہفتے کو برقرار رکھنا غیر معمولی بات نہیں ہے۔ اِس بیماری میں مبتلا مریضوں کی دیکھ‌بھال کرنا اُس وقت تک اہم ہے جب تک کہ ذیابیطس میں واضح طور پر نہ ہو ۔';

