  @override
  String get ghbReferenceDay180 =>
      'چھ ماہ کا وقفہ\n\nماخذ: \"Characterization of the GHB Withdrawal Syndrome,\" on PubMed Central\n\nنصف سال پر\nچھ ماہ تک ، طویل عرصے سے جی‌بی‌بی انتقالِ‌خون ختم ہو جاتا ہے اور دوبارہ نیند کو قائم کرنے ، فوری طور پر کنٹرول کرنے اور دوبارہ روک‌تھام کیلئے مکمل طور پر بحال ہو جاتی ہے ۔ اس مرحلے کی بجائے پہلے دن اور ہفتوں سے خطرناک خودکار اور دیلئیئم-ریئم مرحلے سے تعلق رکھتا ہے۔\n\nبِھیڑ کی تصویر\nجی‌ایچ‌بی کے ذریعے تحفظ حاصل کرنے اور نصف سال تک رہنے کی ایک بڑی کامیابی یہ ہے کہ ابتدائی مرحلے کو کتنا خطرناک ثابت کِیا جا سکتا ہے اور اسکے بعد دوبارہ پیدا ہونے والا خطرہ کسقدر خطرناک ثابت ہو سکتا ہے ۔ آپ یہاں حاصل ہونے والے معمولات اور حمایت کے مستحق ہیں.';

  @override
  String get inhalantsReferenceDay1 =>
      'اِس سے ظاہر ہوتا ہے کہ ہم یہوواہ خدا سے محبت کرتے ہیں ۔\n\nماخذ: Radparvar, \"The Clinical Assessment and Treatment of Inhalant Abuse,\" The Permanente Journal (2023), on PubMed Central\n\nمعجزے کیوں ہوتے ہیں ؟\nاِس کی وجہ یہ ہے کہ اِس بیماری کی وجہ سے اِس بیماری میں مبتلا ہونے کا امکان کم ہو جاتا ہے ۔ بہتیرے ایسے ہی دماغ کے سرکٹ کو شراب کے طور پر متاثر کرتے ہیں لہٰذا دماغ کو وقتی طور پر بےقابو چھوڑ دیتا ہے ۔ کیمیائی مادوں سے خون کی جلد صاف ہو جاتی ہے مگر جسم کی چربی میں محفوظ رکھا جاتا ہے جس سے وقت کا مناسب وقت آ سکتا ہے۔\n\nابتدائی ابتدا\nاِس جائزے میں بتایا گیا ہے کہ شراب پینے یا بین‌الاقوامی مدد کرنے کے لئے اِستعمال ہونے والی علامات کا ذکر کِیا گیا ہے :\n• ناکا ، سُرنگ اور پس‌منظر\n• باقاعدگی سے دل کا دورہ پڑنے سے دل کا دورہ پڑ جاتا ہے۔\n• مایوسی اور نیند کی کمی\n• پریشانی اور پریشانی\n\nایک محفوظ نوٹ\nمزید سنگین صورتوں میں ، تجزیہ‌شُدہ رپورٹوں کے مطابق ، علامات میں حل‌شُدہ ، فریب‌کُن اور ضبطِ‌نفس کی فہرست بھی پیش کرتا ہے ، اگرچہ یہ ایک مقررہ وقت کے طور پر ان علامات کا علاج نہیں کرتا ، نہ ہی مقررہ وقت کے طور پر رونما ہوتا ہے ۔ طب کی نگرانی ڈیوٹکس کے دوران حکیمانہ ہوتی ہے، خاص طور پر بھاری، طویل مدتی صارفین کے لیے۔';

  @override
  String get inhalantsReferenceDay7 =>
      'اُن میں سے ایک کا نام‌ونشان مٹا دیتا ہے\n\nماخذ: Radparvar, \"The Clinical Assessment and Treatment of Inhalant Abuse,\" The Permanente Journal (2023), on PubMed Central\n\nکیا آپ کو معلوم ہے ؟\nاناطولیہ لٹریچر میں شراب یا بینزودیازائپین رد عمل کے طور پر بیان کیا گیا ہے، لیکن عام طور پر اسے مختصر مدت تک سمجھا جاتا ہے۔ پہلے ہفتے کے آخر تک ، شدید جسمانی علامات — بیماری ، چوٹ ، پس‌منظر ، بےچینی — عام طور پر زیادہ‌تر لوگوں کیلئے حل ہو رہی ہیں ۔\n\nکیا چیز قائم رہتی ہے ؟\n• نیند اور دماغ کی نشوونما\n• ادنیٰ یا غیر مستحکم مزاج\n• کرس‌ٹینا\n\nابتدائی ابی‌سلوم پر غور کریں\nاِس مرحلے میں دماغ کے لئے مسلسل نقصان نہیں ہوتا کیونکہ دماغ ابھی تک تازہ‌دم ہو رہا ہے ۔ اِس بات پر تحقیق کریں کہ اگلے ہفتوں میں کس طرح سوچ اور یادداشت کو بحال کِیا جاتا ہے اور بعد کے میلوں میں مہینوں کا احاطہ کِیا جاتا ہے ۔';

  @override
  String get inhalantsReferenceDay14 =>
      'دو رنگ‌برنگی دُنیا\n\nماخذ: Radparvar, \"The Clinical Assessment and Treatment of Inhalant Abuse,\" The Permanente Journal (2023), on PubMed Central\n\nاِس کی وجہ یہ ہے کہ اِس بیماری کی وجہ سے اُن کی صحت خراب ہو گئی ہے ۔\nکلینک کے جائزے میں شراب یا بین‌اُلعملے کو نظرانداز کرنے کی بجائے تھوڑی دیر کے لئے استعمال کِیا گیا ہے ۔ دو ہفتوں تک ، خوف‌زدہ ، پریشان‌کُن اور پریشان‌کُن زندگی بسر کر رہی ہے ۔\n\nجلد آنے والی سڑک\nاگلے مہینوں میں توجہ ، یادداشت ، حرکت اور اِس کی وجہ سے آہستہ آہستہ واپس لوٹ آتی ہے ۔ مستقل طور پر یہ تمام نظمیں بہتری لانے کے لیے وقت دیتی ہیں۔ اچھی خوراک (inhalant used) وٹامن بی12) کو ضائع کر سکتا ہے اور اس کے لیے ایبٹ آباد سٹیج قائم کر سکتا ہے۔';

  @override
  String get inhalantsReferenceDay30 =>
      'ایک ماہ کی تاخیر\n\nماخذ: Dingwall et al., \"Cognitive recovery during and after treatment for volatile solvent abuse,\" Drug and Alcohol Dependence (2011), on PubMed\n\nجہاں ایک ماہ کی چھٹی ہوتی ہے\nابتدائی دور آپ کے پیچھے بہت اچھا ہے۔ اس مطالعے میں کچھ سیکھنے کی صلاحیت چھ ہفتوں کے اندر بہتر ہو گئی، جب کہ نظریاتی ترانے، یادداشت، منصوبہ بندی اور فیصلہ سازی کے بعد اگلے مہینوں میں آہستہ آہستہ بہتر ہو گئی۔\n\nآپ کیا کر سکتے ہیں ؟\n• توجہ اور کچھ سیکھنے کے کام\n• مُردار اور سو جیسے جسم کمزور ہو جاتا ہے\n• موٹر رفتار، بتدریج\n\nدوبارہ سے نشانات کو صاف کریں\nمطالعے کا نتیجہ واضح ہے: یادداشت، منصوبہ بندی اور فیصلہ سازی کی وجہ سے سالوں کے دوران آہستہ آہستہ بہتری آتی ہے۔ ابی‌سلوم اس بحالی کا سب سے مضبوط ڈرائیور ہے ۔';

  @override
  String get inhalantsReferenceDay90 =>
      'تین ماہ کی تاخیر\n\nماخذ: Dingwall et al., \"Cognitive recovery during and after treatment for volatile solvent abuse,\" Drug and Alcohol Dependence (2011), on PubMed\n\nایک ناقابلِ‌یقین ، غیرمتوقع\nاس مطالعے نے آٹھ ہفتے کے علاج کے پروگرام سے باہر لوگوں کی پیروی کی اور ایک سال بعد ان میں سے کچھ کا دوبارہ جائزہ لیا۔ کچھ سیکھنے کی صلاحیت چھ ہفتوں کے اندر بہتر ہو گئی، جب کہ نظریاتی ہندسے، یادداشت، منصوبہ بندی اور فیصلہ سازی میں مزید بہتری لائی گئی۔\n\nکورس جاری رکھنا\nمطالعے سے پتہ چلتا ہے کہ اِن صلاحیتوں کی وجہ سے اِن میں سالوں کے دوران آہستہ آہستہ بہتری آتی رہتی ہے ۔ تین مہینوں کے بعد ، اُنہوں نے اپنے بچوں کی پرورش کرنے کے لئے اَور زیادہ محنت کی ۔';

  @override
  String get inhalantsReferenceDay365 =>
      'ایک سال غیرمتوقع\n\nماخذ: \"A prospective study of neurocognitive changes 15 years after chronic inhalant abuse,\" on PubMed\n\nحقیقی ، قابلِ‌اعتماد بحالی\nطویل عرصے کے مطالعہ نے دو سال کے طویل عرصے کے بعد مستقل انہدام دماغ اور سوچ کے مسائل سے دوبارہ رجوع کیا۔ ایک سال میں آپ اس بحالی کی راہ پر اچھی طرح چل رہے ہیں ۔\n\nاس کا کیا مطلب ہے ؟\nیاد رکھیں ، توجہ اور موٹروے کام میں بہتری لانے کا عمل جاری رہتا ہے ۔ لمبے عرصے تک طویل عرصے سے دماغ کی حقیقی بحالی پیدا ہوتی ہے: دو سال تک، زیادہ تر دماغ، یادداشت اور سوچنے والے سکور دائمی صارفین میں عام طور پر واپس آئے تھے جن کے دماغ کو لیڈرشپ سے کوئی نقصان نہیں ہوتا تھا۔';

  @override
  String get inhalantsReferenceDay730 =>
      'دو سال بیکار ہو گئے\n\nماخذ: \"A prospective study of neurocognitive changes 15 years after chronic inhalant abuse,\" on PubMed\n\nدو سالہ مارک\nیہ تحقیق میں اہم سنگ میل ہے: دو سال کے طویل عرصے کے بعد دماغ کے نقصان کی عکاسی کرتا ہے۔ مصنفوں نے یہ نتیجہ اخذ کیا کہ دماغ کے نقصان کی عدم موجودگی میں، طویل عرصے تک کی تاخیر دماغ کی کارکردگی کی بحالی کی اجازت دے سکتی ہے۔\n\nدوبارہ سے نشانات کو صاف کریں\nاِس کے علاوہ اِس سے بھی نقصان ہوتا ہے ۔ ورنہ دو سال کے بچے دماغ کو شفا دینے کے بہترین مواقع کی نمائندگی کرتے ہیں — اس کے گرد دوبارہ تعمیر ہونے والی زندگی ۔';

  @override
  String get ketamineReferenceDay1 =>
      'اِس سے ظاہر ہوتا ہے کہ ہم اِس بات پر یقین رکھتے ہیں کہ یہوواہ خدا ہماری مدد کرے گا ۔\n\nماخذ: \"Ketamine-Induced Cystitis: A Comprehensive Review of the Urologic Effects of This Psychoactive Drug,\" on PubMed Central\n\nکیا یہ خالق کی کاریگری ہے ؟\nاسکے برعکس ، کاٹمین بہت کم جسمانی طور پر ختم ہو جاتا ہے ۔ عام طور پر لوگوں کو جسمانی بیماریوں سے زیادہ تکلیف اور ذہنی دباؤ کا سامنا کرنا پڑتا ہے ۔\n\nآپ کیا محسوس کریں گے ؟\n• مادہ‌پرستی اور کم رُجحان\n• کرس‌ٹینا\n• جذباتی پس‌منظر یا نقل‌مکانی\n\nاہم اقدام\nہر شخص کے لئے فوری اور مکمل طور پر بحالی کا اہم پہلو ہے — لہٰذا ایک دن سب سے اہم فیصلہ ہے ۔';

  @override
  String get ketamineReferenceDay7 =>
      'ایک ہفتے کے آخر میں کیٹامین\n\nماخذ: \"Ketamine-Induced Cystitis: A Comprehensive Review,\" on PubMed Central\n\nپُراسرار پَر\nشروع شروع میں کیٹمین کی بیماری میں سب سے اہم چیلنج نفسیاتی ہے : جذباتی ، تبدیلی یا کم‌تر رُجحان اور دماغ کے بعض حصوں میں تبدیلی واقع ہوتی ہے ۔ جسمانی طور پر حرکت کرتے وقت عموماً نرم‌مزاجی ہوتی ہے ۔\n\nدماغ کی آواز اس مرحلے پر عام ہوتی ہے — مرکزی کارکردگی ، ردِعمل وقت کی کمی محسوس ہوتی ہے اور تھوڑی دیر کیلئے یادداشت ناقابلِ‌برداشت محسوس ہو سکتی ہے ۔ سوچ اور یادداشت پر یہ اثرات ایبٹ آباد کے ساتھ بہتر ہوتے ہیں: 114 کاٹمین کے ایک طویل مطالعے نے لفظی یادداشت، نظریاتی یادداشت، منصوبہ بندی اور منصوبہ بندی کے بغیر 12 ہفتوں کے بعد، توجہ اور فیصلہ سازی میں اہم فوائد حاصل کیے۔\n\nبلے باز\nاگر آپ کے پاس cytamine-insioned cystitis (urinary emply, frequency, درد یا خون میں خون) ہے تو اب بلڈنگ کو صحت کے لیے بہترین موقع فراہم کرتا ہے۔ درد لوگوں کو خود کشی کرنے پر مجبور کر سکتا ہے — اس کی بجائے مناسب درد کی حمایت کے ساتھ ایک چکر توڑ سکتا ہے۔';

  @override
  String get ketamineReferenceDay14 =>
      'دو موسمِ‌گرما کو ختم کرنے والے\n\nماخذ: \"Ketamine-Induced Cystitis: A Comprehensive Review,\" on PubMed Central\n\nصاف‌گوئی\nاس دوا کو مکمل طور پر صاف کرنے کے ساتھ ساتھ ذہنی فوگ اور باقاعدہ کاٹن استعمال کرنے والی سوچ کو ختم کرنے لگتی ہے ۔ ذیابیطس اور مرکزیت میں بہتری اور ذہنی کیفیت پیدا ہوتی ہے ۔\n\nبُت‌پرستی کا آغاز\nشروع شروع میں cystitis کے لئے، تجزیے پر زور دیا جاتا ہے کہ صرف کیٹیمین کو روکنے سے رکنے والی علامات کو دوبارہ شروع کرنے کا ایک اہم ترین قدم ہے، اِس عمل کا آغاز دو ہفتے ہوتا ہے ۔';

  @override
  String get ketamineReferenceDay30 =>
      'ایک ماہ کیٹمین\n\nماخذ: \"Prevalence and Natural History of Urinary Symptoms Among Recreational Ketamine Users,\" Winstock et al., BJU International (2012)\n\nبِل‌دار کمر\nکیٹمین-انٹڈ cystitis کا واحد سب سے اہم علاج کیٹمین کو روک رہا ہے۔ اِس سے ظاہر ہوتا ہے کہ اِن علامات میں سے 51% اِستعمال کرنے کے بعد بہتری کی اطلاع دی گئی جبکہ 4% کے تحت اِس سے بھی بدتر ہو گیا ۔ اس سے پہلے کہ آپ رک جائیں، بہتر انجام ہے.\n\nذہن‌ودماغ\nایک مہینے کے اندر اندر کچھ لوگوں کو پتہ چل جاتا ہے کہ اُن کے دل میں کیا ہے ۔ ( ۱ - کرنتھیوں ۱۵ : ۵۸ ) اگر ہم چاہتے ہیں کہ ہم اپنے جیون‌ساتھی کی مدد کریں تو ہمیں اِس بات پر غور کرنا چاہئے کہ ہم اُس کی مدد کیسے کر سکتے ہیں ۔';

  @override
  String get ketamineReferenceDay90 =>
      'تین ماہ کیٹمین\n\nماخذ: \"Ketamine-Induced Cystitis: A Comprehensive Review,\" on PubMed Central\n\nدوبارہ کوشش جاری رکھیں\nلیکن اِس میں یہ بھی بتایا گیا ہے کہ اِس بیماری کی وجہ سے اِس میں بہتری آ سکتی ہے ۔ تین ماہ کے بعد اُس بہن‌بھائیوں کو اُن معاملات میں شفا دینے کے لئے وقت مل گیا جو اُن کے لئے فائدہ‌مند ثابت ہوں گے ۔\n\nدماغ\nظاہری سوچ اور رُجحان ابتدائی ردِعمل سے واضح طور پر واضح ہوتا ہے اور جذباتی طور پر زیادہ دیر تک کم ہوتے رہتے ہیں ۔ اِس کی وجہ یہ ہے کہ اِن علامات کا اندازہ اِس بات سے لگایا جا سکتا ہے کہ اِن علامات کو کس حد تک درست بنایا جا سکتا ہے ۔';

  @override
  String get ketamineReferenceDay180 =>
      'چھ ماہ بعد کیٹمین\n\nماخذ: \"Ketamine-Induced Cystitis: A Comprehensive Review,\" on PubMed Central\n\nنصف سال پر\nاِس کے علاوہ اِس بیماری کی وجہ سے اِس بیماری میں مبتلا لوگوں کو بہت سی مشکلات کا سامنا کرنا پڑتا ہے ۔ استعمال کرنے میں رکاوٹ کافی حد تک کمزور ہو گئی ہے ۔\n\nدوبارہ سے نشانات کو صاف کریں\nثابت‌شُدہ بِل‌دار نقصان کی بحالی نامکمل ثابت ہو سکتی ہے جس کی وجہ سے ابتدائی معاملات اتنے زیادہ ہیں ۔ آپ نے جو بھی قدم اُٹھایا ، اُسے بند کر دیا اور بِل‌دار کو اِس کا بہترین نتیجہ بھگتنا پڑا ۔';

  @override
  String get ketamineReferenceDay365 =>
      'ایک سال کیٹمین\n\nماخذ: \"Ketamine-Induced Cystitis: A Comprehensive Review,\" on PubMed Central\n\nایک سال\nبارہ ماہ کی شبنم بلددر کو دیتی ہے، ابتدائی صورتوں میں صحت یاب ہونے کا پورا موقع ملتا ہے اور سوچ اور یادداشت اور مزاج کے مستحکم اور روشن چھوڑ دیتا ہے۔ مشکل میں رکاوٹ پیدا کرنے والا نفسیاتی انحصار بہت زیادہ تباہ‌کُن ہے ۔\n\nبِھیڑ کی تصویر\nایک سال مفت ایک گہرا تبدیلی ہے یعنی جسمانی صحت، واضح اور خود مختاری میں۔ جو آپ کو یہاں حاصل کیا گیا ہے کی حمایت برقرار رکھنے کے.';

  @override
  String get kratomReferenceDay1 =>
      'کرایہ: پہلا دن ہے۔\n\nماخذ: Swogger et al. (2022), \"Understanding Kratom Use: A Guide for Healthcare Providers,\" Frontiers in Pharmacology\n\nمعجزے کیوں ہوتے ہیں ؟\nکراتوم کے فعال مرکبات ایک ہی اپائئیڈ مرکبات پر بطور کلاسیکی اوپیکز کام کرتے ہیں۔ جسم کو باقاعدہ استعمال کرنے کے ساتھ ساتھ اس طرح رکاوٹ پیدا کرنے سے ایک اپائڈ کی طرح حرکت پیدا ہوتی ہے۔ اِس کتاب میں بتایا گیا ہے کہ اِس میں اِس بات پر غور کِیا گیا ہے کہ باقاعدہ کس طرح کے استعمال کے خطرات کو تسلیم کِیا جاتا ہے ۔\n\nاِس بات کا کیا ثبوت ہے کہ یہوواہ خدا ہماری فکر رکھتا ہے ؟\nہدایت کار میں مذکور جانوروں کے مطالعے سے ظاہر ہوتا ہے کہ تقریباً 12 گھنٹوں کے اندر اندر سوماٹک ردِ عمل کی علامات ظاہر ہوتی ہیں، جس میں 24 گھنٹے سے ظاہر ہوتا ہے کہ جیسے اثرات ظاہر ہوتے ہیں؛ مکمل انسان آنموسٹ وقت کا تعین کم ہوتا ہے، لیکن عام طور پر ابتدائی علامات میں یہ بتایا گیا ہے:\n• مایوسی ، پریشانی اور مایوسی\n• مسکل ناک اور ناک\n• آنکھیں اور پانی کی آنکھیں\n• کرس‌ٹینا\n\nحد سے زیادہ کھانے پر غور کریں\nہدایت کار نوٹ کرتے ہیں کہ طویل عرصے تک استعمال اور زیادہ تر دواوں کا تعلق زیادہ شدید، طویل عرصے تک جاری رہنے والی تاخیر سے ہوتا ہے۔ اُوپر والے طبّی امداد کی ضرورت ہوتی ہے خاص طور پر اگر اُوپر والی دواوں یا اُپیائیڈز کے ساتھ کراتم کو استعمال کِیا جاتا تھا ۔';

  @override
  String get kratomReferenceDay3 =>
      'قُطب‌نما : سب سے بڑا دن\n\nماخذ: Singh et al. (2014), Drug and Alcohol Dependence — survey of 293 regular kratom users in Malaysia\n\nاس بات کا کیا ثبوت ہے ؟\nایک اندازے کے مطابق \'peak دن\' کی بجائے اس سروے نے سنگین راستے دریافت کیے کہ کس قدر اور کتنی دیر تک کسی کو استعمال کیا جاتا ہے: لوگ کرایہ روزگار کے تین یا اس سے زیادہ شیشے پی رہے تھے اور سخت انحصار اور مشکل رد عمل کا خاصہ رکھتے تھے۔ زیادہ تر لوگوں کے لیے رکنے کے بعد پہلے دن مشکل ترین ہوتے ہیں۔\n\nعام رپورٹ\n• مٹی اور جوڑوں کے جوڑ، بے امن ٹانگوں،\n• کمزوریوں کے باوجود انتہائی مایوسی\n• ناکا ، پیٹ کارمپس اور ڈائری وغیرہ\n• پریشانی ، مایوسی اور مایوسی\n• طاقت‌ور\n\nاس کے ذریعے حاصل کرنا\nHydration، آرام، اور ہنگامی مدد. اگر اِس حد تک سنگین صورتحال کا سامنا کرنا پڑ رہا ہے تو یہ حد سے زیادہ بھاری یا اِستعمال کرنے کی بجائے اِس سے زیادہ فائدہ اُٹھا سکتا ہے ۔';

  @override
  String get kratomReferenceDay7 =>
      'ایک ہفتے کے آخر میں کراتوم\n\nماخذ: Swogger et al. (2022), \"Understanding Kratom Use: A Guide for Healthcare Providers,\" Frontiers in Pharmacology\n\nاِس سے ظاہر ہوتا ہے کہ اُس کا ایمان مضبوط تھا ۔\nاس گائیڈ میں انسانی خود مختار اعداد و شمار سے پتہ چلتا ہے کہ زیادہ تر لوگوں کے لیے علامات کے اندر تقریباً ایک سے تین دن کے اندر ختم ہو جاتی ہیں۔ ایک ہفتے تک ، شدید جسمانی علامات — چیچک ، پس‌منظر ، دردِشقیقہ — نے اکثریت کیلئے ثابت‌قدم رہنے کی کوشش کی ہے ۔ اس سے بھی زیادہ نفسیاتی کیفیت پیدا ہو سکتی ہے : تھکاوٹ ، نیند کم اور کم محسوس جیسے کہ اپی‌ڈی‌ڈیکلز کراتم جسم کے اپنے اشاروں کی طرف واپس منتقل ہو رہا تھا ۔\n\nایک حقیقی خطرہ\nہدایت کار مزید بیان کرتے ہیں کہ ایک چھوٹی سی تعداد کو کراتم بہت مشکل پاتے ہیں، جس میں زیادہ سخت اور طویل عرصے تک جاری رہنے والے افراد نے بھاری، لمبے عرصے کے صارفین کے درمیان رپورٹ کی۔ یہ ہفتے دوبارہ شروع ہونے کا ایک عام نکتہ ہے اور جلد ہی تحمل کیساتھ آنے والی سابقہ دواوں میں واپس آ جاتا ہے ، خاص طور پر اگر اُن کا تعلق اُس وقت واقعی خطرناک ہوتا ہے ۔';

  @override
  String get kratomReferenceDay14 =>
      'دو موسمِ‌گرما\n\nماخذ: National Institute on Drug Abuse (NIDA), \"Kratom\"\n\nس . ع .\nکریپٹ ٹائم پر انسانی اعداد و شمار عام طور پر صرف پہلے چند دنوں پر محیط ہیں، اس لیے اس میں ایک مخصوص \'دو ہفتے\' میلے کو نیچے نہیں رکھا گیا ہے۔ کونسا وسیع نمونہ ہے: کروم ایک ہی اپائزڈ ریزوں پر کام کرتا ہے بطور کلاسکل اوپیکز اور جیسا کہ باقاعدگی سے استعمال کرنے والے ان خلیات کو آہستہ آہستہ جسم کے اشاروں پر اپنی حساسیت بحال کرتا ہے۔\n\nعام طور پر لوگوں کی رپورٹ\n• ایپیٹ اور توانائی اکثر بہتر ہوتی ہے۔\n• نیند زیادہ قابلِ‌اعتماد ہونے کی طرف مائل ہوتی ہے\n• مودود اب بھی تبدیلی لانے کے باوجود غیر فعال ہے\n\nاِس لئے اُن کے لئے منصوبہ‌سازی کرنا مفید ثابت ہوتا ہے ۔';

  @override
  String get kratomReferenceDay30 =>
      'ایک ماہ بعد\n\nماخذ: National Institute on Drug Abuse (NIDA), \"Kratom\"\n\nاَجر کا دَور\nNIDA کراتوم کو دماغ کے اپائزڈ خلیات پر عمل کرنے کے طور پر بیان کرتا ہے، انحصار اور رد عمل کے ساتھ باقاعدہ استعمال کے خطرات کے اعتراف کے طور پر۔ اس میں کوئی خاص مطالعہ نہیں ہے ایک \'ایک ماہ کی بحالی میلے‘ لیکن عام نمونہ برائے اپائزڈ-ریپٹر انحصار یہ ہے کہ دماغ کی جانب سے روز مرہ عیش و آرام کے لیے بتدریج معمولات کو برقرار رکھنے والے معمولات کے ساتھ ساتھ معمولات کا اطلاق ہوتا ہے۔\n\nاِس سے کیا مُراد ہے ؟\nاِس کے علاوہ وہ وقت اور کوشش کے ساتھ ساتھ اِستعمال بھی کرتے ہیں ۔ کرشن چندر کم مرتبہ آتے ہیں اور زیادہ پریشان کن محسوس کرتے ہیں، اگرچہ بلند ترین لمحات سب سے زیادہ بے چینی برقرار رکھتے ہیں۔';

  @override
  String get kratomReferenceDay90 =>
      'تین ماہ بعد\n\nماخذ: National Institute on Drug Abuse (NIDA), \"Kratom\"\n\nایک سٹیڈیئر روز کی ریاست -\nKratom Opioids پر کام کرتا ہے، تو اس کے بغیر تین ماہ دماغ کے اجرا اور دباؤ کے نظام کو مستقل طور پر حل کرنے کے لیے وقت فراہم کرتا ہے۔ بہتیرے لوگ واضح طور پر سوچ‌بچار کرتے ہیں اور مزید سرگرم استعمال سے حوصلہ‌افزائی حاصل کرتے ہیں ۔\n\nیہ کیوں ضروری ہے\nحال ہی میں استعمال ہونے والا یہ عمل دن‌بدن کم ہونے لگتا ہے — اس میل کو دائمی بحالی کیلئے ٹھوس بنیاد بنا دیتا ہے ۔';

  @override
  String get kratomReferenceDay365 =>
      'ایک سال کُرم کا شکار\n\nماخذ: National Institute on Drug Abuse (NIDA), \"Kratom\"\n\nاچھی طرح سے ماضی کی غلطیوں کا علاج\nNIDA ایک مخصوص ایک سالہ کریٹ بیک وقت لائن شائع نہیں کرتا، لیکن مستقل طور پر جاری رہنے والا ایک سال کراتم کی تحقیق میں شدید اور ابتدائی نفسیاتی طور پر پسماندہ کھڑکیوں سے باہر ہے۔ اِس بات پر غور کرنے سے ہمیں بہت فائدہ ہوتا ہے ۔\n\nبِھیڑ کی تصویر\nآذربائیجان کا ایک سال صحت، مالی اور خود مختاری میں غیر معمولی تبدیلی کی نمائندگی کرتا ہے۔ اس ترقی کو محفوظ رکھنے میں مدد دیتے ہیں ۔';

  @override
  String get maoiReferenceDay3 =>
      'MaOI Discontinuation: The High-Risk Phase -\n\nماخذ: Dilsaver (1988), research on MAOI withdrawal reactions\n\nتباہ‌کُن خطرناک آگاہی\nمیاو کسی بھی اینٹی‌رائڈ پریشر کلاس کے سنگین خطرات کا حامل ہے ۔ بالخصوص فن‌لینڈ اور تروانسیپرومین — شدید ردِعمل پیدا کر سکتے ہیں جن میں یہ شامل ہے :\n• شدید پریشانی اور پریشانی\n• بات‌چیت اور مایوسی پر زور دیا جاتا ہے\n• نیند یا نیند\n• ہم‌جنس‌پسندی\n• ڈیلیریئم اور پیرانئیڈ توہم‌پرستی\n\nاگر آپ ان علامات کا تجربہ کر رہے ہیں تو فوراً طبّی توجہ حاصل کریں ۔\n\nمَیں کیسے کام کرتی ہوں ؟\nMaOIS by University constituency of and ransome oxidase genes (MAO-A and MaO-B). یہ پروٹین عموماً سرتونین، ورپینیفرین، دوپمین اور دماغ اور گیٹ میں زہریلے مادوں کو توڑ دیتی ہیں۔ چونکہ جراثیم خود کو صرف بلاک کرنے کی بجائے تباہ کر دیا جاتا ہے اس لیے اس بات کا انحصار جسم پر ہوتا ہے کہ یہ دوا کتنی تیزی سے خون کو صاف کرتی ہے۔';

  @override
  String get maoiReferenceDay7 =>
      'ایم اوس کے بعد سے ایک ہفتم : MaO Enzyme Sentnes serway -\n\nماخذ: \"Monoamine Oxidase Inhibitors (MAOIs)\" (StatPearls, NCBI Bookshelf)\n\nاِن سوالوں پر غور کریں :\nایس آر آئی ، SNRIs اور TCAs — جو دماغ کے کیمیائی ردِعمل کو تیز کرنے والی دوبارہ شروع کر دیتی ہے — اینٹی‌باڈیز ماس ( Fhenelzine, Tranylcypromine) دائمی طور پر مونو ایسڈز ڈائی‌سی‌سی‌م‌سی‌م‌سی‌م‌مس‌مسکلم کو تباہ کر دیتا ہے ۔ لہٰذا انتقالِ‌خون کے عمل سے جسم کتنا تیزی سے نئے نظام میں داخل ہو سکتا ہے — تقریباً ۲ ہفتوں — یہ دوا بذاتِ‌خود خون کو تیز کرنے کی بجائے ۔\n\nایک ہفتے میں کیا ہو رہا ہے\n• MaO-A اور MaO-B Nico Sentis اچھی طرح سے چل رہی ہے، ~2 ہفتوں کی بازنطینیوں کی کھڑکی کے ذریعے گزر رہی ہے۔\n• ۳ دن کے دوران بیان‌کردہ خطرناک خطرے کا مرحلہ گزر رہا ہے اگرچہ قریبی طبّی نگرانی اہم ہے\n\nاِس کے علاوہ اُس نے کہا : ” مَیں . . .\nایم آئی اے کے علاج میں کم مقدار میں ہونے والی غذا کی ضرورت ہوتی ہے، کیونکہ یہ پروٹین عام طور پر ٹیورمین کو توڑ کر اس کو ایک ہائیپرانسی بحران کو روکنے سے روک دیتے ہیں۔ ہدایت یہ ہے کہ اس انکار کی کھڑکی کے ذریعے موت کی پابندیوں کا مشاہدہ کرتے رہیں — آپ کا مشیر جب انہیں آرام کرنے کے لئے محفوظ ہو تو مشورہ دے گا۔';

  @override
  String get maoiReferenceDay14 =>
      'میری اوس کے بعد دو ہفتوں کا آغاز : مَاو انس‌مَنَّا سُلطَّقِّی طور پر دوبارہ پیدا ہوتا ہے\n\nماخذ: Fritz et al. (1983), Biological Psychiatry\n\nمارپیٹ دوا مارک\nدو ہفتوں کے بعد ، ایک خاص قسم کا ٹی‌این‌کیپررمین یا فی‌ہن‌لین‌ین‌ین‌ین‌ین‌ین‌ین‌کین کے لئے استعمال ہونے والا معیاری عذاب ہے ۔ اس تحقیق سے پتہ چلا ہے کہ پلیٹ‌لیٹ ایم‌او-بی‌بیکل سرگرمی — دو ہفتوں کے اندر اندر اندر معمول میں کمی — جیسے کہ جسم منشیات کے استعمال کے پلیٹ‌لیٹس کو تازہ‌شُدہ پروٹین کے ساتھ تبدیل کرتا ہے ، اگرچہ مکمل ایم‌او-بی پروٹین کی مقدار کبھی بھی تبدیل نہیں ہوتی تھی ۔\n\nمَیں نے اُن سے پوچھا : ” کیا مَیں واقعی خدا کی خدمت کر رہا ہوں ؟ “\n• پلیٹلیٹ MAO-B سرگرمیاں اس نقطہ نظر سے بالکل ٹھیک ہو چکی ہیں۔\n• دماغ MaO-A اور MaO-B، جو ایک ایسی ہی طرح کے ریاضی ٹائم لائن کی پیروی کرتا ہے، کو بھی بڑی حد تک بحال کیا جاتا ہے۔\n• عام طور پر Tyraminous دوبارہ حل کیا جاتا ہے — MIOI Deathary پابندیوں کو اپنے مشیر سے مشورہ کرنے والے کے ساتھ نرمی سے بات‌چیت کی جا سکتی ہے\n\nدماغ-Chemical توازن بحال کرتا ہے۔\nMaONational سرگرمیوں کے ساتھ، دماغ کے وہ کیمیائی نظام جو MAOIS اثر انداز ہوتے ہیں، قدرتی طور پر زیر عمل آنے لگے ہیں:\n• سروتنین، ناسیپینیفرین اور دوپمین کو اب میاوشن سے بلندی نہیں دی جا رہی ہے۔\n• Monoamine spectivity of Monomine specials (district by special MaOI-reseral-chemical rates) حل کرنا شروع ہو جاتا ہے۔\n• قدرتی مزاج اور توانائی کی کمیت واپس آ رہی ہے۔';

  @override
  String get maoiReferenceDay30 =>
      'MAOIS کے ایک ماہ بعد: دماغ-Chemical Systems Rebalaings -\n\nماخذ: \"Monoamine Oxidase Inhibitors (MAOIs)\" (StatPearls, NCBI Bookshelf)\n\nیکم منٹ کے اشعار ہیں۔\nMAOI Dicontinuation کے ایک ماہ بعد اس ماخذ میں بیان کردہ 2 وکٹوں سے بخوبی پہلے موجود ہے، لہذا اس نقطہ مجوزہ سرگرمی سے مکمل طور پر صحت یاب ہو گیا ہے اور دماغ کے کیمیائی نظام مکمل طور پر مکمل طور پر زیر عمل ہیں۔\n\nایک مہینے میں کیا واقع ہوا ہے\n• مکمل MaONNational سرگرمی: مئو-A اور MaO-B دونوں مکمل عمل میں آتے ہیں۔\n• ڈی‌وی‌ڈی پابندیوں نے فیصلہ کِیا : عام خوراک کی پابندیوں کے بغیر ہی پابندیوں کو ختم کر دیتی ہے\n• قدرتی سروٹونین خوارزم: دماغ کا نارمل سروتونین چکر بحال کرتا ہے۔\n• قدرتی طور پر کی جاتی ہے کیو ایمو کی عملداری : دوپمین اور Norepinefrine کی سطحیں قدرتی کام کے زیرِاثر ہیں۔\n\nمنشیات کا عمل\nمیاواس کا تعلق حیاتیاتی مواصلات سے ہے جس میں سروٹون ادویات کے ساتھ منسلک ہیں۔ ان مواصلاتی خطرات نے ایک ماہ کے نشان پر حل کیا ہے۔ تاہم، ہمیشہ اپنے مشیر اور فقہی فقہا کو اس وقت آگاہ کرتا ہے جب کوئی نئی دوا تجویز کی جاتی ہے۔';

  @override
  String get maoiReferenceDay90 =>
      'ایم اوس کے تین مہینے بعد : قدیم زمانے کے واقعات\n\nماخذ: \"Antidepressant Withdrawal Syndrome,\" Therapeutics Letter 112 (2018), Therapeutics Initiative, on the NCBI Bookshelf\n\nمخالفِ‌مسیح کلاسوں کا آغاز\nاِس سلسلے میں ایک مثال پر غور کریں ۔ اِس مضمون میں ہم اِن سوالوں پر غور کریں گے ۔ \'عام طور پر روک کے چند دنوں میں ظاہر ہوتا ہے\' اور \'بہت زیادہ ... 2 ہفتوں کے اندر حل کریں،\n\nجہاں تین ماہ کی جگہیں\nتین ماہ تک ، تیز رفتاری سے چلنے والا مرحلہ لوگوں کی بڑی اکثریت کے پیچھے اچھا ہے اور جسم مریخ کے بغیر مونومین کی حوصلہ‌افزائی کرنے کیلئے کافی دیر تک تیار رہتا ہے ۔\n\n\'Receptor Resenentation\' پر دوبارہ دستخط کریں گے۔\nماہرین کا دعویٰ ہے کہ سروتونین، یانیپینفرین، اور دوپمین کی تمام \'تین مہینے کی حد سے تجاوز کرتے ہیں\' ان ثبوتوں سے باہر جا رہے ہیں جو نیچے ہیں۔ کیا چیز ہے: پیچھے ہٹ جانے والا مرحلہ اب تک حل ہو چکا ہے اور زیادہ تر لوگوں کے مزاج، توانائی اور جذباتی فضاء کے لیے قدرتی، نفسیاتی طور پر خود سے تعلق رکھنے والے دماغی سگنلنگ پر چوٹیں لگ رہی ہیں۔\n\nقدیم ورس دوبارہ دریافت\nاِس خط میں یہ ہدایت دی گئی ہے کہ ہم کسی حقیقی صورتحال سے کنارہ کریں ۔ اگر علامات تین ماہ تک برقرار رہیں تو اُن سے مشورہ لینے کی بجائے اُن کا جائزہ لیں کہ وہ اِسے نظرانداز کر رہے ہیں ۔';

  @override
  String get maoiReferenceDay180 =>
      'ایم او ایس کے چھ ماہ بعد: طویل ترم ریکی (انگریزی:\n\nماخذ: Zwiebel & Viguera (2022), Cleveland Clinic Journal of Medicine\n\nچھٹے منٹ کے اشعار ہیں۔\nاِس جائزے میں بتایا گیا ہے کہ اینٹی‌رائڈ فشز ایک دوسرے کے کام آتے ہیں جس کی وجہ سے مُنہ کے اندر داخلے کی وجہ سے وقت گزرنے کے ساتھ ساتھ اِس دوا بند ہو جاتی ہے ۔\n\nجہاں چھ ماہ کی چھٹی نشستیں ہیں۔\nچھ ماہ کے زمانے میں اس بات کا انتظار کر رہا ہے کہ ہفتے بھر کے دوران بڑے پیمانے پر لوگوں کی بڑی اکثریت کے لئے کھڑکی کے ساتھ، جنھوں نے پہلے مہینے میں مکمل طور پر معمول قائم کیا تھا. Recupy signal: مکمل طور پر serotonin، enepinephine کے لیے ٹائمز اور دوپمین فیکلٹی صحافت میں روزمرہ کے یقینی سے قائم نہیں کیے جاتے — یہ بات قابل یقین ہے کہ چھ ماہ تک، زیادہ تر لوگ قدرتی، نفسیاتی طور پر دماغ کے سگنلنگ پر کام کر رہے ہیں۔\n\nفن‌لینڈ کا ایک نوٹ\nمَیں نے دیکھا ہے کہ اِس بیماری کی وجہ سے مَیں بہت کمزور ہو گئی ہوں ۔ اِس کی وجہ یہ ہے کہ اِس کی وجہ یہ ہے کہ اِس کی وجہ سے اِس بات کا اندازہ نہیں لگایا جا سکتا کہ اِس بیماری کی وجہ سے اِس کی وجہ سے اُس کی صحت خراب ہو جائے گی ۔';

  @override
  String get maoiReferenceDay365 =>
      'میری اوس کے ایک سال بعد : بحالی تحصیلدار\n\nماخذ: \"Monoamine Oxidase Inhibitors (MAOIs)\" (StatPearls, NCBI Bookshelf)\n\nایک سال : ایک کامیاب کامیابی\nمَیں نے دیکھا ہے کہ مَیں ایک سال کے بعد ایک خاص میل‌جول رکھتا ہوں ۔ MAOIs سب سے زیادہ طلب کرنے والے ادویات میں شامل ہیں انائیڈ پریشر کو ختم کرنے کے لیے، ایک کم مقدار میں کم مقدار میں کھانے والی غذا، اور منشیات کے استعمال کے اقدامات جو کسی دوسرے انائیڈ پریسنگ کلاس کے مقابلے میں ہیں۔\n\nیہ سال کیا نمائندگی کرتا ہے\n• قدرتی طور پر مکمل طور پر خود مختار مونومین آکسائیڈ سرگرمیوں کا ایک بھرپور سالمہ جس نے پہلی ماہ میں مکمل کیا تھا۔\n• منشیات سے پرہیز کرنے کے بغیر اچھی صحت برقرار رکھنے کی صلاحیت\n• اِس بات کا یقین کرنے کے لئے کافی وقت لگتا ہے کہ اِس دَور میں آپ کو کیا کرنا ہوگا ۔\n\nمیاو پر غور کریں\nMAOIS بعض علاج کی شرائط اور ایک ہنگامی ڈپریشن کے لیے منفرد طور پر مؤثر رہا ہے. کامیاب ڈسکنیشن ادویات کے طور پر ان کی قدر کم نہیں کرتی — یہ دماغ کی صحت کی صلاحیت کو ظاہر کرتی ہے اور مریض کو غیر معمولی طور پر طبی عملے کی جانچ کرنے کی صلاحیت کو ظاہر کرتی ہے۔ ایک دائمی احتیاط: گزشتہ MOI استعمال کے بارے میں کسی بھی نئے مشیر یا Anesthetheist کو بتانے کے لیے، کیونکہ کچھ منشیات کے استعمال کے خطرات ہمیشہ کے قابل ہوتے ہیں۔';

  @override
  String get marijuanaReferenceDay1 =>
      'ماریجوانا اوبلاست : دن یکم\n\nماخذ: \"The cannabis withdrawal syndrome: current insights,\" Substance Abuse and Rehabilitation (2017), on PubMed Central\n\nکُل‌وقتی خدمت\nیہ نظری جائزہ قائم کرتا ہے کہ کینابیس اوبلاست (CWS) ایک نہایت منظم مرکب شرط ہے، جو 90% لوگوں کو روکنے کے بعد کینز انحصار کے ساتھ بیمار ہو جاتی ہے۔ اس کی اوسط اُونچائی تانبے کے انتقالِ‌خون کی طرح ہے ۔\n\nمعجزے کیوں ہوتے ہیں ؟\nاِس کے علاوہ اِس بات پر بھی زور دیا جاتا ہے کہ اِنسان کا دماغ اِس حد تک بگڑ جاتا ہے کہ اُس کا دماغ اُس کی صحت پر اثر کرتا ہے ۔ اس نظام کو ہمیشہ کے لئے استعمال کرتے ہوئے دماغ نیچے کی طرف اشارہ کرتا ہے ؛ جب کین‌بیس رک جاتی ہے تو یہ عارضی طور پر زیرِاثر ہوتا ہے ۔ سی بی‌بی‌ایم‌ایس کے جائزے کے مطابق اب تک تقریباً چار ہفتوں کے اندر اندر دوبارہ عام کام کِیا جاتا ہے ۔\n\nایک دن کے لئے،\nاس بات کا جائزہ لینے سے پہلے کہ جسمانی علامات ظاہر ہوتی ہیں — آخری استعمال کے ۱– ۳ دن کے اندر — جبکہ نفسیاتی علامات ۲– ۱۰ دن کے دوران ظاہر ہوتی ہیں ۔ ابتدائی علامات میں شامل ہیں:\n• مایوسی ، پریشانی اور مایوسی\n• آرام‌دہ نیند\n• دباؤ کی وجہ سے مایوسی\n• جسمانی دباؤ ، پس‌منظر یا تھکاوٹ\n• ذہنی رُجحان\n\nحد سے تجاوز\nسی‌وی‌ایس طبّی طور پر خطرناک نہیں ہے اور علامات اعتدال‌پسندی کے لئے نرم ہو جاتی ہیں لیکن جائزے کے مطابق وہ دوبارہ گاڑی چلانے کیلئے کافی پریشان‌کُن ہو سکتے ہیں — جس کی وجہ سے وقتی معاملات کو سمجھنا مشکل ہے ۔';

  @override
  String get marijuanaReferenceDay3 =>
      'کینابیس وقتی لائن : ابتدائی دنوں\n\nماخذ: \"Time-course of the DSM-5 cannabis withdrawal symptoms in poly-substance abusers,\" BMC Psychiatry (2013), on PubMed Central\n\nایک پیمائشی وقت-\nاس مطالعے نے ڈی ایس ایم-5 کینابس کو چار ہفتوں کے دوران 90 مریضوں میں علامات تبدیل کر دیا، جس سے ایک واضح تصویر بنائی گئی ہے کہ علامات کس طرح بڑھتی ہیں اور کس طرح گرتی ہیں۔ سب سے بڑھ کر ایک موڑ کے بعد : اُٹھنے کے بعد اگلے ہفتوں میں گر جاتا ہے ۔\n\nکوہِ‌قاف کی ابتدا\nروک تھام کے ابتدائی دنوں میں جسمانی طور پر لگنے والی کئی علامات میں سے چند ایک یہ ہیں:\n• انس‌منیا — دن کے چاروں اطراف کی چوٹیاں ۱\n• مایوسی — دن کے چاروں اطراف کی چوٹیاں\n• ذہنی رُجحان اور جسمانی علامات — دن کے اُوپر اُونچائی ۵\n• مایوسی — ⁠ دن کے چاروں اطراف کی چوٹیاں ۶\n\nبعدازاں کونسی پیک\nتحقیق سے پتہ چلا ہے کہ پہلے ہفتے کی نسبت کچھ علامات ظاہر ہوتی ہیں :\n• وید ، ناخوشگوار خواب — دن کے گرد اُونچائی 11\n• غصے اور غصے کی شدت — دن کے اُوپر اُونچائی 14\n\nنیند اور کین‌بیس\nاِس کے بعد اُن کے ذہن میں اِس بات کی خواہش پیدا ہوتی ہے کہ وہ اُن کی مدد کریں تاکہ وہ اُن کی مدد کر سکیں ۔ مصنف اِس بات پر بحث کرتے ہیں کہ اُن کے خیال میں اُن کی سوچ بدل گئی ہے اور اُن کی سوچ بدل گئی ہے ۔\n\nتیسرے دن کیلئے وقف\nآپ تین دن تک جسمانی اُفق کی گہری تہ میں رہتے ہیں ۔ اِس سلسلے میں ایک مثال پر غور کریں ۔';

  @override
  String get marijuanaReferenceDay7 =>
      'ایک ویک بے کینابس (انگریزی: Week La Kannabis): جنگ عظیم دوم کے ذریعے\n\nماخذ: \"The cannabis withdrawal syndrome: current insights,\" Substance Abuse and Rehabilitation (2017), on PubMed Central\n\nکہاں سے ایک ہفتہ‌وار سیٹ\nاِس تحقیق سے پتہ چلا ہے کہ یہ دستاویز عموماً تین ہفتوں تک قائم رہتی ہے جس میں پہلی اور تیسرے ہفتے کے درمیان سب سے زیادہ پریشان‌کُن مدت ہوتی ہے ۔ ایک ہفتے میں ، ابتدائی جسمانی علامات — بےچینی ، تھکاوٹ ، آرام‌وآسائش — اپنی انتہا تک پہنچ چکی ہیں ۔\n\nابھی تک کیا کچھ ہو رہا ہے\nتجزیے میں جسمانی علامات کو بعد کے نفسیاتی امراض سے ممتاز کیا جاتا ہے۔ ایک ہفتے میں:\n• جسمانی تکلیف اور توانائی بڑی حد تک بہتر رہی ہے۔\n• نیند اب بھی بہتیروں کیلئے ناقابلِ‌رسائی خوابوں ( آر ایم‌ایم‌ایس ) کے ساتھ اُوپر کی طرف اُڑ رہی ہے\n• چونکہ یہ پہلے دو ہفتوں بعد کی انتہائی بلندیوں کی طرف اشارہ کرتے ہیں\n\nریکی کا نیورابولوجی\nان تبدیلیوں کے تحت ، جائزے میں بیان کِیا گیا ہے کہ تقریباً چار ہفتوں کے اندر اندر عام کارکردگی کی طرف رجوع کِیا جاتا ہے ۔ ایک ہفتے میں ، یہ دوبارہ پیدا ہونے والا عمل کافی حد تک کم ہوتا ہے — اس نظام میں بھی کچھ علامات قائم رہتی ہیں ۔\n\nمُلک\nایک ہفتے تک پہنچنے کا مطلب یہ ہے کہ جسمانی اُونچائی آپ کے پیچھے ہے ۔ نیند اور مزاج کی علامات ایک ایسی بیماری کا حصہ ہیں جسکی وجہ سے اِس بیماری میں مبتلا ہونے کی وجہ سے اُس کا علاج جاری رہتا ہے ۔';

  @override
  String get marijuanaReferenceDay14 =>
      'دو ویک بے کینابیس: Acuteal district district district district district\n\nماخذ: Budney, AJ et al. (2003) — peer-reviewed study on cannabis withdrawal time course\n\nتلاشیں\nاس ساتھی مطالعے نے باقاعدہ صارفین میں علامات نکالنے کے وقت کے کورس کو بے نقاب کر دیا۔ اِن دریافتوں سے ظاہر ہوتا ہے کہ پہلے ہفتے میں مریض کی بیماری کی وجہ سے اُس کی صحت خراب ہو جاتی ہے اور اُس کی زیادہ‌تر علامات کی روک‌تھام کے 2 ہفتوں بعد حل ہوتی ہیں ۔\n\n۲ ہفتوں کا آغاز\nمطالعے نے یہ نتیجہ اخذ کِیا کہ ۱۴ دن تک ، مندرجہ‌ذیل علامات نے مطالعے والوں میں بڑی حد تک حل کِیا تھا :\n• جسمانی تکلیف اور بیماری کی علامات\n• غیر متصل خطرات\n• زیادہ‌تر نیند خراب ہو جاتی ہے\n• پریشان‌کُن اور پریشانی\n\n۲ عالمی اُفق\nتحقیق سے یہ بھی پتہ چلا کہ وہ علامات جو کچھ صارفین میں دو ہفتے کے نشان سے تجاوز کر رہی تھیں:\n• ذہنی رُجحان\n• مشکلات\n• نیند کی کیفیت (عام طور پر بہتری )\n\n2- ویکی مارک کی نشان دہی\nدو ہفتے کے نشان کو عبور کرنا اہمیت کا حامل ہے کیونکہ اس کا مطلب یہ ہے کہ اس کا مطلب شدید بخار کا شکار ہونا بہت زیادہ مکمل ہے۔ بنیادی طور پر اس نقطہ سے آگے والے چیلنجز کا تعلق طویل عرصے سے دماغ کی بحالی سے ہے اور اس کی اصل وجوہات کا انتظام کیا جاتا ہے، بلکہ روکنے کے لئے سخت رد عمل۔';

  @override
  String get marijuanaReferenceDay30 =>
      'ایک ماہ بغیر کین‌بیس : میموریل میں کمی\n\nماخذ: Pope et al. (2001), Archives of General Psychiatry\n\nکین‌بیس اور میموریل : مسئلہ\nاس مطالعے کے بعد بھاری، طویل مدتی کینز صارفین نے 28 دنوں تک تصدیق آذربائیجان سے کی اور ان کی سوچ اور میموریل ٹیسٹ کے نتائج کا موازنہ ہلکے صارفین اور غیر کارندے سے کیا۔ اُنہوں نے کہا : ” جب مَیں نے اِس بات پر غور کِیا کہ مَیں اُن لوگوں کی مدد کیسے کر سکتا ہوں جو خدا کے کلام میں درج اصولوں کے مطابق زندگی گزار رہے ہیں تو اُن کے دل میں یہ خواہش پیدا ہو جاتی ہے کہ مَیں اُن کی مدد کروں ۔ “\n\nخوشخبری : یومِ‌کفارہ پر بحالی\n28 دن تک بھاری صارفین، ہلکے صارفین اور غیر صارفین نے مطالعے کی سوچ اور یادداشت کے امتحانات میں عملی طور پر ایک ہی طرح کا مظاہرہ کیا۔ اس دور میں مجموعی طور پر کینز کے استعمال اور امتحانی کارکردگی کے درمیان بھی کوئی اہم تعلق نہیں تھا۔\n\n۳۰ دنوں میں اس بات کا کیا مطلب ہے ؟\n• باربال سیکھنے اور یاد رکھنے کے لیے گروپ کی سطحوں پر کنٹرول کرنے میں واپس آ گئے ہیں۔\n• پہلے ہفتے میں دیکھے جانے والے فضول‌گوئیوں نے حل کِیا ہے\n• اس سے پہلے باقی ماندہ پستانوں کو حالیہ طور پر لگنے والے اثرات سے وابستہ کیا گیا تھا نہ کہ دائمی نقصان\n\nاس بات کا کیا ثبوت ہے ؟\n28 دن تک بھاری صارفین کو عملی طور پر روشنی کے صارفین اور غیر صارفین کی جانب سے مطالعے کے مکمل سیٹ اور یادداشت کے امتحانات سے لیس کر دیا جاتا تھا۔ پہلے ہفتے میں دیکھا گیا تھا کہ گروہی سطحوں کو کنٹرول کرنے کے لئے دوبارہ کابل کی تعمیر اور یاد تازہ ہو گئی تھی۔';

  @override
  String get marijuanaReferenceDay60 =>
      'دو ماہ بغیر کین‌بیس : دو مہینے کے اندراندر اُس کی صحت بہتر ہو گئی\n\nماخذ: Roten et al. (2015), Addictive Behaviors\n\nتحقیقی سوال\nاس نوجوان کینسبیس-سیشنل مطالعے نے یادداشت پر تحقیق کی اور سوچ کے ٹیسٹ اسکور کیے جو تقریباً دو ماہ کے اندر اندر اندر اندر جاری رہنے والے صارفین کے ساتھ موازنہ کرتے رہے جنھوں نے حال ہی میں روک دیا یا رہا ہو\n\nکلیدی تلاش\nاشتیاق عبدالمطلب کا تعلق اہم بہتری سے تھا:\n• ضرب شدہ میموری اسکور\n• وربال میموری خاص طور پر متاثر کن ڈومین —\n• تحریک اور رد عمل\n\nدو ماہ بعد\nآٹھ ہفتوں تک اتفاق رائے، یادداشت اور حرکت اور رد عمل کے اسکورز کے ذریعے مریخ پر چڑھنے لگے تھے جہاں وہ سرگرم استعمال کے دوران بیٹھے تھے، اس بات کی تصدیق کرتے ہوئے کہ وہ تنہا وقت کی بجائے غیر استعمالات کی تصدیق کرتے ہیں۔\n\nمطالعے کا مضمون کیا ظاہر کرتا ہے\nنوجوانوں اور نوجوانوں میں جوڑوں پر انحصار کرتے تھے ، اُنہوں نے مناسب طریقے سے دو ماہ کے علاج کی کھڑکیوں میں مکمل یادداشت ، لفظی یادداشت اور حرکت اور ردِعمل سے بھرپور فائدہ اُٹھایا ۔';

  @override
  String get marijuanaReferenceDay90 =>
      'تین ماہ کینابس کے بغیر: مودود اسٹیبلشمنٹ واپسی\n\nماخذ: Connor et al. (2022), Addiction — a clinical review of cannabis withdrawal\n\nحقیقت میں کس چیز نے وقت کو دیکھا\nاِس جائزے میں بتایا گیا ہے کہ 24–48 گھنٹے کی علامات کو ختم کرنے اور اِس پر قابو پانے کے بعد 24–48 گھنٹے لگتے ہیں ۔ غصے ، زیادتی اور ڈپریشن کا شکار ہونے کی وجہ سے ایک ہفتے کے اوائل میں ہی نظر آ سکتا ہے لیکن اُنکی اُونچائی دو ہفتوں کے بعد زیادہ ہو سکتی ہے ؛ خاص طور پر نیند دوسری علامات سے زیادہ طویل ہو سکتی ہے ۔\n\nجہاں تین ماہ کی جگہیں\nتین ماہ تک ، آپ اس سے بھی زیادہ دور ہیں : علامات کا آغاز 24–48 گھنٹوں کے اندر ، اُونچائی 2–6 کے ارد گرد ، اور اگلے ہفتوں کے اندر اندر بھی شدید رُجحان اور نیند کی علامات سے ہوتا ہے ۔ انیس دن ان لوگوں کو بے ہوش کرنے اور نیند کے اثرات بس میں رہنے کے لئے کئی ماہ.\n\nاِس شمارے کے خصوصی مضامین\nکینابیس-جس کی تحقیق سے یہ بھی ظاہر ہوتا ہے کہ اب تک تقریباً چار ہفتوں کے اندر عام کارکردگی کی طرف واپس لوٹنے والے سی بی‌بی‌بی‌بی‌بی‌ایس بھی ظاہر ہوتا ہے ۔ 90 دن میں، آپ کو اس خالی کھڑکی سے باہر اچھی طرح ہیں.\n\nمستقبل کو دیکھیں\nاس جائزے میں اس بات پر بھی بحث کی گئی ہے کہ پروکسیس کے بعد اور رد عمل میں رکاوٹ کے تحت،';

  @override
  String get marijuanaReferenceDay180 =>
      'چھ ماہ بغیر کیننبیس: Planning and Decing-Mecing Recution –\n\nماخذ: Crean, Crane & Mason (2011), Journal of Addiction Medicine\n\nکانابیس کے بعد منصوبہ بندی اور فیصلہ سازی کا کام دیتا ہے۔\nاس جائزے میں طویل عرصے کے دوران استعمال ہونے کے بعد پہلے گھنٹے سے توجہ، فیصلہ سازی، خود مختاری، کام کی یاد اور کلامی کی جانچ کی گئی تھی۔ چھ ماہ تک آپ مختصر مدتی اثرات سے بہت آگے ہیں اور بحالی کی مدت میں گہری گہرائی ہے۔\n\nتحقیق سے کیا پتہ چلا ہے ؟\nاِس لئے اُس نے اُن سے کہا : ” مَیں اِس بات کا خیال رکھتا ہوں کہ مَیں اُن سے بات کروں گا ۔ “ بھاری ہونے کے بعد بحال کرنے کے لیے سب سے سستے علاقے شامل ہیں:\n• فیصلے سازی اور خطرے سے دوچار — مخصوص طور پر ڈومینکس کے طور پر جانا جاتا ہے جہاں بھاری، مستقل استعمال کرنے والے لوگ طویل عرصے تک جاری رہ سکتے ہیں۔\n• بالخصوص ایسے بالغوں میں جو ۱۷ سال سے پہلے استعمال کرنا شروع کر چکے تھے\n\nابتدائی-ونسیٹ بحالی\nچھ ماہ اس جائزے میں مختصر مدتی اثرات سے دور ہے۔ منصوبہ بندی، فیصلہ سازی اور استدلال کو برقرار رکھنے کے ساتھ ساتھ مزید بحالی کے لیے سب سے مضبوط راستہ بناتا رہا۔\n\nبُت‌پرست تصویر\nبالغوں کے لیے، ہلکا استعمال، نظریہ زیادہ قابل رحم ہے — چھ ماہ کی رپورٹ میں بہت سے لوگ واضح طور پر سوچ بچار، متبادل فیصلہ سازی اور خود کشی کا مضبوط احساس رکھتے ہیں۔ سب سے بڑی حاصلات، بالخصوص بھاری یا جلدی استعمال کے بعد';

  @override
  String get marijuanaReferenceDay365 =>
      'ایک سال بغیر کین‌بیس : دماغ کی شریانیں دوبارہ پیدا ہو جاتی ہیں\n\nماخذ: \"Hippocampal harms, protection and recovery following regular cannabis use,\" Translational Psychiatry (2016), on PubMed Central\n\nکین‌بیس کی طرف سے ناقابلِ‌برداشت تبدیلیاں\nدماغ کے اس مطالعے نے ہندسہ، دماغ کا مرکزی علاقہ، موجودہ صارفین، سابق صارفین اور غیر صارفین کا جائزہ لیا۔ موجودہ صارفین کو سی بی ڈی سے ظاہر نہیں کیا گیا تھا تقریباً 11% چھوٹے اور دماغ کے سیل صحت کی نشان دہی کنٹرولز کے مقابلے میں تقریباً 15% کم ہوتی تھی۔\n\nاِن سوالوں کے جواب تلاش کریں : اپنے ایمان پر قائم رہیں\nکریول انالیز نے ایک \"دہشت گردی اور بحالی\" ماڈل کی حمایت کی۔ کاروباری طور پر ، سابقہ صارفین — تقریباً 29 مہینوں تک اوسطاً — کسی بھی راستی کی پیمائش پر کنٹرول کرنے سے فرق نہیں تھے ۔ مصنف یہ نتیجہ اخذ کرتے ہیں کہ THC سے متعلقہ میموریل-رے کو نقصان پہنچتا ہے \"ابیض کے وسیع عرصے سے صحت یاب ہو سکتی ہے\"۔\n\nدماغ سال اور اُس سے بھی زیادہ عرصے تک تازہ رہتا ہے\nایک سال کینابس آزاد، دماغ کے ذکی نظام کو اچھی طرح سے بحالی میں رکھا جاتا ہے: ہیمپوکیپس سائز اور دماغ کے سیل صحت عامہ کی طرف لوٹ مار، یادداشت اور جذباتی کنٹرول کی حمایت کرتی ہے۔\n\nدوبارہ سے نشانات کو صاف کریں\nسابقہ صارفین نے مطالعے کے ہیلی کاپٹر صحت کے اقدامات پر تقریباً 29 ماہ کے لیے غیر صارفین کو اغوا کر لیا۔ ایک سال پہلے ہی یادو کا نظام معمول کی طرف بحالی کے راستے کے ساتھ چل رہا ہے ۔';

  @override
  String get mdmaReferenceDay1 =>
      'ایم‌آئی‌وی کے بعد : آئی‌وی‌لینڈ\n\nماخذ: Meyer (2013), \"3,4-Methylenedioxymethamphetamine (MDMA): Current Perspectives,\" Substance Abuse and Rehabilitation\n\nآپ کو ادنیٰ کیوں محسوس ہوتا ہے\nایس . اے . بعد ازاں دماغ کو عارضی طور پر سروٹونین سے محروم کر دیا جاتا ہے۔ اس جائزے میں ہمہ وقت کی کمیت کو بیان کیا گیا ہے — جنہیں استعمال کرنے کے بعد محققین نے نووکٹ اور تجربہ کار صارفین دونوں میں 2 سے 5 دن کا اندازہ لگایا ہے۔\n\nکیا چیز مدد دیتی ہے\n• حوصلہ‌افزائی اور صحت‌بخش خوراک\n• نیند\n• صبر — ایک مستقل ریاست نہیں ہے ۔\n\nایک دوسرے کے استعمال کے بعد آنے والی آمدنی انحصار سے متعلق رد عمل سے مختلف ہوتی ہے، جس میں ایک ہی جائزے میں انتہائی غیر محسوس علامات کو بیان کیا گیا ہے لیکن اس کی کوئی اہم جسمانی علامات نہیں ہیں۔';

  @override
  String get mdmaReferenceDay3 =>
      'میسو دوم کے چند دن بعد\n\nماخذ: Meyer (2013), \"3,4-Methylenedioxymethamphetamine (MDMA): Current Perspectives,\" Substance Abuse and Rehabilitation\n\nسورج کی روشنی میں\nیہ کھڑکی اس جائزے کی وضاحت کر رہی ہے جب اس میں \"میڈ ہفتے کے نیلے نیلے\" پر بحث کی گئی ہے — خلاء میں ایک دو سے 5 دن بعد نیویس اور تجربہ کار دونوں میں استعمال ہونے والے صارفین کو استعمال کرنے کے بعد، لمبے عرصے کی تبدیلی کی بجائے مختصر مدت میں سرتونین کو منسلک کرنے کے لیے منسلک کیا گیا ہے۔\n\nاِن سوالوں پر غور کریں\n• اس وقت کے ارد گرد موجود اپنے نچلے نقطہ سے زمین کو اٹھا لیتے ہیں۔\n• توانائی واپس آتی ہے۔\n• نیند معمول سے شروع ہوتی ہے۔';

  @override
  String get mdmaReferenceDay7 =>
      'میمن کے بعد ایک ہفتم\n\nماخذ: Meyer (2013), \"3,4-Methylenedioxymethamphetamine (MDMA): Current Perspectives,\" Substance Abuse and Rehabilitation\n\nموسمِ‌گرما کے نیلے رنگ\nزیادہ تر لوگوں کے لئے، ایک ہفتہ 2-5 دن کی کھڑکی سے گزر رہا ہے اس جائزے کے ساتھیوں کے ساتھ. غور کریں کہ جو لوگ بہت زیادہ یا بار بار استعمال کرتے ہیں ، اُن کے لئے یہ بات قابلِ‌غور ہے کہ اِس میں جسمانی علامات کو نظرانداز کرنے والے لوگوں کے طور پر استعمال کِیا گیا ہے ۔\n\nمدد حاصل کرنے کیلئے\nاگر ایک ہفتے میں ذہنی رُجحان ، پریشانی یا نیند کے مسائل پیدا ہو جاتے ہیں تو یہ ایک پیشہ‌ور شخص سے بات‌چیت کرنے کے قابل ہو سکتا ہے ۔';

  @override
  String get mdmaReferenceDay14 =>
      'دو ہفتے کے سفر\n\nماخذ: Meyer (2013), \"3,4-Methylenedioxymethamphetamine (MDMA): Current Perspectives,\" Substance Abuse and Rehabilitation\n\nدوبارہ سے وقت نکالنے\nایک واحد استعمال آنے کے لئے، دو ہفتے پہلے ہے 2 سے 5 دن اس جائزے کی دستاویزات، تو مزاج، نیند، اور مرکزیت کو مستحکم ہونا چاہیے۔ بھاری یا بار استعمال کرنے کے بعد ، بحالی کا کام آنے والے ڈاؤن‌لوڈ سے باہر بھی جاری رہتا ہے اور انف‌صوتی کے مطالعے میں سرتونین کی طرفداری کی صلاحیت کو ظاہر کرتا ہے جس میں مستقل‌مزاجی کا مظاہرہ کِیا جاتا ہے ۔\n\nآپ کیلئے اس کا کیا مطلب ہے ؟\nاگر کبھی آپ کا استعمال ہوتا تو آپ غالباً اس کے بدترین سے گزرتے ہیں۔ اگر یہ بار یا بھاری ہوتا تو صبر سے کام لیں — سروٹون سگنلنگ کی مکمل بحالی دو ہفتوں سے زیادہ کا عمل ہے جو اگلی میلوں پر محیط ہوتا ہے ۔';

  @override
  String get mdmaReferenceDay30 =>
      'ایک ماہ بعد\n\nماخذ: \"Serotonin transporter availability, neurocognitive function and their correlation in abstinent MDMA users,\" on PubMed\n\nجہاں ایک ماہ کی چھٹی ہوتی ہے\nآپ کے پس‌منظر اور سوچ‌وفکر اور یاد‌وفکر بہت بدل جاتے ہیں ۔ تصوراتی تحقیق سے پتہ چلتا ہے کہ مجوزہ دماغ کی صلاحیت کو سرتونین کے عمل میں کمی کرتا ہے اور یہ صلاحیت مستقل طور پر برقرار رہنے والی بے چینی کے ساتھ بحال ہوجاتی ہے۔\n\nدوبارہ سے نشانات کو صاف کریں\nاسی تحقیق سے معلوم ہوتا ہے کہ سرتونین-ری سائیکلنگ کی صلاحیت مستقل طور پر غیر مستحکم ہوتی ہے۔ مود اور سرونٹن کام میں سب سے پہلے بہتری آتی ہے جبکہ میموریل اپنی بحالی کے اوقات پر جاری رہتا ہے — ابی‌سلوم نے دونوں کی حمایت کرتے ہوئے بھی مدد کی ہے ۔';

  @override
  String get mdmaReferenceDay90 =>
      'تین مہینوں کا وقفہ\n\nماخذ: \"Serotonin transporter availability, neurocognitive function and their correlation in abstinent MDMA users,\" on PubMed\n\nدوبارہ کوشش جاری رکھیں\nبرقرار رکھنے کے ساتھ ساتھ دماغ کا سرٹونین نظام صحت بحال کرتا رہتا ہے، خاص طور پر گہرا دماغ کے علاقوں میں۔ اس نقطہ نظر سے مدھو اور سوتے بہت پائیدار ہوتے ہیں۔\n\nدوبارہ سے نشانات کو صاف کریں\nباقی رہنے والی بے چینی تحریکوں نے ذہنی حلقوں میں سروتونین-ترنسپورٹر بحالی کا سلسلہ جاری رکھا، جب کہ ذہنی اور نیند مستحکم رہتی ہے اور سوچ اور یاد کی بحالی کرتی رہتی ہے۔';

  @override
  String get mdmaReferenceDay365 =>
      'ایک سال کا وقفہ\n\nماخذ: \"Serotonin transporter availability, neurocognitive function and their correlation in abstinent MDMA users,\" on PubMed\n\nایک سال\nایک سال کے ساتھ دماغ کی سروتونین آپریٹنگ بے حد صحت یاب ہو گئی ہے اور اس کا مزاج مستحکم ہے۔\n\nدوبارہ سے نشانات کو صاف کریں\nآذربائیجان کا ایک مکمل سال سروٹون کے نظام کو طویل بحالی کی کھڑکی فراہم کرتا ہے ۔ تصوراتی تحقیق سے پتہ چلتا ہے کہ سروتونین-ری سائیکلنگ کی صلاحیت اُٹھتی ہے، جس کی وجہ سے اس مرحلے میں نمایاں ترین حیاتیاتی سگنل بحال کیا جاتا ہے۔';

  @override
  String get methReferenceDay1 =>
      'Metham specine Central: First 24 گھنٹے\n\nماخذ: McGregor et al., \"The nature, time course and severity of methamphetamine withdrawal,\" Addiction (2005), on PubMed\n\nکراس\nجب استعمال ہوتا ہے تو نظامِ‌شمسی ختم ہو جاتا ہے ۔ اِس تحقیق سے ظاہر ہوتا ہے کہ اِس بیماری کی وجہ سے اِن علامات کو ختم کر دیا جاتا ہے ۔\n\nجس دن زمین کو جھٹکا دیا جائے گا\nمطالعے نے اس ردِعمل کی خصوصیات کو اُجاگر کِیا جو اب بہت زیادہ شدت اختیار کر رہی ہیں :\n• بے حد تھکن اور نیند میں اضافہ (hephersomnia)۔\n• بڑھتی ہوئی بھوک ( شدید دباؤ )\n• مایوسی اور عیش و آرام کا شکار\n• طاقت‌ور\n• پریشانی اور پریشانی\n\nجسمانی حفاظت\nmetham specine River Memberum بذات خود زندگی سے متعلقہ علامات عام طور پر نہیں ہیں، تاہم اس مطالعے سے متعلقہ علامات کا اندازہ اس مطالعے میں لگایا گیا ہے اور اس میں حیاتیاتی خیالات بھی شامل ہو سکتے ہیں۔ طبّی نگرانی خاص طور پر بھاری صارفین کے لیے سخت استعمال کی جاتی ہے۔\n\nاِس میں تبدیلی لانا شروع ہو جاتا ہے\nاس تحقیق سے حاصل ہونے والی حوصلہ افزائی: ابتدا میں شدت زیادہ ہوتی ہے اور پھر گرتی ہے۔ اس 24 گھنٹے کی بلندی سے آئندہ دنوں میں علامات مسلسل کم ہو جاتی ہیں — بدترین نقطہ آغاز ہے۔';

  @override
  String get methReferenceDay3 =>
      'پیدائش : تین دن — ابھی تک ای‌کوِس پَس میں\n\nماخذ: McGregor et al., \"The nature, time course and severity of methamphetamine withdrawal,\" Addiction (2005), on PubMed\n\nپیک سے نیچے آتے ہیں۔\nاِس تحقیق سے پتہ چلا ہے کہ پہلی 24 گھنٹے کے اندر اندر مجموعی طور پر زیادہ‌تر شدت والی چوٹیاں اِس مشکل مرحلے میں داخل ہو رہی ہیں ۔ تین دن تک آپ سب سے اعلیٰ مقام حاصل کر رہے ہیں لیکن پھر بھی اس مشکل مرحلے میں ثابت‌قدم رہتے ہیں کہ علامات بھی اس رُجحان کو کم کر دیتی ہیں ۔\n\nتین دن\nمطالعے کی خصوصیات جو اب بھی اہمیت کا حامل ہیں :\n• مایوسی اور عیش‌وعشرت میں کمی\n• طاقت‌ور\n• حوصلہ‌شکنی اور سوچ‌بچار واضح طور پر واضح ہو جاتا ہے\n• نیند کی کمی — ہائی‌وے‌وےس‌منیا\n• تھکے ہوئے\n\nایسا کیوں محسوس ہوتا ہے\nمریخ کی شدت اس کی وجہ سے پیدا ہونے والی دوپمین کے پیمانے کی عکاسی کرتی ہے۔ اس مطالعے سے متعلقہ علامات ان ابتدائی دنوں میں سب سے نمایاں ہیں — لیکن اہم بات یہ ہے کہ مطالعے نے مجموعی طور پر ” آذربائیجان کے پہلے ہفتے کے آخر تک کنٹرول کی سطح کے قریب جانے کی شدت کو محسوس کِیا ہے ۔ “\n\nیہ ختم ہو جائے گا\nسب سے مشکل دور پہلے چند دنوں کا ہے اور ڈیٹا یہاں سے مسلسل کمی ظاہر کرتا ہے۔ اس حالت کو عارضی اور ذہنی اور اعصابی طور پر سمجھنا دائمی حالت نہیں بلکہ اس سے گزرنے میں مدد دیتا ہے ۔';

  @override
  String get methReferenceDay7 =>
      'ایک ویک بے میٹر : ایکسچینج پِس ختم ہو جاتی ہے۔\n\nماخذ: McGregor et al., \"The nature, time course and severity of methamphetamine withdrawal,\" Addiction (2005), on PubMed\n\nاکی‌ٹی‌ایس کا اختتام\nیہ تحقیق میں سب سے زیادہ حوصلہ افزائیی نتائج میں سے ایک ہے۔ تحقیق نے بیان کِیا کہ مجموعی طور پر ڈپریشن کی علامات جن میں ڈپریشن کی علامات شامل ہیں — ’ ایبٹ آباد کے پہلے ہفتے کے آخر تک کنٹرول سطحوں کے قریب جانے میں مدد دی گئی ہے ، ‘ یہ خطرناک مرحلے کے اختتام کا نشان ہے ۔ آپ کے پیچھے بلندی کا سب سے بڑا حصہ ہے۔\n\nاِس کے دو مصرعے\nمصنفوں نے متداول ہونے کا بیان یوں بیان کیا ہے:\n• تقریباً ۷– ۱۰ دن کا ایک طویل مرحلہ جس میں شدید شدت اپنی ابتدائی بلندی سے مسلسل گرتی رہتی ہے\n• کم‌ازکم دو ہفتوں کے بعد ، نرم‌مزاج اور غیرمعمولی علامات\n\n۷ دن میں کیا کچھ باقی رہا ہے ؟\nصوبائی سطح کے مرحلے میں داخل ہونے کے بعد اب غالب چیلنج تباہ ہونے کی بجائے نفسیاتی مشکلات کا شکار ہیں:\n• پست مزاج ہونے کے باوجود پہلے دنوں سے بہت بہتر ہو گیا ہے۔\n• کُل‌وقتی خدمت کرنے والے لوگ خاص طور پر کِیا کرتے تھے\n• یاد رکھیں اور یاد رکھیں\n• ابھی تک نیند پوری نہیں ہوئی\n\nجسمانی طور پر کُل‌وقتی خدمت\nتیز رفتار مرحلے کے ساتھ ساتھ توانائی واپس آ گئی ہے اور توانائی آہستہ آہستہ تعمیر کر رہی ہے جب جسم نیند، غذا اور جسم کی کمیت کے اثرات سے ٹھیک ہو جاتا ہے۔';

  @override
  String get methReferenceDay30 =>
      'ایک مہینے کے بغیر : مُنادی کے کام میں حصہ لینے والے لوگ\n\nماخذ: Zorick et al., \"Withdrawal symptoms in abstinent methamphetamine-dependent subjects,\" Addiction (2010), on PubMed Central\n\nپہلی پانچ ہفتوں کا سفر\nاس مطالعے کے بعد میٹہم ایپنمین-دیپنڈنٹ شرکاء نے جو پانچ ہفتوں تک تک ان کا موازنہ کرتے رہے، ان کا موازنہ صحت مند کنٹرول سے کرتے ہوئے — ایک غیر معمولی تصویر پیش کی جس میں ایک ماہ کی نشان دہی کی گئی تھی۔\n\nایک مہینے میں کیا واقع ہوا\n• غیر جانبدار علامات \'مریخ کے پہلے 2 ہفتوں میں غیر مستحکم سطحوں کو مستحکم کرنے کے لیے،‘ اور چار ہفتوں کے اختتام تک قریب رہا، اگرچہ ابھی تک جوہری، صحت مندانہ طور پر سطحوں (یعنی خلاء ایک حد تک، غیر علامتی رُجحان پر تنگ ہو گیا تھا)۔\n• نفسیات اور نفسیاتی قسم کی علامات دوسرے ہفتے کے آخر تک کم از کم شروعاتی سطح تک پہنچ چکی تھیں۔\nلہٰذا ۳۰ دن کے دوران ، شروع میں ڈپریشن کی سنگین وجہ سے اُٹھ کھڑا ہو گیا ہے — ایک حقیقی ، درست حالت کا تعیّن کریں ۔\n\nاب تک کیا کچھ واقع ہوتا ہے\nمطالعے سے یہ بات واضح ہو گئی کہ دوسروں کو خارج کر دینا: خواہش ہے کہ 5 ہفتوں کے دوران میں بھی کم مقدار میں جاری رہنا باقی رہے‘ کرشن پہلے ہفتے کی نسبت کمزور ہیں لیکن اب تک نہیں ہوئے، اسی لیے ایک ماہ ایک اعلیٰ مدت ہے اور مسلسل حمایت کے معاملات جاری ہیں۔\n\nمُلک\nایک ماہ تک دماغ کے مزاج مشینری کافی صحت یاب ہو چکی ہے اس دن کے شروع سے پہلے کی نسبت یہ محسوس بہت بہتر ہے کہ جب کہ مستقل مزاجی اس مرحلے کا معمول ہے، ناکامی کی علامت نہیں ہے۔';

  @override
  String get methReferenceDay90 =>
      'تین مہینے بے مرہٹہ: شفا حسین بیگن — صابر رہیں –\n\nماخذ: Volkow et al., \"Loss of Dopamine Transporters in Methamphetamine Abusers Recovers with Protracted Abstinence,\" Journal of Neuroscience (2001)\n\nاس تحقیق کے بارے میں\nاِس تحقیق کے بعد دو ماہ کے اندر اندر اندر اندر داخل ہونے والے دماغ کے ماہرین نے دو مرتبہ — تین ماہ کے اندر اندر اندر اور ۱۴ ماہ کے آس‌پاس دوبارہ — یہ دیکھنے کے لئے کہ دوپی‌مین سسٹم کیسے بحال کرتا ہے ۔\n\nجہاں تین ماہ کی جگہیں\nتین مہینوں میں ، ابتدائی تاخیر کی مدت طویل اور گہرے دوا‌مین کی بحالی کا سلسلہ چل رہا ہے ۔ اسی مطالعے کے بعد یہ دریافت ہوا کہ دماغ کے اجرا اور حرکت کے شعبوں میں موجود پروٹین کی مقدار 16 تا 19 فیصد تک بڑھ گئی جبکہ 12–17 ماہ کے بعد مریخ سے ٹکرانے کے بعد۔\n\nآپ کیلئے کیا مطلب رکھتے ہیں ؟\n90 دن تک آپ کی صحت خراب ہو جاتی ہے ، آپ کے مزاج اور نیند بہتر ہو جاتی ہے اور علاج سے وابستگی اَور زیادہ پھلدار ہو جاتی ہے ۔ لیکن اگلے سال سب سے زیادہ گہری دوا کی بحالی کا منصوبہ ہے ۔ اگر ابھی تک تحریک اور عیش‌وعشرت کو تین ماہ کا خطرہ محسوس ہوتا ہے تو یہ توقع کی جاتی ہے کہ ناکامی کی علامت نہیں ہے — اس مطالعے میں کششِ‌ثقل کا اظہار بالکل واضح ہے ۔\n\nانتظار کیوں ہے؟\nاسی مطالعے نے ظاہر کِیا کہ بقا وہی چیز ہے جو بحالی کے عمل کو تحریک دیتی ہے : طویل عرصے تک ، ڈی‌ٹی‌ٹی کی بحالی کی پیمائش کی گئی ہے ۔ تین مہینوں کی بنیاد ہے ؛ حاصل ہونے والی برکات ۔';

  @override
  String get methReferenceDay180 =>
      'چھ ماہ بغیر موت : دل کو دوبارہ ڈھانپ سکتا ہے۔\n\nماخذ: \"Stopping Drug Abuse Can Reverse Related Heart Damage,\" American College of Cardiology (2017), reporting a study in JACC: Heart Failure\n\nمیٹ اور دل\nmetham lifemine سب سے زیادہ خطرناک ادویات میں سے ایک ہے۔ اس سے دل کی بیماریوں کی وجہ سے دل کی ناکامی کا باعث بننے والی بیماریوں میں اضافہ ہو سکتا ہے ۔\n\nمطالعے کے مضامین کا مقصد\nاے بی سی نے میمتھ انفنٹریاپتھی کے مریضوں کے بارے میں بتایا (سب کچھ غیر معمولی طور پر دل چسپی کم کرنے والی سرگرمی کے ساتھ)۔ مرکزی، امیدوار تلاش: \'اس دوا کو نقصان پہنچا کر دل تک پہنچ سکتے ہیں اور دل کو بہتر بنانے کا کام انجام دے سکتے ہیں‘ ایسے مریض جنہوں نے استعمال کرنے والوں کی نسبت نہایت بہتر نتائج اخذ کرنا بند کر دیے تھے، اور مصنفوں نے اس پر زور دیا تھا کہ اسے ابتدائی طور پر پکڑ کر \'ہنگامی حالت کو مزید خراب کرنے سے روکا جائے‘۔\n\nچھ ماہ کے معاملات\nہر مہینے جب آپ کے دل پر زہریلی بیماری چھا جاتی ہے تو اِس سے آپ کے دماغ پر اثر پڑتا ہے ۔ چھ ماہ کے اندر اندر آپ نے اس نقصان سے نپٹنے کیلئے اپنے غیرمعمولی نظام کو قائم رکھا ہے جسکے تحت اس مطالعے نے بہتری دیکھی ہے ۔\n\nدوبارہ سے نشانات کو صاف کریں\nثبوت واپس کیے جانے والے نتائج مضبوط ہیں: حدیث روک سکتی ہے metham specine-constant دل کی خرابی کو الٹ سکتا ہے اور دل کی کارکردگی کو بہتر بنا سکتا ہے۔ چھ ماہ تک بار بار کئے جانے والے طعنے کے بغیر دل کو دوبارہ بحال کرنے والی کھڑکیاں کھلی رہتی ہیں ۔';

  @override
  String get methReferenceDay365 =>
      'مریخ کے بغیر ایک سال\n\nماخذ: Wang et al., \"Partial Recovery of Brain Metabolism in Methamphetamine Abusers After Protracted Abstinence,\" American Journal of Psychiatry (2004), on PubMed\n\nتصورات کیا ظاہر کرتے ہیں\nاس دماغ کے مطالعے نے آذربائیجان میں شروع میں میمم ایپیمین صارفین کا جائزہ لیا اور پھر 12–17 ماہ کے بعد دوبارہ شروع ہوا۔ یہ حقیقی دماغ کی بحالی کو ملی جس میں بعض علاقوں کی نسبت زیادہ تیزی سے بڑھ رہی ہے ۔\n\nدی گڈ نیوز: دلی-برین اور سوچ رکھنے والے ہیں۔\nThalamus، ایک گہرا دماغ ریل مرکز، لمبے عرصے کے ساتھ توانائی کا استعمال عام طور پر شروع کیا۔ اس بحالی نے بہتر تحریک اور لفظی طور پر نمودار ہونے والی کارکردگی کا رخ کیا تو دماغ کی بہتری نے حقیقی سوچ اور یادداشت میں سامنے آئے۔\n\nاِس کا نتیجہ کیا نکلا ؟\n12–17 مہینوں میں گہری دماغی ریلیز کا مرکز شدید طور پر بحال ہو چکا تھا اور بہتر حرکت اور لفظی یادوں سے پتہ چلتا ہے۔ انعام اور حوصلہ افزائی کے نظام بھی مضبوط رہے، ایک سالہ تصویر کو سوچ اور یادو میں ایک بڑی بحالی قرار دیا۔\n\nایک سال میں اس کا کیا مطلب ہے ؟\nایک سال کے اندر اندر ایک ایسے دماغ کی توقع کی جاتی ہے جو صحت سے بالکل بہتر ہے ۔ لیکن اگر کبھی کبھی خوشی محسوس کرنے کی صلاحیت یا صلاحیت کبھی ختم ہو جاتی ہے تو یہ سائنس سے مطابقت رکھتی ہے ، ذاتی ناکامی کی بجائے : اس مطالعے سے یہ انعام‌یافتہ سرکٹ زیادہ آہستہ بحال ہو سکتے ہیں ، جس میں سے بعض اب بھی اچھی طرح سے موجود ہوتے ہیں ۔';

  @override
  String get methReferenceDay420 =>
      '۱۴ ماہ بے مرہ : دوپمین مارکر رینچ\n\nماخذ: Volkow et al., \"Loss of Dopamine Transporters in Methamphetamine Abusers Recovers with Protracted Abstinence,\" Journal of Neuroscience (2001)\n\nسرِورق کی تصویر\nاس قابل ذکر دماغ-سکن مطالعے نے آذربائیجان کے ابتدائی صارفین اور تقریباً 12–17 ماہ کے بعد دوبارہ دریافت کیا۔ پرتین کہ دماغ کے اجرا اور حرکت کے شعبوں میں 16 سے 19% اضافہ ہوا اور سطح تک پہنچ گیا کہ صحت مند کنٹرول سے کوئی خاص فرق نہیں آیا۔ اُس نے اُس سے کہا : ” تُم . . .\n\nمعاملات کیوں پریشان ہوتے ہیں\nیہ پروٹین خارج ہونے کے بعد ڈبلین خارج کرتے ہیں ۔ اِن میں سے ایک کا نام اِستعمال کِیا گیا ہے ۔ تقریباً ۱۴ ماہ تک اُنکا خون ایک حقیقی اور صحت‌بخش نشان ہے ۔\n\nدوبارہ سے نشانات کو صاف کریں\n12–17 مہینوں کے بعد اجرت اور تحریک کے شعبوں میں Dopamine-recyling پروٹین تقریباً 16% تا 19% اٹھنے لگے اور صحت مند سطح تک پہنچ گئے۔ دوامین کا نظام معمول کی طرف مائل ہونے کے باوجود سوچ ، یادداشت اور حرکت میں بہتری لانے کی طرف مائل ہے ۔\n\n14 ماہ میں اس کا کیا مطلب ہے۔\nدوپمین سسٹم کا ہارڈ ویئر عام طور پر قابلِ برداشت ہے — اصل وجہ یہ ہے۔ لیکن مکمل عملی بحالی (انگریزی، تحریک، عمدہ موٹر کنٹرول) امیجنگ کے پیچھے رہ سکتی ہے اور مسلسل ریبیز کے ساتھ بہتری لانے کا عمل جاری رہتا ہے۔';

  @override
  String get methReferenceDay730 =>
      'دو سال بغیر موت کے : سوچ‌بچار اور مؤثر ثابت‌قدم رہیں\n\nماخذ: Iudicello et al., \"Longer Term Improvement in Neurocognitive Functioning and Affective Distress Among Methamphetamine Users Who Achieve Stable Abstinence,\" Journal of Clinical and Experimental Neuropsychology (2010), on PubMed Central\n\nایک سال جاری رہنے والی بحالی\nاس مطالعے نے تقریباً 13 ماہ تک میٹروپولیٹن صارفین کے بعد اسٹوڈیوز کا موازنہ جاری رکھنے والے صارفین اور صحت مند کنٹرولرز سے کیا۔ اُنہوں نے کہا : ” مَیں نے اپنی زندگی یہوواہ خدا کے لئے وقف کر دی ہے ۔\n\nاِن سوالوں پر غور کریں\n• احتیاط سے کام لینے والوں کی تمام سوچ صحت کے کنٹرول میں آ گئی جبکہ صارفین نے غیرمعمولی طور پر ناقابلِ‌رسائی زندگی بسر کر لی\n• سب سے بڑی کمائی تیز رفتار اور موٹر صلاحیت میں تھی، خاص طور پر ان لوگوں کے لئے جو شروع میں سب سے زیادہ تیزی سے کام کرتے تھے۔\n• مؤید نے واضح طور پر ترقی کی: صرف پرہیز گاروں نے ڈپریشن اور مجموعی طور پر جذبات میں کافی بہتری ظاہر کی تھی۔\n\nدوبارہ سے نشانات کو صاف کریں\nاُنہوں نے کہا : ” مَیں نے اِس بات پر غور کِیا کہ مَیں کیا کر سکتا ہوں ۔ وربال سیکھنے، کام کی یادداشت، منصوبہ بندی اور توجہ پہلے سال سے زیادہ بہتر ہو سکتی ہے اس لیے بحالی کا عمل جاری رہتا ہے۔\n\nدو سال\nثبوت پر مبنی پیغام : مستقل‌مزاجی پہلے سال کو اچھی طرح ادا کرتی ہے — تیز سوچ ، بہتر مزاج اور مسلسل بہتری — اگرچہ چند علاقوں کو واپس لانے کیلئے زیادہ وقت لگتا ہے ۔';

  @override
  String get nitrousOxideReferenceDay1 =>
      'ایک دن : گیس بہت تیز ہوتی ہے لیکن بی ۱۲ کو دیکھیں ۔\n\nماخذ: Knuf & Maani, \"Nitrous Oxide,\" StatPearls (NCBI Bookshelf)\n\nیہ کتنی تیزی سے صاف ہے\nاِس کی وجہ یہ ہے کہ اِن میں سے دو سے ۵ منٹ کے اندر اندر جسم سے خارج ہو جاتا ہے اور اِسے روکنے کے لیے فوراً ہی جسم سے خارج ہو جاتا ہے ۔ آج تک گیس میں سے کوئی بھی آپ کے نظام میں باقی نہیں رہا۔\n\nحقیقی خطرات گیس نہیں\nاِس سلسلے میں ایک مثال پر غور کریں ۔ وٹامن بی ۱۲ پر انحصار کرنے والی ایک اینٹی‌باڈیز آکسائیڈ میں پایا جاتا ہے ۔ ماہرین کا کہنا ہے کہ بار بار متاثر ہونے والی چیزوں — پر قابو پانے والی قوتِ‌برداشت — میگالوبلاست اینامیا اور دماغ اور دماغ کی بیماریوں کا باعث بن سکتی ہے اور بعض‌اوقات ریڑھ کی ہڈی کی ہڈی کا سرطان پیدا ہو سکتا ہے ۔\n\nاگر آپ خود کو دوسروں سے بہتر سمجھتے ہیں یا اکثر اِسے استعمال کرتے ہیں تو\nنائٹروس آکسائیڈ کو یہ مشورہ نہیں دیا جاتا کہ ایک جسمانی طور پر منتقل ہونے والا دماغ اس طریقے سے اپائوائڈ یا الکحل کا کام کرے، اس طرح ایک دن آپ کے جسم کے بارے میں منشیات کا مطالبہ نہیں ہے. یہ بی12 سے متعلقہ علامات پر توجہ دینا شروع کرنے کے بارے میں ہے — اگلے چند میلوں میں — اور اگر کوئی دکھائی دیتا ہے تو جائزہ لینا۔';

  @override
  String get nitrousOxideReferenceDay3 =>
      '72 گھنٹے : کوئی بھی جسمانی نظام نہیں ، لیکن نیوٹرینو کے لئے انتظار کریں\n\nماخذ: Knuf & Maani, StatPearls; Tikaria et al. (2026), Cureus\n\nاوپیئمائڈز یا الکحل کے برعکس نائٹروس آکسائیڈ کسی جسمانی طور پر انتقالِ‌خون کا سبب بننے کے لئے خارج نہیں ہوتا. اس مرحلے میں نقل‌مکانی عادت اور خواہش ہے نہ کہ جسم منشیات کو عمل میں لانے کا تقاضا کرتا ہے ۔\n\nان کیلئے انتظار کریں\nایک منظم تجزیے میں 1،809 وائرس کی بیماریوں (Tikaria et al، 2026ء) کے واقعات (Tikaria et al., 2026ء) دریافت ہوئے دماغ اور اعصابی علامات — خاص طور پر ٹی‌بی‌بی‌سیس ( Paresthesia) — سب سے عام طور پر B12 سے تعلق رکھنے والے نقصان کی علامت تھی ، جب معیاری خون کے ٹیسٹ معمول کو دیکھا جاتا تھا تو اکثر ظاہر ہوتا تھا ۔ گوتم بدھ کے مسائل اور کمزوریوں کی اطلاع بھی دی گئی۔\n\nاگر آپ ان میں سے کسی پر غور کریں تو\nطبّی جائزہ لیں ۔ اِسی جائزے نے خون کے معیاری ٹیسٹز (haeeomonic) دریافت کِیا (hae B12) متاثرہ مریضوں کا ایک بامقصد حصہ — ⁠ ٹیسٹ برائے athylmalonic acid (MMA) اور ہوموسیکسی‌سٹائن کو زیادہ حساس ہوتے ہیں اور خاص طور پر دریافت کِیا جا سکتا ہے کہ اگر آپ نائٹروجن آکسائیڈ کو ظاہر کرتے ہیں تو اُسے خاص طور پر طلب کِیا جانا چاہئے ۔';

  @override
  String get nitrousOxideReferenceDay7 =>
      'اِن سوالوں کے جواب دیں : ” کیا مَیں آپ سے بات کرنا چاہتا ہوں ؟ “\n\nماخذ: Tikaria et al. (2026), \"The Toxic Legacy of Recreational Nitrous Oxide Use,\" Cureus\n\nاس بات کا کیا ثبوت ہے ؟\nاِس نظامی جائزے سے پتہ چلا ہے کہ وٹامن بی12 کی کمی کی وجہ سے اکثر \"فرکشنل\" ہوتی ہے — جیم B12 متاثرہ مریضوں کے آدھے مریضوں میں عام نظر آتی ہے، حتیٰ کہ جب اُن کے دماغ اور اعصابی نقصان کا حقیقی شکار ہوتا تھا۔ ہومیوکیستن اور ایم ایم اے بہت زیادہ غیر مستحکم تھے (84% اور 73% امتحانی مریضوں کی کارکردگی) اور زیادہ قابل اعتماد نشان دار ہیں۔\n\nکیا کرنا ہے؟\nاگر آپ کا استعمال سنگین یا باربار ہوتا ہے تو ایک ہفتے کے دوران ڈاکٹر کو دیکھنے کا مناسب وقت ہوتا ہے اور اُسے ہوموسیٰ اور ایم‌ایم پرکھا جاتا ہے ۔\n\nدماغ کی بحالی کے بعد عموماً وٹامن بی12 علاج کِیا جاتا ہے : علاج کے بعد زیادہ‌تر مریضوں میں بڑے سی‌ڈی‌ڈی‌سیسیسی‌سیسیسی رپورٹ یا مکمل بہتری واقع ہوتی ہے جس میں علاج کے پہلے مہینوں میں بحالی کا عمل جاری رہتا ہے ۔';

  @override
  String get nitrousOxideReferenceDay14 =>
      'دو ہفتوں: دماغ اور دماغ کی نالیوں کا پیچھا کرتے ہوئے\n\nماخذ: Tikaria et al. (2026), Cureus; Knuf & Maani, StatPearls\n\nکیا رپورٹ دی گئی ہے\nکیس رپورٹوں اور سیریز کا جائزہ تکیریا ایٹ ایل نے کیا۔ اِس سے ظاہر ہوتا ہے کہ اِس بیماری کی وجہ سے اِس بیماری کی وجہ سے اِس بیماری کا شکار ہو جاتے ہیں ۔\n\nٹائم‌لائنز پر دوبارہ سے دستخط\nاِس میں یہ بھی بتایا گیا ہے کہ اِس بیماری کی وجہ سے اُن کی صحت خراب ہو جاتی ہے ۔ کیس بیان کرتا ہے کہ مکمل بحالی سے لے کر مستقل‌مزاجی تک مختلف نتائج کی بابت بیان کرتا ہے جس کا انحصار اس بات پر ہے کہ تشخیص سے پہلے کتنا نقصان ہوا تھا ۔ لٹریچر میں جو کچھ مناسب ہے وہ یہ ہے کہ پہلے علاج سے بہتر نتائج حاصل ہوتے ہیں۔\n\nاگر آپ کو چیک نہیں کیا گیا تو\nدو ہفتے اب بھی خون کے کام کرنے کا اچھا وقت ہے ، حتیٰ‌کہ علامات کے بغیر بھی — خاص طور پر ہوموسیٰ‌تھی‌ٹن اور ایم‌ایم‌اے — اکیلے بی‌ایم‌اے بی ۱۲ کی بجائے ۔';

  @override
  String get nitrousOxideReferenceDay30 =>
      'ایک ماہ : ہابٹ اور کرایہ ، جسمانی مناسبت سے نہیں ۔\n\nماخذ: Knuf & Maani, \"Nitrous Oxide,\" StatPearls (NCBI Bookshelf)\n\nجہاں آپ کھڑے ہیں\nStatiperles Nitrous oxide کی وضاحت نہیں کرتے جیسے کہ جسمانی انحصار کا لاحقہ پیدا ہوتا ہے، تو ایک ماہ کا مطلب یہ ہے کہ کسی بھی قسم کی تلقین عادت، سماجی سیاق و سباق کے بارے میں ہے، یا پھر جسم ابھی تک منشیات کی عدم موجودگی کی طرف مائل ہے۔\n\nبی ۱۲ سوال\nاگر آپ کو بی‌12 کی کمی کا سامنا کرنا پڑا ہے تو ایک مہینے بعد ڈاکٹر کو یہ جاننے کی ضرورت ہے کہ آیا آپ کی سطح اور ہر قسم کی علامات نے آپ کی مدد کی ہے یا نہیں ۔ اگر آپ ٹیسٹ نہیں ہوتے اور بہت زیادہ استعمال نہیں کرتے تھے تو پھر بھی سوال کرنا ضروری ہے۔\n\nکیا حوصلہ افزائی ہے\nہر ماہ آپ استعمال نہیں کرتے ایک ماہ میں آپ کسی بھی موجود مِتَوَینِین سنِّت (interation) یا دماغ اور غیر محسوس خطرے میں شامل نہیں ہوتے جو اس کے ساتھ پیش آتا ہے۔';

  @override
  String get nitrousOxideReferenceDay90 =>
      'تین ماہ: دوبارہ چیک کرنے کا وقت، اگر آپ نہیں ہوتے تو\n\nماخذ: Tikaria et al. (2026), \"The Toxic Legacy of Recreational Nitrous Oxide Use,\" Cureus\n\nہم کیا جانتے ہیں — اور نہ کریں\nیہ تحقیقی بنیاد کیس رپورٹوں اور کیس سیریز سے بنا ہے، بحالی کے مطالعوں کو کنٹرول نہیں کیا جاتا، لہذا اس میں کوئی قابل اعتماد وقت نہیں شائع کیا گیا ہے کہ تین ماہ کے دوران علامات کو کس طرح حل کرتی ہیں۔ ثبوت سے پتہ چلتا ہے کہ مختلف نتائج مختلف ہوتے ہیں — بعض مریض جن کے اندر نرمی پیدا ہو جاتی ہے ، ابتدائی کمی کی وجہ سے مکمل طور پر بحال ہو جاتے ہیں جبکہ تاخیر سے تشخیص کرنے والے یا اس سے زیادہ سنگین نقصان کے باعث مستقل کمی واقع ہو سکتی ہے ۔\n\nایک مؤثر حصہ\nاگر آپ کے پاس کوئی دماغ اور غیر محسوس علامات ہوتی ہیں اور نہ ہی خون کے کام یا ماہرانہ تجزیے کی پیروی کی جاتی ہے تو تین ماہ کے بعد یہ ایک ذہین نقطہ ہے۔ اگر آپ کا علاج کِیا جاتا ہے اور اِس میں بہتری لائی جاتی ہے تو یہ آپ کے ڈاکٹر کے ساتھ اِس بات کی تصدیق کرنے کا مناسب وقت ہوتا ہے ۔\n\nزیادہ‌تر معاملات پر توجہ دینا\nتجزیہ ایک چیز کے بارے میں مطابقت رکھتا ہے: جاری رہنے والی شعاعیں B12 کو برقرار رکھتی ہیں اور خطرے میں اضافہ کرتی ہیں۔ آپ کی مقبولیت میں سب سے بڑا عنصر استعمال نہیں ہوتا ۔';

  @override
  String get nitrousOxideReferenceDay365 =>
      'ایک سال: بہترین حفاظتی ادارہ جاری ہے۔\n\nماخذ: Knuf & Maani, StatPearls; Tikaria et al. (2026), Cureus\n\nجہاں حقیقت میں ثبوت\nکوئی بھی ماخذ کسی مخصوص بحالی ٹائم لائن کا وعدہ نہیں کرتا اور یہ دیانتدار ہونے کی بات ہے — نیوٹریس آکسائیڈ پر لٹریچر اور بی12 کمیت کو انفرادی کیس رپورٹوں سے مکمل طور پر تعمیر کیا گیا ہے نہ کہ طویل عرصے کے بعد مطالعہ کیا جاتا ہے۔ جو اچھی طرح قائم کیا گیا ہے وہ ہے : نائٹرکس آکسائیڈ میں وٹامن بی12 جب بھی استعمال ہوتا ہے، اور اسے ختم کر دیتا ہے کہ مسلسل نقصان جاری رہتا ہے۔\n\nاگر آپ دفاع سے وابستہ ہیں تو\nکیس بیان کرتا ہے کہ مختلف نتائج کی بابت بیان کرتا ہے ، مکمل بحالی سے انکار کی علامات مسلسل ختم ہو جاتی ہیں ، بڑی حد تک اس بات سے وابستہ ہے کہ یہ کتنا نقصان ہوا اور اسکے فوری علاج کا کیا نتیجہ نکلا ۔ اگر آپ ابھی بھی سال میں علامات کا تجربہ کر رہے ہیں تو اس کی ایک وجہ یہ ہے کہ اس کی وجہ یہ ہے کہ سائنسدانوں کے ساتھ کام جاری رکھنا ہے، کوئی نشان نہیں کیا جا سکتا — ریڑھ کی ہڈی کی بحالی ایک طویل مدت پر جاری رہ سکتی ہے۔\n\nیقینی کیا ہے؟\nایک سال بغیر نیوٹرینو آکسائیڈ (انگریزی: Nitrous oxide) ایک سال کا ہوتا ہے جس میں مزید methioine Sentense inactiviation (activiation) کے بغیر سال کا ہوتا ہے۔ یہ دونوں ماخذوں کی حمایت کی ضمانت ہے.';

  @override
  String get opioidReferenceDay1 =>
      'اُصول : ایک دن\n\nماخذ: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings,\" World Health Organization (2009), on the NCBI Bookshelf\n\nاحبار کی کتاب\nلیکن یہ شدید جسمانی تکلیف کا باعث بنتا ہے اور دوبارہ پیدا ہونے کے خطرے میں پڑ جاتا ہے ۔ اِس کی وجہ یہ ہے کہ اِس بیماری میں مبتلا ہونے کی وجہ سے اُن کے ساتھ صبر سے پیش آتا ہے اور اُن کی جان خطرے میں پڑ جاتی ہے ۔ طبّی نگرانی اور اپائزڈ علاج کی شدید سفارش کی جاتی ہے۔\n\nجب کوئی مسئلہ کھڑا ہو جاتا ہے\nموسمِ‌سرما کا آغاز اُس وقت سے ہوتا ہے جب اُس کا زمانہ اُس کی قسم کے ذریعے ہوتا ہے :\n• مختصر سا عملہ اوپیائڈس (انگریزی: Heroin, oxicododones): onset 8–24 گھنٹے بعد آخری استعمال ہوتا ہے، 4–10 دن کی مدت کرتا ہے۔\n• طول البلد (access-date=, date=, date=, archive-date= (معاونت) Opioids (methadeone): onset 12–48 گھنٹے، مدت 10–20 دن ہے۔\n\nجس دن زمین کو جھٹکا دیا جائے گا\nاُصولوں کی فہرست اُپوئیڈ ردِعمل کی ابتدائی خصوصیات :\n• پریشانی اور پریشانی\n• مسکل کرومپس اور اکیس\n• آنکھوں اور ناک سے پانی خارج ہوتا ہے۔\n• یئونگ اور کُل‌وقتی\n• گرمیوں اور سردیوں کے ساتھ انسومنیا\n• ابتدائی مایوسی\n\nیہ اتنا بُرا کیوں محسوس کرتا ہے\nاِس نظام میں درد ، دباؤ ، جذباتی صحت اور بنیادی تسلی کا بندوبست کِیا جاتا ہے ۔ لمبے عرصے کے اپئیئیڈ استعمال جسم کی خود مختار پیداوار (endorphins) کو خارج کرتا ہے۔ جب اُن کا جسم ختم کر دیا جاتا ہے تو اُن کے جسم کو درد ، پریشانی اور پریشانی کا تجربہ ہوتا ہے جو اُس کی گہرائی کی عکاسی کرتے ہیں ۔ اُصولوں میں روزانہ ۲– ۳ لیٹر پانی پینے اور ۳– ۴ مرتبہ نگرانی کرنے کا مشورہ دیا جاتا ہے ۔';

  @override
  String get opioidReferenceDay7 =>
      'ایک ہفتہ‌وار اُوپریائیڈز : Peak Thows Drates\n\nماخذ: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings,\" World Health Organization (2009), on the NCBI Bookshelf\n\nکیا یہ خالق کی کاریگری ہے ؟\nڈبلیوایچ‌او نے 4–10 دنوں میں فوری کارروائی کی جس میں علامات کی تعمیر شروع ہو گئی اور پھر اس کھڑکی میں گھس گئی ۔ پہلے ہفتے کے آخر تک:\n• بڑی حد تک وومنگ اور ڈائری وغیرہ کو حل کیا جاتا ہے۔\n• مسکل کرومپس کم سخت ہوتے ہیں۔\n• جسمانی تکلیف بامقصد طور پر کم ہوتی ہے۔\n\n۷ دن میں کیا کچھ باقی رہا ہے ؟\nاگرچہ جسمانی علامات میں بہتری آ رہی ہے توبھی اہم چیلنج جاری رہتے ہیں :\n• insomnia — نیند میں کمی کی علامات میں سے ایک ہے۔\n• جذباتی اور جذباتی پلاٹ\n• کمزوری اور کمزوری\n• کرس‌ٹینا\n• پریشانی\n\nاس کے بعد-اکونسل -\nپہلی تاخیر کے بعد ، نیند کے مسائل ، مزاج میں تبدیلی اور خواہشات کی لہریں ہفتوں یا مہینوں تک جاری رہ سکتی ہیں ۔ اس طویل بحالی کے مرحلے میں زیادہ تر معاملات کی حمایت کرتے رہے۔\n\nعلاج شروع کرنے کا اچھا طریقہ\nاِس کے علاوہ اُنہوں نے کہا : ” مَیں اِس بیماری میں مبتلا لوگوں کی مدد کرنے کی پوری کوشش کرتا ہوں ۔ “ یہ دوائیں اوپیکئیڈ استعمال کرنے والی بیماریوں سے بھی اموات کو کم کرتی ہیں اور بہت سے لوگ جو کامیاب طویل عرصے تک بحالی کے مرحلے میں استعمال کرتے ہیں۔';

  @override
  String get opioidReferenceDay14 =>
      'دو ہفتوں کی علامات : نیند پوری کرنا شروع ہو جاتی ہے\n\nماخذ: Peer-reviewed pharmacology research on opioids and sleep\n\nOpioid-Selep اتصال\nاِس تحقیق سے پتہ چلتا ہے کہ اِن میں سے ایک کا تعلق اُن لوگوں سے ہے جو نیند سو رہے ہیں ۔ ان دریافتوں کی دستاویز جس نے کئی لوگوں کے ذریعے عام نیند کے آرکیٹیکچر کو شدید نقصان پہنچایا:\n• دھیمی آواز (redious) نیند کی کمی ہے۔\n• نیند کی کمی\n• نیند کی حد تک مناسب سانس (central سوتے ہوئے apnea)۔\n• سرِورق کی تصویر :\n\nایک خطرناک کمزوری\nاِس سلسلے میں ایک تحقیق سے پتہ چلتا ہے کہ اِس مسئلے کے بارے میں کیا کہا جا سکتا ہے ۔ توڑنے کا مطلب یہ بھی ہے کہ اس نیند کو توڑنے والے چکر کو توڑ دے۔\n\nدو موسموں میں نیند\n14 دنوں تک اوپیئیڈ ریبیز کی نیند معمول سے شروع ہوتی ہے:\n• مرکزی نیند Apnea (اگر موجود ہو) دن کے اندر حل کرتی ہے۔\n• گہری رفتار سے سونا شروع ہو جاتا ہے۔\n• نیند معمول کے مطابق واپس آ رہی ہے\n• نیند پر بھروسا کرنا زیادہ قابلِ‌اعتماد ہو رہا ہے\n\nنیند دو ہفتوں میں بہت سے لوگوں کے لئے ایک اہم چیلنج ہے لیکن اِس میں بہت زیادہ بہتری آ رہی ہے ۔ نیند کو براہِ‌راست بہتر بنانے ، مایوسی کو کم کرنے اور بحالی کے لئے درکار واضح سوچ کی حمایت کرنے کی کوشش کریں ۔';

  @override
  String get opioidReferenceDay30 =>
      'ایک مہینے کے بعد اُس نے کہا : سوچ‌بچار کریں اور یاد رکھیں کہ اُس کی یاد تازہ ہو جائے گی ۔\n\nماخذ: Mayo Clinic\n\nسمجھ‌داری سے کام لیں\nمے کلینک بیان کرتا ہے کہ تمام دماغ اور جسم کے اندر اُگنے والی بیماریوں میں مبتلا ہو جاتے ہیں جس سے درد ، درد اور نیند کم ہو جاتی ہے ۔ بار بار استعمال ہونے کے ساتھ دماغ کم زوری جواب دیتا ہے اور اپنے اپنے اوپیکئیڈ جیسی کیمیاوی کیمیاوی کیمیائوں کو کم بناتا ہے۔ جس سے جسمانی انحصار پیدا ہوتا ہے۔\n\nایک مہینے میں سوچ‌بچار کرنا اور یاد رکھنا\n30 دن میں سوچ بچار اور یادو میں بامعنی بحالی واقع ہوئی ہے۔ بد ترین دماغ فوگ نے صاف کیا ہے اور دماغ کا سامنے — جو منصوبہ بندی اور خود قابو میں رکھتا ہے —\n• فیصلہ سازی بہتر رہی ہے۔\n• کام کی یاد تازہ ہے\n• رفتار کو تیز کرنا\n• زیادہ قابلِ‌اعتماد\n\nاِس دُنیا کا نظام\nایک ماہ میں دماغ کا قدرتی اوورفین نظام فعال طور پر استعمال ہوتا ہے : یہ اپنے اپنے آپ سے زیادہ سے زیادہ خودبخود پیدا کر رہا ہے اور دوبارہ عام طور پر جواب دے رہا ہے۔ جب اُس کی بحالی جاری رہتی ہے تو جذباتی تناؤ اور کم تکلیف برداشت کرنا جاری رہتا ہے ۔\n\nدوبارہ کوشش کریں\nمے کلینک نے اس بات پر زور دیا ہے کہ ایک مہینے میں سوبریٹ دوبارہ سے گزرنے کے خطرے کا مطلب یہ نہیں ہے کہ یہ ابھی تک بلند ہے ۔ اِس سے ظاہر ہوتا ہے کہ اِس کا مطلب یہ ہے کہ سابقہ دواوں کو بار بار استعمال کرنے سے بہت زیادہ نقصان ہوتا ہے ۔';

  @override
  String get opioidReferenceDay60 =>
      'دو ماہ کی تاخیر: دماغ کے دباؤ کی وجہ سے پیدا ہونے والے سرکٹ بیٹین کو سٹیج بنانے کے لیے\n\nماخذ: \"Neuroplasticity of the extended amygdala in opioid withdrawal and prolonged opioid abstinence,\" Frontiers in Pharmacology (2023)\n\nجہاں منفی احساسات پیدا ہوتے ہیں\nاس تجزیے کے نقشے کس طرح لمبے عرصے کے اپوئیڈ دماغ کے دباؤ اور ڈرون سرکٹ تبدیل کرتے ہیں۔ اِس دوران یہ سرکٹ اِس حد تک جذب ہو جاتے ہیں کہ اِس کے نتیجے میں اُنہیں اَور بھی بہت سی مشکلات کا سامنا کرنا پڑتا ہے ۔ اِس ملاپ سے پریشانی ، افسردگی اور مایوسی کو کم کرنے میں مدد ملتی ہے ۔\n\nدو مہینے نجات کیوں دیتے ہیں\nکرنسی، تجزیاتی دستاویز کہ ان میں سے کچھ تبدیلیوں کو دوبارہ حل کیا جاتا ہے۔ جانوروں میں ریڑھ کی ہڈی کی کمی کے نقصان کو بیان کیا گیا ہے جو کہ ایکڑ سے زائد ہفتوں پر پہلے کی قدروں کی طرف رجوع کرتے ہیں۔ جب یہ دباؤ اور انعامی سرکٹز نے دوبارہ شروع کِیا تو ابتدائی جذباتی مشکلات کی بنیادی بنیاد — دو ماہ کے اندر اندراندر کم‌ازکم ایکشن اور متبادل رُجحان رکھنے والے بہتیرے لوگوں کی رپورٹ پیش کرتی ہے ۔\n\nدوبارہ سے نشانات کو صاف کریں\nاس لٹریچر میں ریختہ ریڑھ کی ہڈی کی ہڈی اور دباؤ کی تبدیلی ایک حقیقی حیاتیاتی بحالی عمل کو ظاہر کرتی ہے: گردے منفی جذباتی حالت پر انحصار کے دوران اپنی قبل از وقت کی حالت کی طرف پھر سے منتقل ہو جاتا ہے۔';

  @override
  String get opioidReferenceDay90 =>
      'تین ماہ کے اختتام پر اُمیدی علامات : اَجر پانے کا آغاز کرنا\n\nماخذ: \"Structural and Functional Brain Recovery in Individuals with Substance Use Disorders During Abstinence: A Review of Longitudinal Neuroimaging Studies,\" Drug and Alcohol Dependence (2022), on PubMed Central\n\nدوامین اور اُوپریائیڈز\nدماغ کے اجرا کے نظام میں Opioids dopine خارج کرتا ہے۔ لمبے عرصے میں استعمال ہونے والے پتے جو نظامِ شمسی کی کمیت کرتے ہیں: ایک دماغ کے مطالعے میں ایسے پروٹین جن کے پروٹین کو شروع میں صحت مند سطح کے قریب 30% تھے۔ اِس سے ظاہر ہوتا ہے کہ اُن کی خوشی ختم ہو گئی ہے اور اُن کی صحت خراب ہو گئی ہے ۔\n\nدوبارہ سے کام کرنے کی اہمیت\nاس جائزے نے ان طویل تحقیقی مطالعات کو جمع کیا جو آذربائیجان کے اوپر انہی لوگوں کو دوبارہ منظم کرتے ہیں۔ دوپمین-ترونسپورٹر کی کمیت کے مطابق 20% سے بڑھ کر 6–12 ماہ تک دوبارہ بحال ہو گئی، اور ابتدائی دور میں دیکھے جانے والے کچھ بالواسطہ اور سفید فاموں کو ایک ماہ کے بعد دوبارہ دریافت نہیں کیا گیا تھا۔ تین مہینوں میں آپ اس بحالی کے موڑ پر جلدی سے ہیں: انعام اور پیش کردہ نظام میقات ہیں، لیکن ختم نہیں ہوا ہے.\n\nلوگوں کا تجربہ\nجب یہ سرکٹ ٹھیک ہو جاتے ہیں تو ۹۰ دن کے آس‌پاس بہتیرے لوگ نوٹ کرتے ہیں :\n• کام ، خوراک اور تعلقات کا حقیقی فائدہ\n• ابتدائی بحالی کے مقابلے میں حوصلہ‌افزائی\n• صاف خیال اور بہتر فیصلہ سازی\n\nدوبارہ سے نشانات کو صاف کریں\nلمبے عرصے میں انسانی امیگریشن (Longitudinal) ظاہر کرتا ہے کہ Dopamine-transporter کی دستیابی 6–12 مہینوں میں بڑھتی ہے، جبکہ پیشن گوئی-اور سفید فاموں میں بہت پہلے نارمل ہونا شروع ہو جاتا ہے۔ 90 دن کے بعد پہلے سے ہی دماغ کی مرمت کی جاتی ہے۔';

  @override
  String get opioidReferenceDay180 =>
      'چھ ماہ کی تاخیر : اِمنے کے نظام میں تبدیلی لانے کا نظام\n\nماخذ: \"Effects of opioid tolerance and withdrawal on the immune system,\" Journal of Neuroimmune Pharmacology (2006), on PubMed\n\nاوپیک اور ایمونی نظام\nاس جائزے سے پتہ چلتا ہے کہ لمبے عرصے کے اُپائئیڈ کا استعمال کئی طریقوں سے مدافعتی نظام کو کمزور کرتا ہے:\n• مدافعتی خلیوں (T cells, NK cells, Macrophages) پر براہ راست Opioid عمل کرتی ہے۔\n• مدافعتی طور پر پیدا ہونے والے کیمیائی مرکبات\n• Advenution of the Construction-brain-pituituary-adrenal (HPA) Autonomy -\n• انفیکشن میں اضافہ\n\nدوبارہ سے نشانات کو صاف کریں\nلمبے عرصے کے اپئیائڈز مدافعتی نظام کے کئی حصوں کو دبا دیتے ہیں۔ چھ مہینوں تک ، یہ بیماری نصف سال سے مسلسل ختم ہو رہی ہے اور مدافعتی سرگرمیاں معمول کی طرف دوبارہ بحال ہو رہی ہیں ۔\n\nچھ ماہ کے بعد کیا واقع ہوا\nچھ ماہ تک بغیر افیون کے مدافعتی خلیوں، مدافعتی سگنلنگ اور جسم کے دباؤ کے نظام کو معمول کے مطابق ٹھیک کرنے میں وقت لگتا تھا۔\n\nابھی تک ایسا کیوں ہوتا ہے ؟\nیہ خاص طور پر ان لوگوں کیلئے ہے جنہوں نے ایچ‌آئی‌وی اور ہیپاٹائٹس سی جیسے خطرناک خطرات کا سامنا کِیا تھا ۔ اِس کے علاوہ اِس بیماری کی وجہ سے اُن کی صحت پر اچھا اثر پڑتا ہے اور اُن کی صحت خراب ہو جاتی ہے ۔';

  @override
  String get opioidReferenceDay365 =>
      'ایک سال اوپیائڈز : دماغ کی شریانوں اور کیمیاء دوبارہ پیدا ہو جاتی ہے۔\n\nماخذ: \"Structural and Functional Brain Recovery in Individuals with Substance Use Disorders During Abstinence: A Review of Longitudinal Neuroimaging Studies,\" Drug and Alcohol Dependence (2022), on PubMed Central\n\nانسانی تصورات کیا ظاہر کرتے ہیں\nاس جائزے نے ان مطالعات کو جمع کیا جو ایک ہی شخص کے ساتھ اپائیئیڈ سے متعلقہ افراد نے ایک بار سے زیادہ امراض کا استعمال کیا۔ نتائج مسلسل بحالی کی طرف بڑھتے رہتے ہیں :\n• عطارد اور حرکت کے شعبوں میں موجود پروٹین، ابتدا میں تقریباً 30% زیرِ معمول، 6–12 ماہ سے زائد اوپیکائڈز سے 20%\n• ابتدائی ردِعمل میں موجود فرنٹل کمزور ثابت‌قدمیاں اب آذربائیجان کے تقریباً ایک ماہ بعد دریافت نہیں ہوئی تھیں\n• سفید فاموں (انگریزی: White-dependent and Cingulate) اور آرام پیشہ ورانہ سرگرمیاں بھی پہلی ماہ کے اندر دوبارہ شروع ہونے لگیں۔\n\nجہاں ایک سال کی تقریبات ہوتی ہیں۔\nبارہ مہینوں تک آپ سب سے طویل کھڑکی یا ماضی میں ان مطالعوں کی پیمائش کرتے ہیں۔ دوپیمین سسٹم کو صحت یاب کرنے میں سب سے زیادہ وقت لگا ہے اور اپنے آپ کو قابو میں رکھنے اور فیصلے کی حمایت کرنے والے فرنٹل سرکٹ مہینوں سے اصلاح لیتے ہیں — ایک سال میں واضح سوچ ، کمزور اور متبادل مزاج رکھنے والے لوگوں کا حیاتیاتی تعاون\n\nدوبارہ سے نشانات کو صاف کریں\nایک سال میں انسانی امیجنگ سگنل کو شدید بحالی کا عمل قرار دیا گیا ہے: Dopamine-transporter کی دستیابی 6–12 ماہ کی کھڑکی میں بڑھ چکی ہے، جبکہ پیشن گوئی اور سرگرمیاں معمولات کے لیے بہت سے ماہ ہو چکی ہیں۔';

  @override
  String get opioidReferenceDay730 =>
      'دو سالوں میں اوکاڑہ (انگریزی: A Stable Foundation) ایک اسٹیبل فاؤنڈیشن ہے۔\n\nماخذ: \"Treatment of Opioid Use Disorder,\" Centers for Disease Control and Prevention (CDC)\n\nاِس کی ایک وجہ یہ ہے کہ اُس نے اُن سے پوچھا : ” کیا مَیں اُن کی بات مانتا ہوں ؟ “\nسی‌سی‌ڈی‌سی بیان کرتی ہے کہ ” ایک دائمی مرض جو کسی کو متاثر کر سکتا ہے “ — ’ ایک طبی کمزوری نہیں ۔\n\nسی‌سی‌سی‌سی‌ایس کیا کام کرتی ہے ؟\nسی ڈی سی کا ہدایتی مرکز علاجوں پر مشتمل ہے جو طویل عرصے میں بحالی کے لیے قائم رہتے ہیں:\n• ادویات برائے اوپیئیڈ استعمالات (انگریزی: Bumprephine, Methadone)، جسے خاص طور پر مؤثر کہا جاتا ہے۔\n• علاج‌معالجے کے سلسلے میں دوا استعمال کریں\n• وہ علاج جو مختلف عرصے تک جاری رہتا ہے ، اُس شخص کے سامنے ٹھیک ہو جاتا ہے ۔\nسی‌سی‌سی‌سی نے بیان کِیا کہ اِن ادویات میں ” دماغ کی کیمیا کو تیز کرنا “ اور اِس سے آرام پانا شامل ہے ۔\n\nمحفوظ رہنا\nسی ڈی سی میں لوگوں کو بحالی کے لیے اپنے ڈاکٹر سے درخواست کرنے کی تاکید کی گئی ہے کہ وہ دوبارہ استعمال کرنے کے خطرے سے دوچار ہو جائیں، اور ناولوں کو ہاتھ پر رکھنے کی کوشش کریں۔ یہ جان کر کہ آپ نے جو کچھ بنایا ہے اس کی حفاظت کا ایک حصہ ہے.\n\nدو سال\nسی ڈی سی واضح ہے کہ بحالی کا عمل اکثر ایک طویل مدتی عمل ہوتا ہے نہ کہ ختم ہونے والی لکیر۔ دو سال سفر کا اختتام نہیں بلکہ یہ ایک مستحکم ، صحت‌بخش بنیاد اور مضبوط ثبوت ہے کہ جس راستے سے آپ کام کر رہے ہیں اُسے استعمال کر رہے ہیں ۔';

  @override
  String get pornographyReferenceDay1 =>
      'پہلا دن : واپس پر قابو پانا\n\nماخذ: Kraus et al., Compulsive sexual behaviour disorder in the ICD-11, World Psychiatry (2018).\n\nاِس سلسلے میں ایک مثال پر غور کریں ۔ جنسی بداخلاقی کو مسلسل مشکل کے دوران بیان کِیا جاتا ہے ۔ اگر آپ فحش مواد دیکھنے کی عادت میں پڑ گئے ہیں تو آپ اِس مسئلے کو حل کرنے کے لئے کیا کر سکتے ہیں ؟\n\nاِس لئے مَیں نے اِس بات کو تسلیم نہیں کِیا کہ مَیں نے اِس بات کو تسلیم نہیں کِیا ۔ ایک پورا دن دماغ اور اعصابی نظام کو ظاہر نہیں کرتا بلکہ جب حوصلہ‌افزائی ظاہر ہوتی ہے تو یہ آپ کو پہلا حقیقی مشاہدہ فراہم کرتا ہے ، کونسی صورتحال انہیں متاثر کرتی ہے اور آپ کیا کر سکتے ہیں ۔\n\nاگر آپ کا استعمال پریشان‌کُن نہیں ہوتا ، اُسے قابو میں رکھنا مشکل ہوتا یا مشکل ہوتا تو آپ کو بھی ایسا کرنا چاہئے ۔ یہ میل‌جول ایسے لوگوں کی طرف اشارہ کرتے ہیں جو جان‌بوجھ کر مسئلے کو بدل رہے ہیں یا پھر اِن کے استعمال میں آ رہے ہیں ۔';

  @override
  String get pornographyReferenceDay3 =>
      'تیسرے دن : یہ جان لینا کہ کس چیز کی شناخت کی جا سکتی ہے\n\nماخذ: Lewczuk et al., Withdrawal and tolerance as related to compulsive sexual behavior disorder and problematic pornography use, Journal of Behavioral Addictions (2022).\n\n1،541 بالغوں کے ایک پریفیکچر میں، زیادہ سے زیادہ CSBD اور Beratic-pornography-suse settlement-settlement کے ساتھ مضبوط خود کشی کے تجربات سے منسلک تھے۔ مسئلے کی فحش نگاری کے استعمال کے ساتھ شریک ہونے والوں میں عام طور سے تجربات میں مشکل جنسی خیالات، مشکل سے نمٹنے کی خواہش، عروج میں اضافے، ذہنی تبدیلی اور نیند کے مسائل شامل تھے۔\n\nبےچینی ، جنسی سوچ ، شدید حوصلہ‌افزائی اور نقل‌مکانی کرنے والے لوگوں میں زیادہ سنگین مسائل پیدا ہو جاتے ہیں ۔ اگر وہ تین دن کے ارد گرد دکھائی دیں تو ان کے ساتھ ایک حقیقی رد عمل کے طور پر برتاؤ کریں اور ان کا انتظام کریں۔\n\nاُس نے لکھا : ” اَے [ یہوواہ ] ! لیکن جب اِس کا نام دماغ کے ایک حادثے کے طور پر رکھا جاتا ہے تو اُس کا علاج کرنا آسان ہو جاتا ہے ۔';

  @override
  String get pornographyReferenceDay7 =>
      'یکم ہفتم: ایک randomid Abstinence مطالعے کی بنیاد کیا ہے۔\n\nماخذ: Effects of a 7-Day Pornography Abstinence Period on Withdrawal-Related Symptoms in Regular Pornography Users, Archives of Sexual Behavior (2023).\n\nتحقیق‌دانوں نے 176 فحش‌نگاری کرنے والے لوگوں کو یہ سوچنے پر مجبور کِیا کہ وہ سات دن تک فحش مواد استعمال کریں گے یا پھر عام طور پر جاری رہیں گے ۔ اُنہوں نے کہا : ” اَے [ یہوواہ ] !\n\nتحقیق سے پتہ چلا ہے کہ ایسے لوگوں میں زیادہ دلچسپی بڑھ گئی تھی جو اعلیٰ مسائل کے استعمال سے پہلے روزانہ فحش مواد استعمال کرتے تھے۔ اس کا نتیجہ یہ ہوتا ہے کہ اس کے لیے غیر ضروری ہے، لیکن یہ مفید ہے: سب سے پہلے ہفتے میں بھاری مسئلے والے صارفین کے لیے حقیقی ہو سکتا ہے، جب کہ ایک عالمی فحش‌نگاری کو رد کرنے والا مریض اس آزمائش کی حمایت نہیں کرتا ۔\n\nاگر آپ اسے ایک ہفتے کے ذریعے بنا چکے ہیں، تو اب آپ کے پاس اپنے انداز کے بارے میں بہتر ثبوت موجود ہے ہر جینریکل انٹرنیٹ ٹائم لائن فراہم کر سکتا ہے۔';

  @override
  String get pornographyReferenceDay14 =>
      'دو ہفتوں کا نقشہ : حقیقت‌پسندانہ بات‌چیت کرنے والے ٹریگرس کو نقشہ\n\nماخذ: Biopsychosocial Determinants of Problematic Pornography Use: A Systematic Review (2023).\n\nاس جائزے نے 66 مطالعے کئے اور یہ دریافت کِیا کہ فحش‌نگاری ایک سادہ دوا‌مین ایم‌این‌اے کی بجائے عناصر کے ملاپ سے تعلق رکھتی ہے ۔ جذباتی طور پر شناختی اور سماجی عناصر میں شوق، دباؤ، تنہائی، تنہائی، منفی عقائد اور اسٹائل کا مقابلہ کرنا شامل تھا۔\n\nدو ہفتوں کے دوران آپ کو ہفتے کے دن ، دن‌بھر کے لئے باربار ورزش کرنی پڑتی ہے ، دباؤ ، تنہائی ، اوزاروں اور دیگر پہلوؤں سے گزرنا پڑتا ہے ۔ کہ اعداد استعمال کریں. اگر دباؤ کی وجہ سے دباؤ کا شکار ہو جاتا ہے تو دباؤ کا حل تلاش کریں ۔ اگر تنہائی کا شکار ہو تو رابطے میں اضافہ کریں ۔ اگر آسان رسائی دائرہ ہو تو ماحول کو تبدیل کر دے۔\n\nاِس سلسلے میں ایک مثال پر غور کریں ۔';

  @override
  String get pornographyReferenceDay30 =>
      'ایک ماہ : معاملات پر قابو رکھنا زیادہ آسان حد تک خطرناک ہوتا ہے\n\nماخذ: Bőthe et al., Are sexual functioning problems associated with frequent pornography use and/or problematic pornography use?, Addictive Behaviors (2021).\n\n14،581 بالغوں کی ایک کمیونٹی ماڈل میں، مسئلہ خیز فحش نگاری کے استعمال میں مرد اور خواتین دونوں میں جنسی عدم توازن پیدا کرنے والے مسائل کے ساتھ اعتدال پسند شراکت تھی۔ فحش نگاری کے استعمال نے خود ان مسائل کے ساتھ ایک کمزور منفی شراکت کا مظاہرہ کیا۔\n\nیہ باتیں فرق‌فرق ہیں ۔ اِس بات کا ثبوت یہ نہیں کہ فحش‌نگاری دیکھنے والا شخص صرف جنسی طور پر نقصان اُٹھاتا ہے ۔ زیادہ سے زیادہ متعلقہ ہدف کنٹرول کھو جاتا ہے اور اس نمونے کے ارد گرد موجود مسائل.\n\nایک مہینے بعد ، زندگی کا موازنہ اُس وقت کریں جب آپ نے شروع کِیا : وقت ضائع ہو گیا ہے ، وقت ضائع ہو گیا ہے ، اِسے روکنے کی صلاحیت ، جنسی کام کرنے ، رشتہ‌داری اور پریشانی کا سامنا کرنا پڑتا ہے ۔ یہ تبدیلیاں ایک شمسی دن-30 دماغ کی گردش کا انتظار کرنے سے زیادہ اہم ہیں.';

  @override
  String get pornographyReferenceDay90 =>
      'تین مہینے : تکلیف‌دہ تبدیلی ممکن ہے\n\nماخذ: Crosby & Twohig, Acceptance and Commitment Therapy for Problematic Internet Pornography Use: A Randomized Trial, Behavior Therapy (2016).\n\nاس چھوٹی سی غیر متوقع مقدمے نے 28 بالغ مردوں میں ایک انتظار کنندہ کے ساتھ ایک 12 سی ٹی پروگرام کا موازنہ کیا۔ علاج کے اختتام پر اے سی ٹی گروپ میں فحش دیکھنے میں بہت زیادہ کمی واقع ہوئی اور تین ماہ کے بعد اس میں کمی واقع ہوئی۔\n\nمطالعے سے یہ ثابت نہیں ہوتا کہ صرف 90 دنوں تک اِسی نتیجے پر پہنچا ہے اور اِس کا نمونہ چھوٹا اور جمہوری انداز میں تنگ تھا۔ اِس سے ظاہر ہوتا ہے کہ فحش‌نگاری بہت اہم ہے ۔\n\nاگر آپ کی ترقی کا انحصار ابھی تک زیادہ تر سفید-کنلنگ پر ہے، تو تین ماہ اس کے گرد نظام کو مضبوط کرنے کے لیے اچھا نقطہ ہے: حرکت کے منصوبوں، تاکیدی منصوبوں کو عمل کے بغیر، ماحولیاتی عدم استحکام، عدم توازن اور علاج کی ضرورت کے وقت قبول کرنا ہے۔';

  @override
  String get pornographyReferenceDay180 =>
      'چھ ماہ: لمبے-Term Symptom کنٹرول ہولڈ ہو سکتا ہے۔\n\nماخذ: Hallberg et al., A Randomized Controlled Study of Group-Administered Cognitive Behavioral Therapy for Hypersexual Disorder in Men, Journal of Sexual Medicine (2019).\n\n137 مردوں میں بیرونی جنسی سلوک کے ساتھ گروپ سی بی ٹی کے سات ہفتوں میں زیادہ کمی پیدا ہوئی جس کے ساتھ ساتھ ساتھ ایک انتظار میں بہتری لائی گئی۔ علاج کے نتیجے میں تین اور چھ ماہ بعد مستقل طور پر مستحکم رہا۔\n\nاس مطالعے نے صرف فحش‌نگاری کو نظرانداز کرنے کی بجائے جنسی بداخلاقی کو زیادہ متاثر کِیا ، لہٰذا یہ دعویٰ نہیں کِیا جانا چاہئے کہ ہر شخص چھ ماہ بعد جسمانی طور پر ٹھیک ہو جاتا ہے ۔ یہ ایک مضبوط اور مفید بیان کی حمایت کرتا ہے : جنسی تعلقات میں بہتری پیدا کرنا اس طویل عرصے تک قائم رہ سکتا ہے ۔\n\nلہٰذا ، چھ ماہ تک ایک مُہلک جُز ہے ۔ اُن معمولوں کو برقرار رکھیں جن کی وجہ سے تاریخ کو اِس بات کی اجازت نہیں تھی کہ وہ اُن کی غلطیوں کو نظرانداز کر دیں ۔';

  @override
  String get pornographyReferenceDay365 =>
      'ایک سال : دُوردراز علاقوں میں ہونے والی تبدیلی کے ثبوت\n\nماخذ: One-year follow-up effects of an acceptance-based treatment for hypersexuality (2026).\n\nایک سال بعد اس مقبول علاج پر مبنی مطالعے میں حصہ لینے والوں نے ہائیر جنسیت کی جانب سے ان کی قبل از وقتی سطح کی طرف رجوع نہیں کیا تھا۔ مصنفوں نے اعدادوشمار کا حوالہ دیتے ہوئے بیان کِیا کہ یہ قابلِ‌قبول اور بامقصد فوائد ہیں جسکی وجہ سے وقت گزرنے کے ساتھ ساتھ عمل میں آنے والی خواہش پر قابو پایا جاتا ہے ۔\n\nیہ علاج ثبوت کے ماتحت ہے، ایک سالہ دماغ کی گردش کا ثبوت نہیں ہے. بامقصد دعوٰی بہتر ہے : ابتدائی مداخلت کے فوراً بعد ختم ہونے کی بجائے ایک سال تک ماحولیاتی کنٹرول برقرار رہ سکتا ہے۔\n\nخود آپ کی قائم کردہ تبدیلی کا ایک سال بھی بڑا ذاتی اعداد و شمار ہوتا ہے۔ حالیہ کنٹرول ، پریشانی ، محنت ، رشتوں اور وقت کے استعمال پر غور کریں ۔';

  @override
  String get pornographyReferenceDay1825 =>
      'پانچ سال: لمبے عرصے تک کنٹرول آؤٹ ہو جاتا ہے۔\n\nماخذ: Compulsive sexual behavior disorder and problematic pornography use: a comprehensive interdisciplinary expert-informed review (2026).\n\nجدید تجزیوں میں سی‌سی‌بی‌بی‌ڈی اور مسئلہ‌خیز فحش‌نگاری کو قابو میں رکھنے ، مشکلات ، کام‌کاج ، سیاق‌وسباق اور انفرادی اختلافات پر مشتمل پیچیدہ مسائل کے طور پر استعمال کِیا جاتا ہے ۔ پانچ سالہ دماغ اور ریڑھ کی ہڈی میں کوئی رکاوٹ نہیں رہتی۔\n\nلیکن پانچ سال خالی میل نہیں ہے ۔ آپ نے جس چال‌چلن کا انتخاب کِیا ، اُسے برقرار رکھنے کا یہ دن 1.825 دن ہے ۔ اِس کی وجہ یہ ہے کہ اِس مسئلے کے نتیجے میں اِس مسئلے کو حل کرنا مشکل ہو جاتا ہے ۔\n\nاس مرحلے پر مفید سوال یہ نہیں کہ آیا آپ کا دماغ ایک فنکارانہ فیصد ریویرنگ تک پہنچ چکا ہے۔ یہ اب بھی آپ کے انتخاب پر قابو رکھتا ہے یا آپ کی مرضی کے مطابق زندگی کو خراب کر دیتا ہے. اگر ایسا نہ ہو تو یہ ایک زیرک طویل مدتی کامیابی ہے۔';

  @override
  String get smokingReferenceDay1 =>
      'پہلا دن : اب فائدہ‌مند\n\nماخذ: NHS Better Health\n\nچند منٹ کے اندر ہی فوائد شروع ہو جاتے ہیں — دن نہیں ۔ سانس لینے کے فوراً بعد جسم معمول سے شروع ہو جاتا ہے۔\n\nآجکل کیا واقع ہوتا ہے\n• 20 منٹ: معمول پر واپس آنا شروع ہو جاتا ہے۔\n• 8 گھنٹے: خون میں کاربن مونو آکسائیڈ نصف النہار سے گرتا ہے؛ آکسیجن کی مقداروں میں کمی واقع ہوتی ہے۔\n• 48 گھنٹے: کاربن مونو آکسائیڈ ایک غیر تابکاری کی سطح تک گر چکا ہے۔\n\nکاربن مونو آکسائیڈ کو آکسیجن کی نسبت زیادہ مضبوط اور خون کے سُرخ خلیوں میں تقسیم کرتا ہے ۔ ہر عضو اس سے کم آکسیجن حاصل کر رہا تھا۔ یہ دو دن کے اندر ختم ہو جاتا ہے.\n\nایک دن کا آغاز ہوتا ہے\n• ہر ایک مستقل 3–5 منٹ —\n• مایوسی اور مشکل کا سامنا\n• بڑھتی ہوئی بھوک\n\nیہ عارضی اور عارضی ہیں ۔ این ایچ ایس بہتر صحت کے پروگرام میں ایم ایس اور فقہی مشورے سمیت آزادانہ تعاون پیش کیا جاتا ہے۔';

  @override
  String get smokingReferenceDay3 =>
      'تیسرا دن : پیک‌کُل\n\nماخذ: McLaughlin, Dani & De Biasi\n\n72 گھنٹے تک نکوٹین آپ کے جسم سے غائب ہو جاتی ہے۔ دماغ نے سگریٹ نوشی کے سالوں کے دوران اضافی ذیابیطس پیدا کی، اب وہ زیرِ استعمال ہیں جس کی وجہ سے انتقالِ‌خون کا باعث بنتا ہے-\n\nپائیک علامات\n• صلیب — اس وقت زیادہ‌تر شدت سے\n• مایوسی ، مایوسی ، بے چینی\n• مایوسی\n• پریشانی\n• سر کو کچلنا\n• بڑھتی ہوئی بھوک\n• کُوُوُگ ( ہوا کے راستے صاف ہو رہے ہیں — ایک اچھا نشان )\n\nوہ دن بڑا ہی سخت دن ہوگا یہ اس سے بھی بدتر نہیں ہوتا — یہاں سے آپ کے دماغ میں مستقل آسانی پیدا ہو جاتی ہے.\n\nاس مرحلے پر این آر ٹی ، وارانسی لائن اور بھوجپوری سب کچھ تیزی سے کم ہو جاتا ہے ۔';

  @override
  String get smokingReferenceDay7 =>
      'ایک ہفتہ : چکھنے کا مزہ اور اسکی واپسی\n\nماخذ: NHS Better Health\n\nایک ہفتے میں دھوئیں سے آزاد ہونا ایک طویل مدتی کامیابی کی مضبوط پیش گوئی ہے — پہلے ہفتے سے گزرنے والے لوگ خیر کے لیے چھوڑنے کا امکان بہت زیادہ ہے۔\n\nکیا ٹھیک ہے؟\n• خوراک میں تبدیلی کا مزہ زیادہ ہوتا ہے\n• سیم زیادہ واضح ہوتے ہیں۔\n• بریونگ آسان ہے — ہوا کے راستے صاف کر رہے ہیں۔\n• سگریٹ‌نوشی بہتر ہو رہی ہے\n• اسکینیا بہترین ہائیڈیز ہے\n\nاِس کی وجہ یہ ہے کہ اُن کی صحت خراب ہو جاتی ہے اور اُن کی صحت خراب ہو جاتی ہے ۔\n\nاِس کی کیا وجہ ہے ؟ اِس لئے اُس کی صحت بہت کم ہوتی ہے ۔ ( ۱ - پطرس ۵ : ۸ ) اس سے ظاہر ہوتا ہے کہ ہمیں ہر قسم کی مشکلات کا سامنا کرنا پڑتا ہے ۔';

  @override
  String get smokingReferenceDay14 =>
      'دو ہفتوں کا فرق : اِس کا مطلب ہے کہ اِس کا مطلب ہے کہ اِس میں کوئی تبدیلی نہیں آئے گی ۔\n\nماخذ: NHS Better Health\n\n2–12 ہفتوں کے اندر خون کی گردش بہتر ہو جاتی ہے۔ نکوٹین ہر سگریٹ کے ساتھ خون کی نالیوں کو تنگ کرتا ہے ؛ اس کے بغیر یہ نالییں آرام کرتی ہیں اور خون زیادہ آزادانہ طور پر بہہ جاتی ہیں ۔\n\nاس کا کیا مطلب ہے؟\n• خون ہاتھ ، پاؤں اور پاؤں تک پہنچتا ہے ۔\n• بہت سے لوگ گرم ہاتھوں اور پاؤں کو دیکھتے ہیں۔\n• سیڑھیوں پر چلنا اور چڑھائی کرنا آسان ہونے لگتا ہے۔\n\nکاربن مونو آکسائیڈ کے ساتھ پہلے ہی دن میں خون سے صاف ہو کر اس میں بہتری آتی ہے اور اس وقت آکسیجن زیادہ مؤثر طریقے سے سانس لیتی ہے ۔\n\nہوائی جہازوں کی سطح پر تعمیر شدہ امؤس کو ہٹانے اور زور دینے کی کوشش کرتے ہیں۔ اگر آپ عام طور پر زیادہ سے زیادہ بلے بازی کر رہے ہیں، تو یہ بحالی کی علامت ہے، نہ کہ کوئی رکاوٹ۔';

  @override
  String get smokingReferenceDay30 =>
      'ایک ماہ : لُوٹ‌بُک کی تقسیم\n\nماخذ: NHS Better Health\n\nپھیپھڑوں کی کارکردگی آسان ہو جاتی ہے اور پھیپھڑوں کی کارکردگی بہتر ہو جاتی ہے — 3-9- مہینے کی کھڑکی سے 10% تک بڑھ جاتی ہے۔ ایک ماہ میں، آپ کو اس بحالی کی موڑ میں اچھی طرح ہیں.\n\nپھیپھڑوں میں کیا ہو رہا ہے۔\n• سیلیا نے دوبارہ دریافت کیا ہے اور مؤثر طریقے سے اسے صاف کر رہا ہے۔\n• ائیرپورٹس ڈیٹا بیس پر واقع ہے۔\n• مستقل تمباکو نوشی کرنے والے کی غداری کی جاتی ہے۔\n• تحمل بہتر ہو رہا ہے\n\nجب پھیپھڑوں کے کام میں اضافہ ہوتا ہے تو سانس لینے اور سانس لینے کے مسائل بہتر ہو جاتے ہیں ۔ ایک ماہ میں اس بحالی کے موڑ پر ایک بامقصد نقطہ ہے.';

  @override
  String get smokingReferenceDay90 =>
      'تین ماہ: دل کا دورہ پڑنے سے دل کا دورہ پڑ جاتا ہے۔\n\nماخذ: PMC — Cardiovascular Effects of Smoking and Cessation (2024)\n\nاِس سے دل کو نقصان پہنچ سکتا ہے اور اِس کی وجہ یہ ہے کہ اِس کی وجہ سے اِس بیماری کی وجہ سے اِس بیماری کا شکار ہو جاتے ہیں ۔ کوکواگولنٹ، خون خراب ہونے والے اثرات کو روکنے کے ایام کے اندر تبدیل کر دیتا ہے، اور اس جائزے میں دل کے دورے اور زچگی کے پہلے سال کے اندر ایک غیر معمولی کمی کی اطلاع دی گئی ہے۔\n\nجو اب تک بہتر ہے۔\n• خون کو خون دینے کے عناصر نارمل ہوتے ہیں۔\n• بلڈ پریشر اور دل کا دورہ پڑ رہا ہے۔\n• آتش‌فشاں پہاڑ کے پھٹنے کے خطرے میں سب سے تیز رفتار کمی اچھی طرح سے کم ہو جاتی ہے\n\nاِس سے فائدہ حاصل ہوتا ہے کیونکہ وقت گزرنے کے ساتھ‌ساتھ اِس میں بہت زیادہ وقت لگتا ہے اور اِسے بعد کے میلوں میں ڈھالا جاتا ہے ۔ ہر دھول ماہ کی بحالی میں اضافہ ہوتا ہے۔';

  @override
  String get smokingReferenceDay180 =>
      'چھ ماہ: پھیپھڑوں کے مدافعتی خلیے دوبارہ طاقت پکڑتے ہیں\n\nماخذ: Smoke-free period and recovery of alveolar immune-cell function (PubMed)\n\nتمباکو نوشی الویولر میکروفیجز کو دبا سکتی ہے — یہ پھیپھڑوں کی گہرائی میں موجود مدافعتی خلیے ہیں جو بیکٹیریا کو نگل کر ختم کرتے ہیں۔\n\nمطالعے میں کیا ناپا گیا\nمحققین نے عمومی بے ہوشی کے دوران 15 ایسے افراد کا موازنہ کیا جنہوں نے کبھی سگریٹ نہیں پیا، 15 موجودہ سگریٹ نوشوں کا، اور 41 سابق سگریٹ نوشوں کا جو 2 ماہ، 3–5 ماہ یا 6–12 ماہ سے سگریٹ سے پاک تھے۔\n\nبحالی کی ایک ٹھوس علامت\nبے ہوشی کے دوران الویولر میکروفیجز کی فاگوسائٹوسس اور بیکٹیریا مارنے کی سرگرمی میں کمی موجودہ سگریٹ نوشوں اور دو ماہ سے چھوڑنے والوں میں کبھی نہ پینے والوں کی نسبت 1.5–3 گنا زیادہ تھی۔ 3–12 ماہ تک سگریٹ سے پاک گروپوں میں جراثیم کش ردِعمل دو ماہ والے گروپ کی نسبت کبھی نہ پینے والوں کے نمونے کے زیادہ قریب تھے۔\n\nسوزش سے متعلق سگنلنگ نسبتاً آہستہ بحال ہوئی، اور سائٹو کائن ردِعمل میں فرق چھ ماہ تک دیکھا گیا۔ چھ ماہ پھیپھڑوں کی مدافعتی بحالی کا ایک حقیقی سنگِ میل ہے، اور بہتری آگے بھی جاری رہتی ہے۔';

  @override
  String get smokingReferenceDay365 =>
      'ایک سال : دل کا دورہ پڑنے سے نقصان ہوتا ہے\n\nماخذ: PMC — Smoking Cessation and Stroke Outcome; CDC, Benefits of Quitting Smoking\n\nاِس بیماری کی وجہ سے خون کی نالیوں کو متاثر کِیا جاتا ہے ، خون کی نالیوں میں اضافہ ہو جاتا ہے ، خون کے دباؤ میں اضافہ ہو جاتا ہے اور خون کی نالیوں کو نقصان پہنچتا ہے ۔ سی آئی سی سی کی خود مختاری ٹائم لائن 1-2 سال کے نشان پر دل کا دورہ پڑنے کے خطرے میں ڈال دیتی ہے —آپ اس کھڑکی کے سامنے کے کنارے پر ہیں۔\n\nدوبارہ سے وقت نکالنے\nمکمل طور پر زچگی کے نارمل معمولات میں زیادہ وقت لگتا ہے: حوالہ جات کے مطالعے نے تقریباً پانچ سالوں کے بعد سگریٹ پینے والوں کی نسبت ایک بامقصد طور پر کم تناؤ کی شرح ظاہر کرنے کے لیے معطل کر دیا اور سی بی سی ڈاٹا نے 3 سے 6 سال تک دل کی بیماریوں کے خطرے میں اضافہ کر دیا ہے۔\n\nایک سال اب بھی ایک حقیقی طبی میلہ ہے — انتہائی تیزی سے کمی کا سب سے زیادہ حصہ آپ کے پیچھے ہے، اگرچہ طویل عرصے سے زیادہ عرصے تک کینسر اور کینسر کے فوائد کی تعمیر جاری ہے۔';

  @override
  String get smokingReferenceDay1825 =>
      'پانچ سال: سرطان کے خطرے کے خلاف بڑی کامیابیاں شروع\n\nماخذ: CDC, Benefits of Quitting Smoking\n\nپانچ سال آپ کو خطرے میں بڑی کمی کے ایک اہم دور کے آغاز پر لے آتے ہیں۔\n\n5 سے 10 سال کے سنگِ میل\n• منہ، گلے اور حنجرے کے سرطانوں کا اضافی خطرہ: آدھا رہ جاتا ہے\n• فالج کا خطرہ: کم ہوتا ہے\n\nابھی آگے\n• تقریباً 10 سال: مثانے، غذائی نالی اور گردے کے سرطان کا خطرہ کم ہوتا ہے\n• 10–15 سال: پھیپھڑوں کے سرطان کا اضافی خطرہ آدھا رہ جاتا ہے\n• 15 سال: دل کی شریانوں کی بیماری کا خطرہ ایسے شخص کے قریب آ جاتا ہے جو سگریٹ نہیں پیتا\n• 20 سال: منہ، گلے اور حنجرے کے سرطان کا خطرہ غیر تمباکو نوش شخص کے قریب آ جاتا ہے؛ رحم کے منہ کے سرطان کا اضافی خطرہ تقریباً آدھا رہ جاتا ہے\n\nپانچ سال بغیر سگریٹ کے ایک بہت بڑا سنگِ میل ہے — آپ اس دور تک پہنچ گئے ہیں جہاں سرطان اور فالج کے خطرے میں بڑی کمی اثر دکھانا شروع کرتی ہے، اور مزید بڑی کامیابیاں ابھی آگے ہیں۔';

  @override
  String get snriReferenceDay3 =>
      'SNRI Discontinuation: پہلا دن ہے۔\n\nماخذ: Harvard Health Publishing\n\nاہم حفاظتی نکات\nایس‌آر‌ایس کو آہستہ آہستہ پائپ کے پیچھے طبّی نگرانی میں بند کر دیا جانا چاہئے ۔ Venlafaxine (Effexor) خاص طور پر تقریباً 5 گھنٹے کی انتہائی مختصر عمر رکھتا ہے، جس کا مطلب ہے دوا جسم سے خارج ہونے والی علامات بہت تیزی سے اور غیر متوقع ہو سکتی ہیں۔\n\nایس . اے .\nSNRIs دماغ کے دو کیمیائی مرکبات یعنی Sertonin اور Nadrenaline پر اثر انداز ہوتا ہے جس کا مطلب ہے کہ دونوں کو اُس وقت حل کرنے کی ضرورت ہے۔ ایس این آر آئیس سے اکثر اس سے زیادہ شدت اختیار کر لیتے ہیں:\n• ایسی علامات (fatigue, sulting, muscles aches)۔\n• بے ہوش اور پریشان نیند\n• ناکا — اکثراوقات ایس‌ایس‌آر کیساتھ زیادہ ذکر کِیا جاتا ہے\n• دل‌ودماغ پر اثر کریں\n• Sensory diseases — \'برین زپس‘ کو venlafaxine کے ساتھ بہت شدت سے کیا جا سکتا ہے۔\n• مایوسی ، پریشانی اور پریشانی\n\nاِس سے ظاہر ہوتا ہے کہ اُس کا ایمان مضبوط تھا ۔\nVenlafaxine اپنی مختصر سی نصف حیات کی وجہ سے سب سے مشکل ڈسکنیشن پروڈیوس کیا جاتا ہے۔ دولوکسیتین (Cymbalta) اپنی طویل مدتی زندگی کی وجہ سے کچھ آسان ہو جاتا ہے۔ دونوں کے درمیان ڈیسوینلافاکسین گرتا ہے۔';

  @override
  String get snriReferenceDay7 =>
      'ایک ہفتہ بعد SNRIS: دو دماغ-Chemical Systemsinging\n\nماخذ: NHS — Stopping or coming off antidepressants (general antidepressant guidance; the noradrenaline-specific mechanisms below reflect general SNRI pharmacology rather than SNRI-specific detail from the NHS page itself)\n\nدیول-سیستم چیلنج\nایک نظام پر اثرانداز ہونے والے بیشتر اینٹی باڈیز کے برعکس ، ایس‌آر‌ایس‌ایس دونوں سرتونین اور Nordrenaline پر اثرانداز ہوتے ہیں ۔ ایک ہفتے تک دونوں نظمیں غیر واضح ہو رہی ہیں:\n\nناردرنا لائن سسٹم اثرات\nنورادری لائن سسٹم جسم کے جہادی عمل، بلڈ پریشر اور توانائی کی سطح پر حکومت کرتا ہے۔ جیسا کہ یہ واضح کرتا ہے:\n• انتقالِ‌خون کے دباؤ میں تبدیلی واقع ہو سکتی ہے\n• پریشانی زیادہ جسمانی ( دل ، پس‌منظر ) محسوس کر سکتی ہے\n• توانائی کی مقدار کم ہو سکتی ہے\n\nسروٹون سسٹم اثرانداز ہوتے ہیں۔\nعام طور پر ، سروٹون کے نظام میں تبدیلی واقع ہو رہی ہے جس سے کسی بھی اینٹی‌باڈیز کو روکنے کی علامات پیدا ہو جاتی ہیں ۔ دونوں نظاموں کا ملاپ پہلے ہفتے کو خاص طور پر چیلنج کر سکتا ہے ۔\n\nجسمانی طور پر یہ بات اکثر یہ ظاہر کرتی ہے کہ خون کے دباؤ میں استحکام اور قائم رہنے کی کمی کو بہتر بناتی ہے ۔ جذباتی طور پر ، جذباتی طور پر 30 دن تک اس سے زیادہ تبدیل ہو جائے گا لیکن اب آزاد حالت میں نہیں ہوگا۔';

  @override
  String get snriReferenceDay14 =>
      'SNRIs کے بعد دو ہفتوں کا نظام : جسمانی طور پر لگنے والی مادہ‌سازی\n\nماخذ: Davies & Read (2019), Addictive Behaviors\n\nدو-ویک سٹیٹس\nزیادہ‌تر لوگوں کے لئے مناسب ٹیپ‌سازی کے بعد ، دو ہفتوں کے دوران جسمانی طور پر زیادہ‌تر مرحلے کو حل کِیا جاتا ہے :\n• دماغ کی حساسیت کم یا غائب ہو جاتی ہے\n• ناکا اور پھیپھڑے کی طرح کی علامات حل کرتی ہیں۔\n• مایوسی اور توازن کے مسائل بہتر ہوتے ہیں\n• خون کا دباؤ اور دل کا دورہ\n\nثابت‌قدم رہیں\n• جذباتی حساسیت اور ذہنی کیفیت\n• پریشان‌کُن پریشانی — جس کا نظام خاص طور پر اثرانداز ہوتا ہے\n• مایوسی ، جیسا کہ Nordrenaline نظام توانائی اور توانائی فراہم کرتا ہے\n\nتحقیقی مضامین\nاِس بات کی تصدیق کی گئی ہے کہ اِس بیماری میں مبتلا لوگوں کی تعداد کم ہوتی جا رہی ہے ۔';

  @override
  String get snriReferenceDay30 =>
      'SNRIs کے ایک مہینے بعد: Dublu Stabilising: Dublic System Stabiling\n\nماخذ: Davies & Read (2019), Addictive Behaviors — systematic review of antidepressant withdrawal incidence, severity, and duration\n\nدُنیا کا نظارہ کرنا\nایک مہینے میں سروتونن اور ناردرن‌لین کی بحالی میں ایک اہم سنگِ‌مس کی نمائندگی کرتا ہے ۔ اس جائزے سے پتہ چلا کہ جب لوگوں میں ایک حد تک کمی واقع ہوتی ہے تو چند ہفتوں سے آگے بڑھتی ہوئی دائمی اثرات کا تجربہ ہوتا ہے، زیادہ تر لوگ اس نقطہ نظر سے جسمانی کمزوری کی علامات کا سب سے بڑا مرحلہ گزرتا ہے۔\n\nایک مہینے میں کیا واقع ہوتا ہے\n• جسمانی کمزوریوں کی علامات (brain Zaps, symply, symption) زیادہ تر کیلئے حل کی جاتی ہیں۔\n• قدرتی سطح پر لوٹنے والے خون کا دباؤ\n• نیند میں بہتری — قدرتی طور پر نیند بحال کرنے کے نمونے\n• توانائی کی سطح کا عمل معمول کے مطابق شروع ہوتا ہے\n\nجذباتی ردِعمل\nاس مرحلے پر سب سے زیادہ معلومات پانے والے تجربات میں سے ایک جذباتی انتشار کا حل ہے ۔ جب دوا صاف ہو جاتی ہے اور دماغ کی نشوونما ہو جاتی ہے تو جذباتی فضا اور حساسیت بحال ہو جاتی ہے ۔';

  @override
  String get snriReferenceDay90 =>
      'SNRI چھوڑنے کے تین ماہ بعد: معمول کی واپسی کی مدت سے آگے\n\nماخذ: Fava وغیرہ (2018)، \"Withdrawal Symptoms after Serotonin-Noradrenaline Reuptake Inhibitor Discontinuation: Systematic Review\"، Psychotherapy and Psychosomatics\n\nSNRI چھوڑنے کی علامات عموماً کیسے چلتی ہیں\n61 رپورٹس — جن میں 22 ڈبل بلائنڈ بے ترتیب کنٹرولڈ ٹرائل شامل تھے — میں زیرِ مطالعہ ہر قسم کے SNRI کو چھوڑنے کے بعد علامات رپورٹ ہوئیں۔ علامات عموماً دوا بند کرنے کے چند دنوں میں شروع ہوئیں اور بتدریج خوراک کم کرنے کے باوجود چند ہفتے رہیں۔ رپورٹس میں venlafaxine کے ساتھ واپسی کی علامات کی شرح زیادہ نظر آئی۔\n\n90 واں دن کیوں اہم ہے\nنوے دن اس عام چند ہفتوں کے دورانیے سے بہت آگے ہیں۔ تین ماہ تک پہنچنے کا مطلب ہے کہ SNRI واپسی کی معمول کی مدت پیچھے رہ چکی ہے۔\n\nکچھ صورتوں میں علامات زیادہ دیر رہ سکتی ہیں\nجائزے میں دیر سے شروع ہونے والی یا زیادہ دیر قائم رہنے والی علامات بھی سامنے آئیں۔ اگر تین ماہ پر اہم علامات اب بھی موجود ہوں تو اپنے دوا تجویز کرنے والے معالج سے بات کریں۔';

  @override
  String get snriReferenceDay180 =>
      'SNRIS کے چھ مہینے بعد : دماغ اور دماغ کی دوبارہ نشوونما\n\nچھٹے منٹ کی ڈاٹ کام پر دوبارہ کنٹرولی اشارات پر۔\nایک مکمل ہونے کے چھ ماہ بعد ، طبّی طور پر نگرانی کرنے والا سخت ابتدائی دور آپ کے پیچھے ہے ۔ مودود، نیند، جنسی عمل اور واضح سوچ کو ٹھیک کرنے کے لیے کئی ماہ لگے ہیں:\n• سرونٹین راستے : بڑی تیزی سے بحال کِیا جاتا ہے\n• Noradrenaline راستے: نارمل، دباؤ کے رد عمل کے ساتھ ساتھ تناؤ کے نظام کو بھی قائم کیا جاتا ہے۔\n• نیند کی ترکیب: مکمل طور پر دوبارہ تعمیر ہونے کی توقع کی جائے۔\n• جنسی عمل: زیادہ تر لوگوں کے لیے دوبارہ بحال کیا گیا (انگریزی: SNRI activity) عام طور پر ایک SNRI side effect ہے، اگرچہ بعض کے لیے یہ عمل ثابت ہو سکتا ہے اور کسی مشیر کے ساتھ بات چیت کی جاسکتی ہے۔\n\nدباؤ کا مقابلہ کرنا\nبہتیرے لوگ چھ ماہ کی رپورٹ میں بیان کِیا گیا ہے کہ عام دباؤ کی وجہ سے اُن کے روزمرّہ کے دباؤ کو بہتر نہیں بنایا جا سکتا ۔';

  @override
  String get snriReferenceDay365 =>
      'ایس‌آر‌ایس کے ایک سال بعد : بحالیی تحصیل\n\nایک سال: ایک مکمل Daual-Systim Recupy -\nایک سال کے اندر اندر ایک ایس‌آری ٹیپ مکمل کرنے کے بعد ، سروٹون اور ناردرن لائن دونوں نظاموں میں مطابقت پیدا کرنے کیلئے ایک مکمل چکر موجود ہے ۔\n\nکیا ثبوت ایک سال میں واقعی معاون ثابت ہوتا ہے ؟\nاِس رسالے میں بتایا گیا ہے کہ کچھ ہی دنوں میں علامات بند ہو جاتی ہیں اور اِن میں سے زیادہ‌تر کا حل صرف دو ہفتوں کے اندر ہوتا ہے ۔ اس دور میں جس چیز کی اچھی طرح حمایت کی گئی ہے وہ اس دور میں کی گئی ہے:\n• جن لوگوں نے مناسب ٹیپیں مکمل کیں اور نفسیاتی حمایت حاصل کی ان کی اکثریت اچھی طرح برقرار رہتی ہے۔\n• زیادہ تر لوگوں کے لیے استعمال ہونے والی شخصیتوں کو مکمل طور پر حل کر چکی ہے۔\n• واضح سوچ، بشمول مرکزی مفادات جو SNRIS فراہم کرسکتے ہیں، قدرتی دماغی عمل کے ذریعے برقرار رکھے جاتے ہیں۔\n\nاس میلے کے پتھر کی علامت\nکامیاب طور پر کامیابی کیساتھ ایک SNRI — بالخصوص volafaxine — ایک اہم کامیابی ہے ۔ طبّی نگرانی کے تحت اِسے منظم کرنے کے لئے درکار معاہدے سے نہایت حیران‌کُن ثابت ہوتا ہے ۔';

  @override
  String get socialMediaReferenceDay1 =>
      'سوشل میڈیا سے واپس آنا : ایک دن\n\nماخذ: Lambert et al., \"Taking a One-Week Break from Social Media Improves Well-Being, Depression, and Anxiety: A Randomized Controlled Trial,\" Cyberpsychology, Behavior, and Social Networking (2022), on PubMed\n\nاس بات کا کیا ثبوت ہے ؟\nاس مضبوط کنٹرول شدہ مطالعے میں لوگوں کو یا تو فیس بک، فیس بک، ٹویٹر اور ٹیک ٹونک سے ایک ہفتے کی چھٹی لینے یا انہیں حسب معمول استعمال کرنے کی تفویض دی گئی تھی۔ ٹوٹ پھوٹنے والی جماعت نے حسن ابدال میں نمایاں بہتری ظاہر کی اور ڈپریشن اور پریشانی میں کمی واقع ہوئی۔ یہ سچ ہے کہ ایسے ثبوتوں پر قابو پانے سے ہمیں مدد ملتی ہے ۔\n\nاس بات کا کیا ثبوت ہے ؟\nسماجی میڈیا کے استعمال کا شدید تعلق کم مزاج اور زیادہ پریشانیوں سے ہے اور غیر متوقع آزمائشوں سے ظاہر ہوتا ہے کہ دانستہ طور پر لوٹ مار اچھی حالت میں بہتری لا سکتی ہے جب کہ ایک ہفتے کے اندر ڈپریشن اور پریشانی میں کمی واقع ہو سکتی ہے۔\n\nایک دن : انتظار کرنے کا کیا مطلب ہے ؟\n• مایوسی اور جانچنے کی کوشش\n• \'فنتوم‘ اطلاعات — ایسا احساس محسوس کرتے ہیں جو ایسا نہ ہوا ہو۔\n• جیسے جیسے آپ مستقل دباؤ میں تبدیلی لاتے ہیں\nیہ عام عادت سے تعلق رکھنے والے رجحانات ہیں اور یہ عارضی ہوتے ہیں۔ نمونے کو تسلیم کرنا اس میں تبدیلی لانے کا پہلا قدم ہے۔';

  @override
  String get socialMediaReferenceDay3 =>
      'سماجی میڈیا کے بغیر تین دن : پریشانی اور تشدد\n\nماخذ: Lambert et al., \"Taking a One-Week Break from Social Media Improves Well-Being, Depression, and Anxiety: A Randomized Controlled Trial,\" Cyberpsychology, Behavior, and Social Networking (2022), on PubMed\n\nشکستہ‌دلوں کی مدد کرنا\nاس کنٹرول مقدمے میں لوگوں نے سوشل میڈیا سے ایک ہفتے کے وقفے سے وابستہ لوگوں کو کم پریشانیوں اور افسردگی اور زیادہ خیر مقدموں سے ہفتہ ختم کر دیا۔ بھاری استعمال کی تکلیف کا بڑا حصہ سماجی مقابلے سے حاصل ہوتا ہے — دوسروں کے کام آنے والے نمایاں رجحانات کے خلاف اپنی حقیقی زندگی کا اندازہ لگا لیں — اور خوف زدہ آواز کی کم رفتار سے۔\n\n72 گھنٹے کے دوران کیا واقع ہوتا ہے۔\nجلد کے شروع میں عادت اب بھی بلند ہوتی ہے:\n• چیک کرنے کی شدید حوصلہ‌افزائی کرتے ہوئے ، اکثر معمول کے لمحات ( ورزش کرنے ، لائن میں انتظار کرنے ) سے فائدہ اُٹھاتے ہیں ۔\n• بعض کانٹوں اور مایوسی\n• کچھ لوگوں کے لیے، موازنہ کرنے والی پریشانیوں کا پہلا آغاز\n• پہلے سے شروع ہونے والے طومار کی عادت میں تبدیلی آنا شروع ہو گئی ہے۔\n\nکُل‌وقتی خدمت\nدوسروں کی توجہات کی مسلسل رعایت کیے بغیر، اس مقابلے میں جو بہت زیادہ سماجی میڈیا کی پریشانیوں کا ایندھن ہوتا ہے، اس میں ایندھن کم ہوتا ہے۔ مقدمے کے نتائج سے پتہ چلتا ہے کہ پہلے ہفتے کے آخر تک ان ابتدائی دائروں میں ذہنی کیفیت میں اضافہ ہوتا ہے — لہٰذا تین دن کے دوران تکلیف ایک ایسی تبدیلی کا سخت حصہ ہے جو ادا کرتی ہے ۔';

  @override
  String get socialMediaReferenceDay7 =>
      'ایک ہفتہ بغیر سوشل میڈیا کے: ناپنے کا پیمانہ\n\nماخذ: Lambert et al., \"Taking a One-Week Break from Social Media Improves Well-Being, Depression, and Anxiety: A Randomized Controlled Trial,\" Cyberpsychology, Behavior, and Social Networking (2022), on PubMed\n\nانصاف — اور یہ کام انجام دیتا ہے\nیہ محققین زیادہ تر براہ راست بات کرتے ہیں: مقدمے کی مداخلت ایک ہفتہ ٹوٹنے والی ایک تھی۔ سماجی میڈیا استعمال کرتے ہوئے رہنے والے لوگوں کے مقابلے میں، ٹوٹ پھوٹ جماعت نے صرف سات دن کے بعد کافی زیادہ ترقی یافتہ اور قابل قدر کم ڈپریشن اور پریشانی کا مظاہرہ کیا۔ ایک ہفتے کے اندر اندر اندر داخل ہونا اس حد تک پہنچ گیا ہے کہ ایک قابلِ‌رسائی مطالعے نے حقیقی فائدہ حاصل کِیا ۔\n\nعام طور پر لوگوں کی سوچ کیا ہے ؟\nلوگ اکثر اس بات کی رپورٹ دیتے ہیں :\n• زیادہ وقت — بہتیرے حیران ہیں کہ اُنہوں نے کتنے خرچ کئے تھے\n• جیسے کہ مسلسل توجہ سے چلنے والی سرگرمیوں کی عادت ہے۔\n• پیشگی کتاب کے بغیر آرام دہ شام اور آسان نیند سوتے ہیں۔\nیہ حاصلات حسن میں وسیع بہتری کے عین مطابق امتحان میں پیمائش کرتے ہیں۔\n\nجاری رہیں\nایک ہفتہ ایک حقیقی، ثبوت پیچھے ہٹ جانے والی میلہ ہے۔ اِس سے ظاہر ہوتا ہے کہ اُس کا مزاج ، وقت اور توجہ کا مرکز بن جاتا ہے ۔';

  @override
  String get socialMediaReferenceDay14 =>
      'دو ہفتے بے سوشل میڈیا: دو ویک گینز -\n\nماخذ: Coyne & Woodruff, \"Taking a Break: The Effects of Partaking in a Two-Week Social Media Digital Detox… among Young Adults,\" Behavioral Sciences (2023), on PubMed Central\n\nاس مطالعے کے بارے میں\nنوجوان بالغوں نے دو ہفتوں تک روزانہ تقریباً ۳۰ منٹ تک سوشل میڈیا کو محدود رکھا جس میں اُن کے فون پر استعمال کِیا گیا ( اُن کی تعداد 78% تھی ) ۔ فریقین نے سوشل میڈیا کے استعمال کو حد سے تجاوز کرتے ہوئے 78% کی مدد سے یہ میل براہ راست حقیقی امتحان دیا کہ کیا ہوتا ہے جب دو ہفتوں تک استعمال تیز رفتار سے کم ہوتا ہے۔\n\nکیا نتیجہ نکلا ؟\nدو ہفتوں کے دوران ساتھی کارکنوں نے بہتری ظاہر کی :\n• نیند — وقت اور کیفیت\n• زندگی سے خوشی\n• دباؤ\n• خوش‌دل بنیں\n• اسکوئر اسمارٹ فون اور سماجی میڈیا کی عادت کے توازن پر ہیں۔\nپیمائشی حاصلات کا جرمانہ تھا: طویل اور بہتر نیند، کم دباؤ، بہتر زندگی کی تسکین اور اچھی طرح سے محسوس کیا گیا اور کم اسمارٹ فون/سوکل-میڈین کی شرح میں کمی واقع ہوئی۔\n\nپناہ‌گزینوں کی دیکھ‌بھال\nتحقیق‌دانوں نے بھی غور کِیا کہ بعدازاں سابقہ سطحوں کی طرف لوٹ مار کا استعمال کرتے ہیں ۔ دو ہفتوں کا حقیقی فائدہ تو ہوتا ہے لیکن اس سے ظاہر ہوتا ہے کہ ایک منصوبہ کیوں — محض وقتی وقفہ — فائدہ — فائدہ‌مند ثابت ہوتا ہے ۔';

  @override
  String get socialMediaReferenceDay30 =>
      'سوشل میڈیا کے بغیر ایک مہینے میں : حقیقی تعلق گہرا ہے\n\nماخذ: Coyne & Woodruff, \"Taking a Break: The Effects of Partaking in a Two-Week Social Media Digital Detox… among Young Adults,\" Behavioral Sciences (2023), on PubMed Central\n\nجب آپ دوبارہ قدم اُٹھا سکتے ہیں تو اتصال بدل سکتا ہے\nاِس کے علاوہ ، بہتر زندگی کی تسکین اور کم دباؤ کے ساتھ ساتھ سوشل میڈیا کو صحیح طور پر ختم کرنے کے ساتھ ساتھ اِس میں بہتری آئی ۔ خوراک کی طرف جانے والے وقت اور توجہ دراصل آپ کی زندگی میں لوگوں کے لیے دستیاب ہو گئی۔\n\nکونسی چیز لا سکتی ہے\n30 دن تک ، بہت زیادہ کمزور چیک کرنے کی خودکار کشش کیساتھ ، بہتیرے لوگ تلاش کرتے ہیں :\n• مکالمے زیادہ تر موجود ہیں اور کم تاخیر کرتے ہیں۔\n• حقیقی دنیا کی سرگرمیوں میں زیادہ دلچسپی\n• خودی پسندی، تبصروں اور پیروکارانہ اقدار پر کم زور دیتے ہیں۔\n\nدوبارہ سے نشانات کو صاف کریں\nایک ماہ تک آپ نے مطالعے کی مداخلت کی کھڑکی کے لیے دو مرتبہ دیکھ بھال کے انداز کو برقرار رکھا۔ نیند، دباؤ، زندگی میں پیدا ہونے والی کشش، بہتری اور رشتے کے فوائد کا اندازہ دو ہفتوں میں ایک اور دو ہفتے ہو گئے ہیں\n\nوقت شمار کریں\nاِس کے علاوہ اِس بات پر بھی غور کریں کہ اِس دُنیا میں کون‌سی تبدیلیاں ہوتی ہیں ۔';

  @override
  String get socialMediaReferenceDay60 =>
      'سوشل میڈیا کے بغیر دو ماہ: ثبوت کیا معاونت کرتے ہیں۔\n\nماخذ: Ramadhan et al., \"Impacts of digital social media detox for mental health: A systematic review and meta-analysis,\" Narra J (2024), on PubMed Central\n\nسب سے قابلِ‌اعتماد تصویر\nتحقیق‌دانوں نے مل کر 10 مطالعے کیے جن میں سات کو کنٹرول کرنے والی آزمائشوں کا سامنا کرنا پڑتا ہے ۔ سب سے واضح نتیجہ سوشل میڈیا سے پیچھے ہٹ جانے کے بعد علامات میں کمی واقع ہوئی تھی ۔\n\nسب سے بڑا نتیجہ\nاِس تحقیق سے ظاہر ہوتا ہے کہ اِس کی علامات میں بہت کمی آئی ہے ۔ دو ماہ تک، آپ کو ایک ہی طرح کے ذیلی ڈیجیٹل حکمت عملی کی حمایت کر رہے ہیں جس کی وجہ سے ذہنی فوائد پیدا ہوئے۔\n\nدو ماہ کا چاند کیسا دکھائی دیتا ہے\nکم روزمرہ کے مقابلے اور کم خوراک پیدا کرنے کے ساتھ ساتھ خود کشی کی وجہ سے پسند، تبصرے یا پیروکار کی قدر پر انحصار کرنے کی بہت کم وجوہات ہیں جبکہ سب سے زیادہ پُل والے ثبوت اس بات کی نشان دہی کرتے ہیں کہ وہ ان علامات کو کم کرنے کی طرف اشارہ کرتے ہیں۔\n\nعملی مشورت\nاِس بات کا ثبوت ہمیں اِس بات سے ملتا ہے کہ ہم خدا کی مرضی پوری کرنے کے لئے تیار ہیں ۔ دو ماہ کے نقطہ نظر کا استعمال کریں کہ پیچھے ہٹ جانے کی بجائے حدود کو اپنی جگہ پر رکھیں اور معنی اور تعلق کے ماخذوں میں سرمایہ کاری کریں۔';

  @override
  String get socialMediaReferenceDay90 =>
      'سماجی میڈیا کے بغیر تین مہینے : ایک نیا معمول\n\nماخذ: Coyne & Woodruff, \"Taking a Break: The Effects of Partaking in a Two-Week Social Media Digital Detox… among Young Adults,\" Behavioral Sciences (2023), on PubMed Central\n\nنیند باقی ہے\nاس مطالعے کی واضح ترین دریافتوں میں نیند بھی بہتر ہو گئی — مستقل اور کیفیت — جب شرکاء نے سوشل میڈیا کو پیچھے سے کاٹ دیا۔ تین ماہ تک برقرار رہنے والی ایک مستقل‌مزاجی کے ذریعے ، نیند میں کھانے والی دیر کی کتابچے نے طویل عرصے سے آرام سے مقابلہ کرنا بند کر دیا ہے اور بہتر نیند جذبے ، توجہ اور توانائی کو اپنے ساتھ لے جانے کا باعث بنتی ہے ۔\n\nاِس بات کا کیا ثبوت ہے ؟\nاِسی مطالعے میں پریشانی ، زندگی کی تسکین ، اچھی صحت اور رشتوں کی حمایت پائی جاتی ہے ۔ تین مہینوں میں یہ نام‌ونشان نہیں ہوگا کیونکہ اُن کے پاس ایک نیا معمول قائم کرنے کا وقت ہے ۔\n\nمیکانیات پر دوبارہ سے دستخط\nسوشل میڈیا کو بے حد بہتر بنانے کے بعد ، دونوں نیند پوری کرنے اور مداخلت کے مطالعے میں سو جانے کی خوبی کو بہتر بنایا گیا ۔ تین ماہ تک قائم رہنے والی اس نمونے کی وجہ سے آدھی رات کیscrol کم نیند کی عادت میں کمی واقع ہو جاتی ہے۔\n\nقریبی اور تعلقات\nاِس کے علاوہ تین مہینے سے زیادہ عرصے تک آپ کے ساتھ جو بھی تعلقات مضبوط ہو گئے ہیں ، اُن کے ساتھ وقت گزارنے کے لیے فون پر زیادہ دیر تک بات‌چیت کرتے رہیں ۔';

  @override
  String get socialMediaReferenceDay180 =>
      'سماجی میڈیا کے بغیر چھ ماہ: واپسی کا اندازہ۔\n\nماخذ: Ramadhan et al., \"Impacts of digital social media detox for mental health: A systematic review and meta-analysis,\" Narra J (2024), on PubMed Central\n\nMeta-Analysis Addis\nتحقیق‌دانوں نے اِس بات پر غور کِیا کہ اِس میں کیا کچھ شامل ہے ۔\n\nاصل میں کیا ملا\n• ڈپریشن : کسی حد تک کمی ( واضح طور پر ، سب سے زیادہ فائدہ )\n• زندگی اطمینان : کوئی اہم اثر نہیں\n• دباؤ : کوئی اہم اثر نہیں\n• مکمل ذہنی فلاح و بہبود: کوئی قابلِ اثر نہیں۔\nسب سے مضبوط پولُس نتیجے کو واضح کرتا ہے : ڈیجیٹل ڈیوٹیکس بڑی حد تک علامات کو کم کرتا ہے ۔\n\nآپ ابھی تک بِلاوجہ فائدہ کیوں محسوس کر سکتے ہیں ؟\nچھ ماہ میں کم‌ازکم کم‌ازکم کم‌ازکم چند مداخلتوں میں استعمال ہونے والے عملی فوائد : زیادہ دستیاب وقت ، کم وقتی چیک کرنے اور اس سے متعلق ڈیجیٹل عمل میں کمی واقع ہونے لگتی ہے ۔\n\nخوراک پر قابو رکھیں\nسب سے بڑی کامیابی سنگین ، غیرضروری استعمال سے حاصل ہوتی ہے ۔ چھ ماہ تک سوشل میڈیا پر مقصدی طور پر آپ کی توجہ کو قابو میں رکھنے کی بجائے نیا بجٹ ہے۔';

  @override
  String get socialMediaReferenceDay365 =>
      'سوشل میڈیا کے بغیر ایک سال\n\nماخذ: Ramadhan et al., \"Impacts of digital social media detox for mental health: A systematic review and meta-analysis,\" Narra J (2024), on PubMed Central\n\nثابت‌قدم رہنے کا ایک سال\nسب سے مضبوط تحقیق ظاہر کرتی ہے کہ سوشل میڈیا سے پیچھے ہٹنے سے علامات کم ہو جاتی ہیں ۔ مکمل سال کا مطلب یہ ہوتا ہے کہ کم وقفہ کی بجائے نیچے والے نمونے آپ کا معمول بن گیا ہے۔\n\nکیا سال تعمیر کرتا ہے\nایک پورا سال آپ کو حقیقی رشتے ، صلاحیتوں ، سوچ‌بچار اور تخلیقی کاموں کے لئے سینکڑوں گھنٹے واپس بھیج دیتا ہے ۔ خودکار چیکنگ کو کمزور کرنے میں مکمل سال لگا ہے جبکہ ان غیرضروری معمولات کو مضبوط کرنے میں مکمل سال لگا ہے۔\n\nتسلی‌بخش فوائد\nسب سے واضح اندازہ لگایا گیا کہ ذہنی کمیت کی کمیت کم ہوتی ہے۔ آپ ہر روز خوراک کا انتظام کرتے رہتے ہیں ۔\n\nاسکے بعد کیا واقع ہوتا ہے\nاِس سلسلے میں ایک مثال پر غور کریں ۔ خواہ آپ محدود ، نصب‌اُلعین یا مکمل طور پر پیچھے ہٹ جاتے ہیں یا پھر کبھی‌کبھار ہی آپکا دل ٹوٹ جاتا ہے — اور یہ کامیابی بڑی کامیابی ہے ۔';

  @override
  String get ssriReferenceDay3 =>
      'SRI Discontinuation: پہلا دن\n\nماخذ: Harvard Health Publishing\n\nاہم حفاظتی نکات\nایس‌آر‌ایس کو آہستہ آہستہ پائپ کے پیچھے طبّی نگرانی میں بند کر دیا جانا چاہئے ۔ بالخصوص طویل استعمال کے بعد — خاص طور پر طویل استعمال کے بعد — کافی حد تک انسولین کی علامات کی شدت میں اضافہ ہوتا ہے ۔\n\nایس‌ایم‌ایس‌ایس کیا ہے ؟\nSRI Dichontinuation Memorial) ایک طبی عملہ ہے جس میں ایس آر آئی کو روکنے یا انتہائی کم کرنے کے دوران واقع ہوتا ہے۔ کلینک عام علامات کو بیان کرنے کے لیے اکرونیم فینش استعمال کرتے ہیں:\n• ایسی علامات (fatigue, sulting, muscles aches)۔\n• بے ہوش اور پریشان نیند\n• ناکا\n• دل‌ودماغ پر اثر کریں\n• sensory diseases — خاص طور پر \'برین زپس\' -\n• مایوسی ، پریشانی اور پریشانی\n\nنصف زندگی کے معاملات\nفیوزن (Prozac) 4–6 دن کی انتہائی طویل مدتی حیات رکھتا ہے، اس لیے یہ خود مختاری کو مؤثر طریقے سے پیدا کرتا ہے اور ہلکر ڈسکنیشن اثرات پیدا کرتا ہے۔ Paroxteintine (Paxil) عام ایس آر آئی کی سب سے مختصر زندگی ہے اور سب سے زیادہ شدت پسند ڈسکنیشن علامات پیدا کرتا ہے۔ سرٹالین، سیتالپورم اور ایسکیتالوپرام کے درمیان میں گرتا ہے۔';

  @override
  String get ssriReferenceDay7 =>
      'ایس‌آر‌ایس‌ایس کے بعد ایک ہفتے کا موسم : ای‌میلی پی‌سے\n\nماخذ: NHS — Stopping or coming off antidepressants\n\n[ صفحہ ۶ پر بکس / تصویر ]\nاین ایچ ایس کی دستاویزات جو زیادہ تر اینٹیائڈ فشنٹ ڈسکنیشن علامات بند ہونے کے پانچ دن کے اندر شروع ہوتی ہیں اور معاملات کی اکثریت میں چھ ہفتوں تک قائم رہتی ہے۔ ایک ہفتے تک ، جسمانی علامات انتہائی متاثر‌کُن ہو جاتی ہیں اور آہستہ‌آہستہ ٹیپ کرنے والوں کے لئے جلد ہی منتقل ہونا شروع ہو جاتی ہیں ۔\n\nایک ہفتہ کے آخر پر کیا واقع ہوگا\n• جسمانی علامات (nausea, symentity, fuil-asi) ان کی سب سے زیادہ شدت میں ہیں لیکن اسے آسانی سے شروع کرنا چاہیے۔\n• نیند کے مسائل جن میں روشن خواب یا بے خواب شامل ہیں عام ہیں۔\n• جذباتی کمزوری — جلد میں تبدیلی — اس مرحلے پر بار بار ہوتی ہے\n• دماغ کے زپ اب بھی موجود ہو سکتے ہیں لیکن اسکے باوجود آلودگی میں کمی کرنا شروع ہو جاتا ہے۔\n\nتپِ‌دق کا کردار\nاین‌ایچ‌ایس ایک سست رفتار ٹیپر کی شدید سفارش کرتا ہے — بعض‌اوقات لمبے عرصے تک صارفین — مہینوں سے بھی زیادہ عرصے کے لئے استعمال ہونے والے اشخاص — ملین سے زیادہ عرصے تک رہنے والے تھے ۔ شاہی کالج آف مشی گن کے ماہرین نے ایسے ہدایات تیار کی ہیں جو بہت آہستہ‌آہستہ پانی کی شکل‌وصورت کا استعمال کرتے ہیں کیونکہ اُن لوگوں کیلئے جو وسیع عرصے تک ایس‌آر‌ایس لیتے ہیں ۔';

  @override
  String get ssriReferenceDay14 =>
      'ایس‌آر‌ایس کے بعد دو ہفتوں کا آغاز : جسمانی طور پر لگنے والی بیماریوں میں اضافہ\n\nماخذ: Davies & Read (2019), Addictive Behaviors — \'A systematic review into the incidence, severity and duration of antidepressant withdrawal effects\'\n\nتحقیق سے کیا پتہ چلا ہے ؟\nاِس بات پر غور کرنے سے پتہ چلا ہے کہ اِن لوگوں میں سے تقریباً 56% ایسے لوگ ہیں جو اِن کے بارے میں سوچتے ہیں ۔ زیادہ‌تر لوگوں کے لئے ایک موزوں ٹیپ پر چلنے والا مشکل مرحلہ دو ہفتوں تک حل ہوتا ہے :\n• دماغ کی حساسیت کم یا غائب ہو جاتی ہے\n• ناکا اور پھیپھڑے کی طرح کی علامات حل کرتی ہیں۔\n• مایوسی اور توازن کے مسائل بہتر ہوتے ہیں\n• نیند معمول سے شروع ہوتی ہے۔\n\nری سیٹ سے خامیاں منتقل کرنا\nاِس کے علاوہ اِس بیماری کی وجہ سے اُن کی صحت خراب ہو جاتی ہے ۔ 2–4 ہفتوں کے بعد پیدا ہونے والے واقعات اور اصل صورت حال کی طرح اُن کے علاج کے بارے میں مزید تحقیق کی جاتی ہے ۔ آپ کے مشیر کے ساتھ اس فرق کی نگرانی کرنا اہم ہے۔';

  @override
  String get ssriReferenceDay30 =>
      'ایس . اے .\n\nماخذ: Haddad PM (2001), Drug Safety — \'Antidepressant Discontinuation Syndromes\'\n\nدُنیا کا نظارہ کرنا\nاِس جائزے میں ڈسکون‌ٹینویشن آن‌سیٹ کو تیزی سے بیان کِیا گیا ہے ، اِس کی روک‌تھام یا اِس کی کمی کے دنوں میں اِس بات پر غور کِیا گیا ہے کہ زیادہ‌تر ردِعمل نرم اور مختصر مدتی ہوتے ہیں ، بغیر کسی خاص علاج کے حل‌شُدہ ہوتے ہیں ۔ ایک مہینے میں اُس آتش‌فشاں پہاڑ سے گزرنے والی تبدیلی کی نمائندگی کی گئی ہے ۔\n\nایک مہینے میں جذباتی زمینیں\nایک ماہ میں جذباتی تبدیلیاں نگرانی کے لیے تبدیلی اور اہم ہیں:\n• بعض لوگ ذہنی طور پر جذباتی طور پر دماغ میں تبدیلیاں لانے لگتے ہیں — اس سے بہتر ہوتا ہے\n• دیگر نے محسوس کِیا کہ وہ کئی سالوں سے جذباتی طور پر محسوس نہیں کر رہے تھے\n• ہر شخص اور اُس کی بنیادی حالت مختلف ہوتی ہے\n\nعدم تعاون کی اہمیت\nتحقیق مسلسل یہ ظاہر کرتی ہے کہ سی بی ٹی (سی بی ٹی) اور دیگر ثبوتوں پر مبنی نفسیاتی بیماریوں کے علاج کے لیے انتہائی مؤثر ہے۔ ایک ماہ کا نشان ان معاونت کو یقینی بنانے کا بہترین وقت ہے۔';

  @override
  String get ssriReferenceDay90 =>
      'تین ماہ: دوا چھوڑنے کی علامات کا رخ بدلتا ہے\n\nماخذ: Duffy وغیرہ، \"Antidepressant medication to prevent depression relapse in primary care: the ANTLER RCT,\" Health Technology Assessment (2021)\n\n12 ہفتوں پر پیمائش\nANTLER میں بنیادی نگہداشت کے 478 مریضوں کو بے ترتیب گروپوں میں تقسیم کیا گیا۔ وہ کم از کم 9 ماہ سے اینٹی ڈپریسنٹس لے رہے تھے اور خود کو اتنا بہتر محسوس کر رہے تھے کہ دوا بند کرنے پر غور کر سکیں۔ وہ citalopram، sertraline، fluoxetine یا mirtazapine لے رہے تھے۔ دوا بند کرنے والے اور دوا جاری رکھنے والے گروپوں کے درمیان دوا چھوڑنے کی علامات کا فرق 12 ہفتوں پر سب سے زیادہ تھا اور بعد کی جانچوں میں کم ہو گیا۔\n\nیہ SSRI سنگِ میل کیوں بنتا ہے\nمطالعے کی چار ادویات میں سے تین — citalopram، sertraline اور fluoxetine — SSRI ہیں۔ مطالعے کے عام فہم خلاصے کے مطابق دوا بند کرنے کے بعد اضافی علامات زیادہ تر پہلے 3–4 مہینوں میں مرتکز تھیں۔\n\nتین ماہ مضبوط\n90واں دن اسی ناپے گئے موڑ پر آتا ہے۔ اس کے بعد علامات کا فرق کم ہوتا ہے، اس لیے تین ماہ بحالی کا ایک واضح اور حقیقی سنگِ میل ہیں۔ اگر ڈپریشن یا بے چینی شدت سے واپس آ رہی ہو تو اپنے نسخہ لکھنے والے معالج سے جلد رابطہ کریں۔';

  @override
  String get ssriReferenceDay180 =>
      'اینٹی ڈپریسنٹس بند کرنے کے چھ ماہ بعد: 65٪ افراد بہتر حالت میں رہے\n\nماخذ: Volkmann و دیگر (2026)، European Archives of Psychiatry and Clinical Neuroscience\n\nچھ ماہ کا ٹھوس نتیجہ\nاس مطالعے میں ایسے افراد کی پیروی کی گئی جن کا بڑا ڈپریشن قابو میں تھا اور وہ اینٹی ڈپریسنٹس بند کر رہے تھے۔ چھ ماہ کے نتائج رکھنے والے 83 شرکاء میں سے 54 — یعنی 65٪ — بہتر حالت میں رہے، جبکہ 29 میں ڈپریشن دوبارہ ظاہر ہوا۔\n\nیہ سنگِ میل کیوں اہم ہے\nچھ ماہ کا یہ باقاعدہ ناپا گیا نتیجہ طویل مدتی استحکام کا ایک حقیقی سنگِ میل بناتا ہے۔ مطالعے نے ترکِ دوا کی علامات کو ڈپریشن کے دوبارہ ظاہر ہونے سے الگ بھی جانچا، جس سے دونوں میں فرق کرنے میں مدد ملی۔\n\nاگر ڈپریشن کی علامات شدت سے واپس آ رہی ہوں تو جلد اپنے تجویز کنندہ سے رابطہ کریں۔';

  @override
  String get ssriReferenceDay365 =>
      'طویل مدتی اینٹی ڈپریسنٹ کے بعد ایک سال: ANTLER نے اصل میں کیا ناپا\n\nماخذ: Duffy اور ساتھی (2021)، Health Technology Assessment — ANTLER آزمائش\n\nآزمائش نے حقیقت میں کیا پایا\nANTLER نے برطانیہ کی بنیادی نگہداشت میں 478 بالغ افراد کو بے ترتیب گروپوں میں تقسیم کیا جو اتنے بہتر تھے کہ طویل مدتی اینٹی ڈپریسنٹ بند کرنے پر غور کر سکیں۔ 52 ہفتوں تک، دوا بند کرنے والے گروپ میں 56% افراد کو دوبارہ بیماری لوٹی، جبکہ دوا جاری رکھنے والے گروپ میں یہ شرح 39% تھی۔ وقت کے ساتھ دوبارہ بیماری لوٹنے کا hazard تقریباً دوگنا تھا (HR 2.06)، لیکن ایک سال میں دیکھی گئی اصل شرحیں 56% بمقابلہ 39% تھیں، دوگنی نہیں۔\n\nمکمل تصویر\nدوا بند کرنا کوئی بند گلی نہیں تھی: 44% افراد کو 52 ہفتوں کی آزمائش کے دوران دوبارہ بیماری نہیں لوٹی۔ تاہم اوسط نتائج جاری علاج کے حق میں تھے: دوا بند کرنے والے گروپ میں withdrawal کی علامات زیادہ تھیں اور 12 ماہ میں معیارِ زندگی کے مطابق ایڈجسٹ کیے گئے سال کم تھے۔ دوا بند کرنے کے لیے مقرر کیے گئے 39% افراد نے اپنا اصل اینٹی ڈپریسنٹ دوبارہ شروع کیا۔\n\nآپ کا ایک سالہ سنگِ میل\nاگر آپ دوا کے بغیر ایک سال تک پہنچ گئے ہیں اور اچھا محسوس کر رہے ہیں تو یہ بہت بڑی کامیابی ہے۔ ANTLER یہ نہیں کہتا کہ ہر شخص کو دوا جاری رکھنی چاہیے یا ہر شخص کو اسے بند کرنا چاہیے؛ یہ دکھاتا ہے کہ دوبارہ بیماری لوٹنے کے خطرے اور علاج کے فیصلوں کی انفرادی پیروی کیوں ضروری ہے۔ ضرورت پڑنے پر دوا دوبارہ شروع کرنا ایک طبی فیصلہ ہے، ناکامی نہیں۔';

  @override
  String get steroidsReferenceDay1 =>
      'Anabolic Steroids : پہلا دن\n\nماخذ: \"Common symptoms associated with usage and cessation of anabolic androgenic steroids in men,\" Best Practice & Research Clinical Endocrinology & Metabolism (2022)\n\nاِس کی ایک وجہ\nاِس جائزے میں اِس بات کا ذکر کِیا گیا ہے کہ دو موقعوں پر ظاہر ہوتا ہے ۔ سب سے پہلے ہمدرد اعصابی نظام کو ہارمون کی سطح کی بجائے منتقل کرتے ہوئے ۱– ۲ دن روک لیتے ہیں اور اس میں شامل ہو سکتے ہیں :\n• سر کا رنگ\n• ٹرک\n• زمین‌وآسمان\n• ناکا\n\nاِس کی کیا وجہ ہے ؟\nانابولک اسکیم بھی جسم کی خود ٹیسٹسٹرو کی پیداوار کو دبا دیتی ہے — دماغ عام طور پر اسے چلانے والے برقی اشاروں کو دریافت کرتا ہے اور بند کر دیتا ہے۔ یہ رکاوٹ رکنے کے بعد بھی قائم رہتی ہے، دوسرا، طویل عرصے تک جاری رہنے والا مرحلہ جو بعد کے میلوں میں بیان کیا گیا ہے۔\n\nایک محفوظ نوٹ\nاگر آپ ڈپریشن کا شکار ہیں تو آپ اِس بیماری میں مبتلا ہو سکتے ہیں ۔ طبی امداد کی تلاش کریں اور خود غرضی کے کسی بھی خیال کے لیے فوری مدد کریں۔ بعض ڈاکٹر اِس کی حمایت کرنے کے لیے دوائیں استعمال کرتے ہیں ۔';

  @override
  String get steroidsReferenceDay14 =>
      'دو ہفتوں کا انابولک اسٹریائڈس\n\nماخذ: \"Common symptoms associated with usage and cessation of anabolic androgenic steroids in men,\" Best Practice & Research Clinical Endocrinology & Metabolism (2022)\n\nاِس کے نتیجے میں اُن کے دل میں اُن کے لیے محبت بڑھتی ہے ۔\nدو ہفتوں تک ابتدائی دنوں کی مختصر ہمدرد علامات گزر چکی ہیں اور تجزیہ کے دوسرے مرحلے — جاری ٹیسٹسٹرن کمیت — زیادہ نمایاں ہیں:\n• مایوسی اور افسردگی\n• مسکل آچے (myalgia)\n• خالی‌نظر\n• اُس نے کہا : ” مَیں اِس بات کو تسلیم کرتا ہوں کہ مَیں نے اُس کی بات مان لی ہے ۔ “\n\nابھی تک ادنیٰ ایبک پر\nقدرتی ٹیسٹسٹرون پروڈکشن کو دوبارہ پیدا کرنے کے لیے دو ہفتے سے زیادہ عرصہ درکار ہوتا ہے، اس لیے یہ مرحلے کی توقع کی جاتی ہے نہ کہ کسی بات کی نشان دہی غلط ہو۔\n\nایک مشہور واقعہ\nبعض مرد اس خلا سے بچنے کیلئے خاص طور پر استعمال کرتے ہیں — ایک ایسا چکر جو اسے ختم کرنے کی بجائے بحالی گھڑی کو دوبارہ شروع کر دیتا ہے ۔ ڈاکٹر یا ڈاکٹر سے مدد حاصل کرنے سے اس مرحلے کو مزید بہتر بنانے میں مدد ملتی ہے ۔';

  @override
  String get steroidsReferenceDay30 =>
      'ایک مہینے میں انابولک اسٹریائڈس کا شکار ہو جاتے ہیں۔\n\nماخذ: \"Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review,\" on PubMed\n\nدوبارہ سے کوشش\nروکنے کے بعد ہارمون کے سگنل جو ٹیسٹسٹرون کو ٹیسٹ کرنے کے لیے بتاتے ہیں، واپس واپس آنے لگتے ہیں۔ محققین اس بحالی کا بہت زیادہ حصہ تین سہ ماہی مدت میں لگا دیتے ہیں، اس لیے ایک ماہ بعد ہی یہ عمل پہلے ہی جاری ہو جاتا ہے۔\n\nکس بات کی توقع کریں ؟\nاِس کے علاوہ جب ہارمونز پیچھے چڑھ جاتے ہیں تو اُن میں بہت سی توانائی ہوتی ہے ۔ بحالی کا انحصار عمر پر ہے اور استعمال کتنا بھاری اور طویل تھا۔';

  @override
  String get steroidsReferenceDay90 =>
      'تین ماہ کی انابولک اسٹریائڈس سے باہر\n\nماخذ: \"Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review,\" on PubMed\n\nخون کی آزمائش کا اچھا وقت\nتین ماہ تک ہارمون سسٹم کو بامقصد بحالی کا وقت مل گیا ہے ۔ یہ ایک مفید بات ہے کہ اپنے ڈاکٹر سے سوال کریں کہ آپ ٹیسٹسٹرون اور اس پر قابو پانے والے ہارمونز کو چیک کرنے کے لئے.\n\nکس بات کی توقع کریں ؟\nتین مہینوں کے دوران بہتیرے مردوں کے لئے سطحِ‌زمین پر چڑھنے کی بجائے کوئی معمول قائم نہیں ہو رہا ہے ۔ مودود اور لیبیدو اکثر ٹیسٹیٹرون کو مکمل طور پر پکڑنے سے پہلے بہتر ہوتے ہیں۔ ٹیسٹ‌کیل سائز اور سیزن کی پیداوار زیادہ آہستہ ختم ہو جاتی ہے اور اگلے سال میں بہتری لا سکتی ہے ۔ اِس بیماری کی وجہ سے اِس بیماری میں مبتلا مریضوں کی تعداد کم ہو جاتی ہے ۔';

  @override
  String get steroidsReferenceDay180 =>
      'چھ ماہ کے بعد انابولک اسٹریائڈس کو ختم کر دیا گیا۔\n\nماخذ: \"Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review,\" on PubMed\n\nکہاں ثبوت\nاس جائزے میں بتایا گیا ہے کہ ایل‌ایچ اور ایف‌ایس‌ایچ — ٹیسٹ‌اِن کو ٹیسٹ کرنے کیلئے ٹیسٹ کرنے والے ہارمونز — عام طور پر تین سے چھ ماہ کے اندر اندر واپس آ جاتے ہیں ۔ چھ ماہ تک ، خود ٹیسٹ‌سٹرون بھی اپنے بحالی کے راستے سے اچھی طرح واقف ہے ۔\n\nاگر آپ ابھی نہیں ہیں تو\nاگر یہ علامات ابھی تک چھ ماہ میں موجود ہیں تو ایک فارغ التحصیل شخص آپ کے انتظار میں آنے کی بجائے علاج کا جائزہ لے سکتا ہے ۔';

  @override
  String get steroidsReferenceDay365 =>
      'انابولک سٹیرائڈز کے بغیر ایک سال\n\nماخذ: \"Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review,\" Endocrine Connections (2023)\n\nایک سال آزاد\nAAS کے بعد بحالی میں بہت فرق ہوتا ہے۔ اس جائزے کے مطابق ٹیسٹوسٹیرون کی تقریباً مکمل بحالی کئی مہینوں میں دیکھی جاتی ہے، گوناڈوٹروپن تقریباً تین سے چھ ماہ میں بحال ہوتے ہیں، جبکہ خصیوں کے حجم اور اسپرم کی پیداوار کی بحالی مہینوں سے برسوں تک جاری رہ سکتی ہے۔ نفسیاتی بحالی کی پیش گوئی کرنا زیادہ مشکل ہے۔\n\nایک سال واقعی اہم ہے\nسٹیرائڈز کے بغیر پورا ایک سال ایک بہت بڑا سنگِ میل ہے، لیکن یہ ایسا عالمی وقت نہیں جب ہر شخص کے ہارمون لازماً معمول پر آ جائیں۔ اگر کم ٹیسٹوسٹیرون کی علامات برقرار ہوں تو ماہر کی جانچ بتا سکتی ہے کہ بحالی کہاں تک پہنچی ہے۔';

  @override
  String get steroidsReferenceDay730 =>
      'انابولک سٹیرائڈز کے بغیر دو سال\n\nماخذ: \"Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review,\" Endocrine Connections (2023)\n\nدو مضبوط سال\nسٹیرائڈز کے بغیر دو سال دوبارہ استعمال کے بغیر ایک طویل عرصہ ہے۔ بحالی عمر اور پہلے اینڈروجن کے استعمال کی مقدار جیسے عوامل کے مطابق مختلف ہوتی ہے؛ دو سال کی کوئی ایسی عالمی حد نہیں جس تک ہر شخص کے ہارمون لازماً معمول پر آ جائیں۔\n\nطویل سفر\nاس جائزے کے مطابق ٹیسٹوسٹیرون کی بحالی کئی مہینوں میں اور گوناڈوٹروپن کی بحالی تقریباً تین سے چھ ماہ میں ہوتی ہے، جبکہ خصیوں کے حجم اور اسپرم کی پیداوار میں بہتری مہینوں سے برسوں تک جاری رہ سکتی ہے۔ کم ٹیسٹوسٹیرون کی مسلسل علامات کے لیے ماہر سے معائنہ کروائیں — ایک اور سٹیرائڈ سائیکل نہیں۔';

  @override
  String get tcaReferenceDay3 =>
      'TCA بند کرنا: ابتدائی دن — کولینرجک ری باؤنڈ\n\nماخذ: Dilsaver, Feinberg & Greden (1983), American Journal of Psychiatry — \'Antidepressant withdrawal symptoms treated with anticholinergic agents\' (3 مریضوں کی کیس رپورٹ)\n\nTCA بند کرنا مختلف کیوں محسوس ہو سکتا ہے\nبہت سے TCA سیروٹونن اور نورایڈرینالین پر اثر کے ساتھ اینٹی کولینرجک اثرات بھی رکھتے ہیں۔ شائع شدہ تین کیسز میں اچانک بند کرنے یا تیزی سے خوراک کم کرنے کے بعد واپسی کی علامات اینٹی کولینرجک علاج سے بہتر ہوئیں، جس کی بنیاد پر مصنفین نے مرکزی کولینرجک زیادہ سرگرمی کو ایک ممکنہ طریقۂ کار قرار دیا۔\n\nTCA واپسی میں رپورٹ ہونے والی علامات\n• متلی، قے، اسہال، پیٹ درد اور بھوک کم ہونا\n• بے خوابی یا نیند کی دوسری خرابیاں\n• بے چینی، اضطراب اور چڑچڑاپن\n• سر درد اور دوسری جسمانی علامات\n\nوقت ہر شخص میں مختلف ہوتا ہے\nواپسی کی علامات جلد آ سکتی ہیں، خاص طور پر اچانک بند کرنے یا تیزی سے خوراک کم کرنے کے بعد۔ تین مریضوں کی یہ کیس رپورٹ کولینرجک ری باؤنڈ کو ایک طریقۂ کار کے طور پر سہارا دیتی ہے۔ یہ مطالعہ روز بہ روز ایک مقررہ ٹائم لائن بنانے یا مختلف TCA کو ری باؤنڈ کی شدت کے لحاظ سے موازنہ کرنے کے لیے نہیں بنایا گیا تھا۔';

  @override
  String get tcaReferenceDay7 =>
      'TCA بند کرنے کے ایک ہفتے بعد: پہلا مرحلہ طے\n\nایک ہفتے کا مطلب\nNHS کے مطابق اینٹی ڈپریسنٹ کی واپسی کی علامات عموماً چند دنوں میں شروع ہوتی ہیں اور کئی ہفتے رہتی ہیں۔ کچھ لوگوں میں یہ شدید ہو سکتی ہیں یا مہینوں یا اس سے زیادہ عرصے تک رہ سکتی ہیں۔\n\nوہ علامات جو اب بھی موجود ہو سکتی ہیں\n• سر درد اور پٹھوں میں درد\n• متلی اور پسینہ\n• دل کا تیز، پھڑپھڑاتا، زور سے یا وقفہ چھوڑ کر دھڑکنا\n• چکر یا عدم توازن\n• نیند کے مسائل، عجیب خواب اور تھکن\n• بے قراری، چڑچڑاپن، بے چینی، اداس مزاج یا سوچنے میں مشکل\n\nسات دن پیش رفت ہیں\nTCA کے بغیر پورا ایک ہفتہ جشن کے لائق ہے۔ NHS کے مطابق واپسی کی علامات کئی دنوں سے کئی ہفتوں تک، اور بعض اوقات اس سے زیادہ، رہ سکتی ہیں؛ اس لیے دل کی رفتار، ہاضمہ، نیند اور دوسری خودکار جسمانی علامات مختلف رفتار سے کم ہو سکتی ہیں۔';

  @override
  String get tcaReferenceDay14 =>
      'TCA چھوڑنے کے دو ہفتے بعد: شدید انخلا عموماً کم ہونا شروع ہو جاتا ہے\n\nعام شدید دور\nاینٹی ڈپریسنٹ انخلا سنڈروم پر ایک طبی جائزہ بتاتا ہے کہ عام علامات — جن میں فلو جیسی علامات، بے خوابی، متلی، توازن کی خرابی، حسی علامات اور زیادہ بیداری شامل ہیں — عموماً ایک سے دو ہفتے رہتی ہیں۔\n\n14ویں دن کا مطلب\nدو ہفتوں پر بہت سے لوگ کلاسیکی شدید انخلا کے آخری حصے میں پہنچ رہے ہوتے ہیں۔ پہلی لہر کی علامات اس وقت تک اکثر خاصی کم ہو چکی ہوتی ہیں۔\n\nTCA کے بغیر چودہ دن\nیہ دن 14 کو ایک حقیقی بحالی کا نشان بناتا ہے: شدید انخلا کی لہر اکثر ٹوٹ رہی ہوتی ہے اور سب سے مشکل ابتدائی حصہ پیچھے رہنے لگتا ہے۔';

  @override
  String get tcaReferenceDay30 =>
      'TCA بند کرنے کے ایک ماہ بعد: شدید ترک کی علامات عموماً تھم چکی ہیں\n\nعام شدید مرحلہ\nWarner اور ساتھیوں کے مطابق اینٹی ڈپریسنٹ بند کرنے کی علامات عموماً ہلکی ہوتی ہیں اور ایک سے دو ہفتے رہتی ہیں۔ TCA کو واضح طور پر شامل کیا گیا ہے، اور TCA بند کرنے کے بعد توازن اور حرکت کے مسائل نسبتاً نمایاں ہو سکتے ہیں۔\n\nدن 30 کا مطلب\nایک ماہ پر زیادہ تر لوگ عام شدید مرحلے سے کافی آگے نکل چکے ہوتے ہیں۔ فلو جیسی علامات، متلی، توازن کی خرابی، بے خوابی، حسی تبدیلیاں اور حد سے زیادہ بے چینی عموماً کافی کم یا ختم ہو چکی ہوتی ہیں۔\n\nتیس مضبوط دن\nTCA کے بغیر ایک ماہ صحت یابی کا واضح سنگ میل ہے: شدید ترک کا روایتی مرحلہ عموماً آپ کے پیچھے رہ جاتا ہے۔';

  @override
  String get tcaReferenceDay90 =>
      'TCA بند کرنے کے تین ماہ بعد: شدید ترک کا مرحلہ بہت پیچھے رہ گیا\n\nعام شدید مرحلہ\nWarner اور ساتھیوں کے مطابق اینٹی ڈپریسنٹ بند کرنے کی علامات عموماً ہلکی ہوتی ہیں اور ایک سے دو ہفتے رہتی ہیں۔ TCA کو واضح طور پر شامل کیا گیا ہے، اور TCA بند کرنے کے بعد توازن اور حرکت کے مسائل نسبتاً نمایاں ہو سکتے ہیں۔\n\nدن 90 کا مطلب\n90 دن پر آپ عام شدید مرحلے کی بالائی حد سے دس ہفتے سے بھی زیادہ آگے ہوتے ہیں۔ اگر آپ کو فلو جیسی علامات، متلی، توازن کی خرابی، بے خوابی، حسی تبدیلیاں اور حد سے زیادہ بے چینی جیسی ابتدائی کلاسیکی علامات ہوئی تھیں تو وہ عموماً بہت پہلے کافی کم یا ختم ہو چکی ہوتی ہیں۔\n\nنوّے مضبوط دن\nTCA کے بغیر تین ماہ صحت یابی کا واضح سنگ میل ہے: شدید ترک کا مرحلہ عموماً بہت پیچھے رہ گیا ہوتا ہے۔ اگر ڈپریشن کی نمایاں علامات واپس آئیں تو جلد اپنے ڈاکٹر سے رابطہ کریں۔';

  @override
  String get tcaReferenceDay180 =>
      'اینٹی ڈپریسنٹ بند کرنے کے چھ ماہ بعد: زیادہ تر افراد دوبارہ ڈپریشن کے بغیر رہے\n\nچھ ماہ کا دوبارہ ڈپریشن چیک پوائنٹ\n2024 کے ایک میٹا تجزیے میں بڑے ڈپریشن کے علاج کے بعد اینٹی ڈپریسنٹ بند کرنے کی 35 بے ترتیب آزمائشیں شامل کی گئیں۔ بند کرنے کے چھ ماہ بعد مجموعی دوبارہ ڈپریشن کی شرح 34.81% تھی—یعنی تقریباً 65% افراد اس وقت تک دوبارہ ڈپریشن کے بغیر رہے۔\n\nایک حقیقی طویل مدتی نتیجہ\nاسی تجزیے میں 12 ماہ پر دوبارہ ڈپریشن کی شرح 45.12% تھی۔ چھ ماہ استحکام کا ایک اہم مرحلہ ہے: مجموعی آزمائشوں میں زیادہ تر شرکاء اس وقت تک دوبارہ ڈپریشن کا شکار نہیں ہوئے تھے۔\n\nاپنی پیش رفت کو محفوظ رکھیں\nاگر ڈپریشن کی علامات واپس آنا شروع ہوں تو جلد اپنے معالج سے رابطہ کریں۔ چھ ماہ تک پہنچنا استحکام کا ایک بڑا دور ہے جسے محفوظ رکھنا اہم ہے۔';

  @override
