  @override
  String get vapingDay1Description =>
      'ویپ کے بغیر پہلا دن۔ اگر آپ کے ویپ میں نکوٹین تھی تو شدید طلب، چڑچڑاپن، بے چینی، اداس مزاج، خراب نیند یا توجہ میں دھندلاپن نکوٹین واپسی کی علامات ہو سکتی ہیں — اسے دوبارہ نکوٹین دینے کی وجہ نہیں۔ بہرحال آپ ویپنگ کا چکر توڑ رہے ہیں۔';

  @override
  String get vapingDay3Description =>
      'ویپ کے بغیر تین دن۔ روزانہ ای سگریٹ استعمال کرنے والے سابق تمباکو نوشوں کی ایک کلینیکل تحقیق میں اوسط علاماتِ ترک پہلے یا دوسرے دن عروج پر پہنچیں، پھر اگلے چار دنوں میں کم ہوتی رہیں۔ اب آپ اس تحقیق کی ابتدائی عروج والی مدت سے آگے ہیں؛ طلب اب بھی آ سکتی ہے، مگر کنٹرول اس کے ہاتھ میں نہیں۔';

  @override
