  @override
  String get vapingWithdrawalReference =>
      'ای سگریٹ سے پرہیز اور واپسی کی علامات\n\nماخذ: Hughes et al., Nicotine & Tobacco Research (2020)\n\nروزانہ ای سگریٹ استعمال کرنے والے 109 سابق تمباکو نوشوں میں، حیاتیاتی طور پر تصدیق شدہ چھ دن کے پرہیز سے نکوٹین واپسی کی علامات اور طلب میں اضافہ ہوا۔ علامات نے واپسی کا عام اوپر-نیچے والا انداز دکھایا، اور پہلے دو دنوں میں واضح اضافہ ہوا۔ تحقیق ای سگریٹ کی حقیقی واپسی کی تائید کرتی ہے، مگر سب کے لیے ایک جیسی روزانہ بحالی کی گھڑی مقرر نہیں کرتی۔';

  @override
  String get vapingHealthReference =>
      'ویپنگ آپ کو کن چیزوں کے سامنے لاتی ہے\n\nماخذ: CDC — Health Effects of Vaping\n\nCDC کے مطابق زیادہ تر ای سگریٹس میں عادت ڈالنے والی نکوٹین ہوتی ہے۔ ویپ ایروسول میں نکوٹین، سرطان پیدا کرنے والے کیمیکل، نکل، ٹِن اور سیسہ جیسی بھاری دھاتیں، پھیپھڑوں کی گہرائی تک جانے والے باریک ذرات، فرار پذیر نامیاتی مرکبات اور بعض نقصان دہ فلیورنگ کیمیکل ہو سکتے ہیں۔ نکوٹین واپسی میں چڑچڑاپن، بے چینی، اداس مزاج، نیند اور توجہ کے مسائل، بھوک اور طلب شامل ہو سکتے ہیں اور یہ علامات وقت کے ساتھ کم ہوتی ہیں۔ ویپنگ کے طویل مدتی اثرات ابھی زیرِ تحقیق ہیں، اس لیے Quitter حقیقی پرہیز کو مناتا ہے، سگریٹ کے کاربن مونو آکسائیڈ، ٹار، کینسر یا دل کے خطرے والے اوقات کو نقل نہیں کرتا۔';
}
